def judge_11_color_paired_animation_anchors(
    vertices: np.ndarray,
    anchors_11: Dict[str, np.ndarray],
    min_medial_interiority: float = 0.92,
    min_single_anchor_interiority: float = 0.85,
    min_bilateral_limb_symmetry: float = 0.85,
) -> Dict[str, Any]:
    """
    Juge la précision anatomique des 11 points d'ancrage d'animation par paires de couleurs :
    - `head`, `pelvis` (axe médian)
    - `shoulder_l/r`, `elbow_l/r`, `wrist_l/r`, `knee_l/r`, `foot_l/r` (5 paires bilatérales)
    Vérifie :
    1. La présence des 11 ancres canoniques.
    2. Le centrage médial de chaque ancre dans la coupe locale du maillage (`interiority >= 0.92`).
    3. La symétrie bilatérale et la hiérarchie verticale (`head > shoulder > pelvis > knee > foot`).
    """
    required_keys = [
        "head",
        "shoulder_l",
        "shoulder_r",
        "elbow_l",
        "elbow_r",
        "wrist_l",
        "wrist_r",
        "pelvis",
        "knee_l",
        "knee_r",
        "foot_l",
        "foot_r",
    ]
    # Note: 12 clés quand pelvis est inclus avec les 5 paires + head, ou 11 avec pelvis/root unifié
    present = [k for k in required_keys if k in anchors_11]
    if len(present) < 11 or len(vertices) < 100:
        return {
            "passed": False,
            "medial_interiority_score": 0.0,
            "present_anchor_count": len(present),
        }

    bmin = vertices.min(axis=0)
    bmax = vertices.max(axis=0)
    span = np.maximum(bmax - bmin, 1e-6)
    slice_radius = 0.09 * float(np.max(span))

    interiority_scores: List[float] = []
    for key in present:
        pt = np.asarray(anchors_11[key], dtype=np.float64)
        dists = np.linalg.norm(vertices - pt[None, :], axis=1)
        local_mask = dists <= slice_radius
        if int(np.sum(local_mask)) < 8:
            # Plus proche voisin si coupe fine (ex: poignet/cheville)
            nearest_k = np.argsort(dists)[:24]
            local_verts = vertices[nearest_k]
        else:
            local_verts = vertices[local_mask]
        local_center = np.mean(local_verts, axis=0)
        local_half_extent = 0.5 * float(np.max(np.ptp(local_verts, axis=0)) + 1e-3)
        offset_ratio = min(
            1.0,
            float(np.linalg.norm(pt - local_center)) / max(local_half_extent * 2.5, 1e-3),
        )
        interiority_scores.append(max(0.0, 1.0 - 0.35 * offset_ratio))

    mean_interiority = float(np.mean(interiority_scores))
    min_anchor_interiority = float(np.min(interiority_scores))
    # Hiérarchie anatomique verticale (axe Y ou Z selon l'extension verticale) sur les 2 chaînes G et D
    up_axis = 1 if span[1] >= span[2] else 2
    hierarchy_ok = bool(
        anchors_11["head"][up_axis] > anchors_11["shoulder_l"][up_axis]
        and anchors_11["head"][up_axis] > anchors_11["shoulder_r"][up_axis]
        and anchors_11["shoulder_l"][up_axis] > anchors_11["pelvis"][up_axis]
        and anchors_11["shoulder_r"][up_axis] > anchors_11["pelvis"][up_axis]
        and anchors_11["pelvis"][up_axis] > anchors_11["knee_l"][up_axis]
        and anchors_11["pelvis"][up_axis] > anchors_11["knee_r"][up_axis]
        and anchors_11["knee_l"][up_axis] >= anchors_11["foot_l"][up_axis]
        and anchors_11["knee_r"][up_axis] >= anchors_11["foot_r"][up_axis]
    )
    # Séparation bilatérale gauche/droite
    bilateral_pairs = [
        ("shoulder_l", "shoulder_r"),
        ("elbow_l", "elbow_r"),
        ("wrist_l", "wrist_r"),
        ("knee_l", "knee_r"),
        ("foot_l", "foot_r"),
    ]
    pair_separations = [
        float(np.linalg.norm(np.asarray(anchors_11[l_k]) - np.asarray(anchors_11[r_k])))
        for l_k, r_k in bilateral_pairs
    ]
    bilateral_ok = bool(min(pair_separations) >= 0.05 * float(span[0]))
    limb_segments = [
        ("shoulder_l", "elbow_l"),
        ("elbow_l", "wrist_l"),
        ("shoulder_r", "elbow_r"),
        ("elbow_r", "wrist_r"),
        ("pelvis", "knee_l"),
        ("knee_l", "foot_l"),
        ("pelvis", "knee_r"),
        ("knee_r", "foot_r"),
    ]
    segment_lengths = [
        float(np.linalg.norm(np.asarray(anchors_11[a_k]) - np.asarray(anchors_11[b_k])))
        for a_k, b_k in limb_segments
    ]
    min_bone_segment_length_mm = float(min(segment_lengths))
    segments_non_degenerate = bool(min_bone_segment_length_mm >= 0.06 * float(np.max(span)))
    # Symétrie cinématique homologue des proportions de segments G/D (invariante d'échelle pour duo Zig & Sharko / pinces asymétriques Bernie)
    axial_segment_lengths = [
        float(abs(float(anchors_11[a_k][up_axis]) - float(anchors_11[b_k][up_axis])))
        for a_k, b_k in limb_segments
    ]
    arm_prop_l = axial_segment_lengths[0] / max(axial_segment_lengths[0] + axial_segment_lengths[1], 1e-6)
    arm_prop_r = axial_segment_lengths[2] / max(axial_segment_lengths[2] + axial_segment_lengths[3], 1e-6)
    leg_prop_l = axial_segment_lengths[4] / max(axial_segment_lengths[4] + axial_segment_lengths[5], 1e-6)
    leg_prop_r = axial_segment_lengths[6] / max(axial_segment_lengths[6] + axial_segment_lengths[7], 1e-6)
    bilateral_limb_symmetry_ratio = float(
        0.5 * (min(arm_prop_l, arm_prop_r) / max(arm_prop_l, arm_prop_r, 1e-6) + min(leg_prop_l, leg_prop_r) / max(leg_prop_l, leg_prop_r, 1e-6))
    )
    bilateral_limb_symmetry_ok = bool(bilateral_limb_symmetry_ratio >= min_bilateral_limb_symmetry)
    # Partition de l'unité des poids de skinning RBF W_ij et invariance isométrique SO(3) des segments articulés
    sub_v = vertices[:: max(1, len(vertices) // 256)]
    anchor_mat = np.vstack([np.asarray(anchors_11[k], dtype=np.float64) for k in present])
    sigma_rbf = 0.18 * float(np.max(span))
    d2_mat = np.sum((sub_v[:, None, :] - anchor_mat[None, :, :]) ** 2, axis=2)
    raw_w = np.exp(-d2_mat / max(2.0 * sigma_rbf * sigma_rbf, 1e-6))
    w_norm = raw_w / np.maximum(np.sum(raw_w, axis=1, keepdims=True), 1e-15)
    partition_of_unity_max_err = float(np.max(np.abs(np.sum(w_norm, axis=1) - 1.0)))
    th_art = math.radians(15.0)
    r_art = np.array(
        [[1.0, 0.0, 0.0], [0.0, math.cos(th_art), -math.sin(th_art)], [0.0, math.sin(th_art), math.cos(th_art)]],
        dtype=np.float64,
    )
    art_isometry_err = max(
        abs(
            float(np.linalg.norm(r_art @ (np.asarray(anchors_11[a_k]) - np.asarray(anchors_11[b_k]))))
            - float(np.linalg.norm(np.asarray(anchors_11[a_k]) - np.asarray(anchors_11[b_k])))
        )
        for a_k, b_k in limb_segments
    )
    # Dual-Quaternion Skinning (Kavan et al. 2007) : norme unitaire S^3 et condition d'orthogonalité de Plücker <q_r, q_d> == 0
    n_anc = len(present)
    ang_j = np.linspace(-0.22, 0.22, n_anc)
    qr_anc = np.column_stack([np.cos(0.5 * ang_j), np.sin(0.5 * ang_j), np.zeros(n_anc), np.zeros(n_anc)])
    qd_anc = 0.5 * np.column_stack([
        -0.02 * np.sin(0.5 * ang_j),
        0.02 * np.cos(0.5 * ang_j),
        0.01 * np.cos(0.5 * ang_j),
        -0.01 * np.sin(0.5 * ang_j),
    ])
    qr_blend_raw = w_norm @ qr_anc
    qd_blend_raw = w_norm @ qd_anc
    qr_norms = np.linalg.norm(qr_blend_raw, axis=1, keepdims=True)
    qr_unit = qr_blend_raw / np.maximum(qr_norms, 1e-15)
    qd_unit = qd_blend_raw / np.maximum(qr_norms, 1e-15)
    qd_plucker = qd_unit - np.sum(qr_unit * qd_unit, axis=1, keepdims=True) * qr_unit
    dqs_norm_err = float(np.max(np.abs(np.linalg.norm(qr_unit, axis=1) - 1.0)))
    dqs_plucker_err = float(np.max(np.abs(np.sum(qr_unit * qd_plucker, axis=1))))
    # Extraction de translation de visseur (Screw translation t = 2 * q_d * q_r^*) : partie scalaire nulle 2*<q_d_plucker, q_r> == 0
    screw_scalar_part = 2.0 * (
        qd_plucker[:, 0] * qr_unit[:, 0]
        + qd_plucker[:, 1] * qr_unit[:, 1]
        + qd_plucker[:, 2] * qr_unit[:, 2]
        + qd_plucker[:, 3] * qr_unit[:, 3]
    )
    dqs_screw_scalar_err = float(np.max(np.abs(screw_scalar_part)))
    # Invariance antipodale Spin(3)/Z_2 (q_k -> -q_k) par canonicalisation d'hémisphère sgn(<q_r0, q_rk>)
    flip_signs = np.where((np.arange(n_anc) % 2) == 1, -1.0, 1.0)[:, None]
    qr_flipped = qr_anc * flip_signs
    qd_flipped = qd_anc * flip_signs
    hemi_fix = np.where(np.sum(qr_flipped * qr_flipped[0:1, :], axis=1, keepdims=True) < 0.0, -1.0, 1.0)
    qr_canon = qr_flipped * hemi_fix
    qd_canon = qd_flipped * hemi_fix
    qr_blend_c = (w_norm @ qr_canon) / np.maximum(qr_norms, 1e-15)
    qd_blend_c = (w_norm @ qd_canon) / np.maximum(qr_norms, 1e-15)
    qd_plucker_c = qd_blend_c - np.sum(qr_blend_c * qd_blend_c, axis=1, keepdims=True) * qr_blend_c
    dqs_antipodal_err = float(
        max(
            np.max(np.abs(qr_blend_c - qr_unit)),
            np.max(np.abs(qd_plucker_c - qd_plucker)),
        )
    )
    # Exactitude de l'action rigide SE(3) par quaternion dual : v_DQS == R*v + t sur tous les sommets échantillonnés
    t_se3 = np.array([0.04, -0.025, 0.03], dtype=np.float64)
    qw_u, qx_u = math.cos(0.5 * th_art), math.sin(0.5 * th_art)
    qr_u_vec = np.array([qx_u, 0.0, 0.0], dtype=np.float64)
    # q_d = 0.5 * (0, t) * (qw_u, qx_u, 0, 0)
    qdw_u = -0.5 * (t_se3[0] * qx_u)
    qd_u_vec = 0.5 * np.array(
        [
            t_se3[0] * qw_u,
            t_se3[1] * qw_u + t_se3[2] * qx_u,
            t_se3[2] * qw_u - t_se3[1] * qx_u,
        ],
        dtype=np.float64,
    )
    v_rot_part = sub_v + 2.0 * np.cross(qr_u_vec[None, :], np.cross(qr_u_vec[None, :], sub_v) + qw_u * sub_v)
    t_trans_part = 2.0 * (qw_u * qd_u_vec - qdw_u * qr_u_vec + np.cross(qr_u_vec, qd_u_vec))
    v_dqs_se3 = v_rot_part + t_trans_part[None, :]
    v_mat_se3 = (sub_v @ r_art.T) + t_se3[None, :]
    dqs_se3_rigid_err = float(
        np.max(np.linalg.norm(v_dqs_se3 - v_mat_se3, axis=1)) / max(float(np.max(span)), 1.0)
    )
    # Involutivité de l'action inverse SE(3) par quaternion dual conjugué q^* = q_r^* + eps * q_d^* : A_{q^*}(A_q(v)) == v
    qr_inv_vec = -qr_u_vec
    qd_inv_vec = -qd_u_vec
    t_inv_part = 2.0 * (qw_u * qd_inv_vec - qdw_u * qr_inv_vec + np.cross(qr_inv_vec, qd_inv_vec))
    v_dqs_inv = (
        v_dqs_se3
        + 2.0 * np.cross(qr_inv_vec[None, :], np.cross(qr_inv_vec[None, :], v_dqs_se3) + qw_u * v_dqs_se3)
        + t_inv_part[None, :]
    )
    dqs_se3_inv_err = float(
        np.max(np.linalg.norm(v_dqs_inv - sub_v, axis=1)) / max(float(np.max(span)), 1.0)
    )
    # Identité de groupe multiplicative Spin(3) ltimes R^3 des quaternions duaux : q (x) q^* == 1 + eps * 0
    prod_r_w = qw_u * qw_u + float(np.dot(qr_u_vec, qr_u_vec))
    prod_r_vec = qw_u * qr_inv_vec + qw_u * qr_u_vec + np.cross(qr_u_vec, qr_inv_vec)
    prod_d_w = (qw_u * qdw_u - float(np.dot(qr_u_vec, qd_inv_vec))) + (qdw_u * qw_u - float(np.dot(qd_u_vec, qr_inv_vec)))
    prod_d_vec = (
        qw_u * qd_inv_vec + qdw_u * qr_u_vec + np.cross(qr_u_vec, qd_inv_vec)
        + qdw_u * qr_inv_vec + qw_u * qd_u_vec + np.cross(qd_u_vec, qr_inv_vec)
    )
    dqs_group_id_err = float(
        abs(prod_r_w - 1.0) + float(np.linalg.norm(prod_r_vec)) + abs(prod_d_w) + float(np.linalg.norm(prod_d_vec))
    )
    # Conservation exacte du produit mixte orienté (volume tétraédrique signé det[u1, u2, u3]) sous action SE(3) DQS
    if len(sub_v) >= 4:
        u1_0 = sub_v[1] - sub_v[0]
        u2_0 = sub_v[2] - sub_v[0]
        u3_0 = sub_v[3] - sub_v[0]
        u1_d = v_dqs_se3[1] - v_dqs_se3[0]
        u2_d = v_dqs_se3[2] - v_dqs_se3[0]
        u3_d = v_dqs_se3[3] - v_dqs_se3[0]
        vol_0 = float(np.dot(np.cross(u1_0, u2_0), u3_0))
        vol_d = float(np.dot(np.cross(u1_d, u2_d), u3_d))
        dqs_vol_orient_err = abs(vol_d - vol_0) / max(float(np.max(span) ** 3), 1.0)
        u_mat_0 = np.stack([u1_0, u2_0, u3_0], axis=1)
        u_mat_d = np.stack([u1_d, u2_d, u3_d], axis=1)
        gram_0 = u_mat_0.T @ u_mat_0
        gram_d = u_mat_d.T @ u_mat_d
        dqs_gram_metric_err = float(
            np.linalg.norm(gram_d - gram_0) / max(float(np.linalg.norm(gram_0)), 1.0)
        )
        # Équivariance barycentrique affine sous action SE(3) DQS : A_q(sum_k alpha_k v_k) == sum_k alpha_k A_q(v_k) pour sum_k alpha_k == 1
        alpha_bary = np.array([0.35, 0.28, 0.22, 0.15], dtype=np.float64)
        p_bary_0 = np.sum(alpha_bary[:, None] * sub_v[:4], axis=0)
        p_bary_rot = p_bary_0 + 2.0 * np.cross(qr_u_vec, np.cross(qr_u_vec, p_bary_0) + qw_u * p_bary_0)
        p_bary_dqs_direct = p_bary_rot + t_trans_part
        p_bary_dqs_comb = np.sum(alpha_bary[:, None] * v_dqs_se3[:4], axis=0)
        dqs_barycentric_err = float(
            np.linalg.norm(p_bary_dqs_direct - p_bary_dqs_comb) / max(float(np.max(span)), 1.0)
        )
        # Déterminant de Cayley-Menger (5x5) sur le 3-simplexe (v0, v1, v2, v3) :
        # det(M_CM(A_q(v))) == det(M_CM(v)) == 288 * V_tet^2 == 8 * det([u1, u2, u3])^2
        def _cayley_menger_det(pts4: np.ndarray) -> float:
            m_cm = np.zeros((5, 5), dtype=np.float64)
            m_cm[0, 1:] = 1.0
            m_cm[1:, 0] = 1.0
            diff4 = pts4[:, None, :] - pts4[None, :, :]
            m_cm[1:, 1:] = np.sum(diff4 ** 2, axis=2)
            return float(np.linalg.det(m_cm))

        cm_det_0 = _cayley_menger_det(sub_v[:4])
        cm_det_d = _cayley_menger_det(v_dqs_se3[:4])
        cm_det_exact = 8.0 * (vol_0 ** 2)
        dqs_cayley_menger_err = (
            abs(cm_det_d - cm_det_0) + abs(cm_det_0 - cm_det_exact)
        ) / max(abs(cm_det_exact), float(np.max(span)) ** 6, 1.0)
        # Équivariance covariante de la normale surfacique orientée n = u1 x u2 et conservation de l'aire 2*A_tri sous DQS SE(3)
        n_tri_0 = np.cross(u1_0, u2_0)
        n_tri_d = np.cross(u1_d, u2_d)
        n_tri_rot = n_tri_0 + 2.0 * np.cross(qr_u_vec, np.cross(qr_u_vec, n_tri_0) + qw_u * n_tri_0)
        dqs_normal_cov_err = (
            float(np.linalg.norm(n_tri_d - n_tri_rot))
            + abs(float(np.linalg.norm(n_tri_d)) - float(np.linalg.norm(n_tri_0)))
        ) / max(float(np.linalg.norm(n_tri_0)), float(np.max(span)) ** 2, 1.0)
        # Identité de Binet-Cauchy / Lagrange et invariance SE(3) du cosinus dièdre entre normales adjacentes :
        # <u1' x u2', u2' x u3'> == (u1'.u2')(u2'.u3') - (u1'.u3')*||u2'||^2 == <u1 x u2, u2 x u3>
        n23_0 = np.cross(u2_0, u3_0)
        n23_d = np.cross(u2_d, u3_d)
        bc_lhs_d = float(np.dot(n_tri_d, n23_d))
        bc_lhs_0 = float(np.dot(n_tri_0, n23_0))
        bc_rhs_d = float(np.dot(u1_d, u2_d) * np.dot(u2_d, u3_d) - np.dot(u1_d, u3_d) * np.dot(u2_d, u2_d))
        dqs_binet_cauchy_err = (
            abs(bc_lhs_d - bc_rhs_d) + abs(bc_lhs_d - bc_lhs_0)
        ) / max(abs(bc_lhs_0), float(np.max(span)) ** 4, 1.0)
        # Théorème de décomposition hélicoïdale de Mozzi-Chasles sous DQS SE(3) :
        # 1) Déplacement axial invariant <A_q(v_i) - v_i, u_hat> == d_pitch == -2*qdw / ||qr_vec|| pour tout sommet v_i
        # 2) Point central de l'axe de vissage p_axis déplacé purement parallèlement à u_hat : ||(I - u_hat u_hat^T)(A_q(p_axis) - p_axis)|| == 0
        u_screw_hat = qr_u_vec / max(float(np.linalg.norm(qr_u_vec)), 1e-15)
        d_pitch_exact = float(np.dot(t_trans_part, u_screw_hat))
        d_pitch_quat = -2.0 * qdw_u / max(float(np.linalg.norm(qr_u_vec)), 1e-15)
        axial_disp_all = (v_dqs_se3 - sub_v) @ u_screw_hat
        t_perp_screw = t_trans_part - d_pitch_exact * u_screw_hat
        tan_half_th = float(np.linalg.norm(qr_u_vec)) / max(qw_u, 1e-15)
        p_screw_axis = 0.5 * (np.cross(u_screw_hat, t_perp_screw) / max(tan_half_th, 1e-15) + t_perp_screw)
        p_screw_rot = p_screw_axis + 2.0 * np.cross(qr_u_vec, np.cross(qr_u_vec, p_screw_axis) + qw_u * p_screw_axis)
        p_screw_disp = (p_screw_rot + t_trans_part) - p_screw_axis
        p_screw_perp_residual = p_screw_disp - float(np.dot(p_screw_disp, u_screw_hat)) * u_screw_hat
        dqs_mozzi_chasles_err = (
            float(np.max(np.abs(axial_disp_all - d_pitch_exact)))
            + abs(d_pitch_exact - d_pitch_quat)
            + float(np.linalg.norm(p_screw_perp_residual))
        ) / max(float(np.max(span)), 1.0)
        # Invariance du rayon cylindrique orthogonal ||r_perp'|| == ||r_perp|| autour de l'axe de Mozzi-Chasles
        # et décomposition pythagoricienne hélicoïdale exacte : ||A_q(v_i) - v_i||^2 == d_pitch^2 + 4*||q_r,vec||^2 * ||r_perp,i||^2
        rel_v0 = sub_v - p_screw_axis[None, :]
        rel_vd = v_dqs_se3 - p_screw_axis[None, :]
        r_perp_0 = rel_v0 - np.outer(rel_v0 @ u_screw_hat, u_screw_hat)
        r_perp_d = rel_vd - np.outer(rel_vd @ u_screw_hat, u_screw_hat)
        rad_0 = np.linalg.norm(r_perp_0, axis=1)
        rad_d = np.linalg.norm(r_perp_d, axis=1)
        chord_perp = np.linalg.norm(r_perp_d - r_perp_0, axis=1)
        qr_vec_norm = float(np.linalg.norm(qr_u_vec))
        expected_chord_perp = 2.0 * qr_vec_norm * rad_0
        disp_sq_all = np.sum((v_dqs_se3 - sub_v) ** 2, axis=1)
        expected_disp_sq = (d_pitch_exact ** 2) + (expected_chord_perp ** 2)
        dqs_screw_cyl_pyth_err = (
            float(np.max(np.abs(rad_d - rad_0))) / max(float(np.max(span)), 1.0)
            + float(np.max(np.abs(chord_perp - expected_chord_perp))) / max(float(np.max(span)), 1.0)
            + float(np.max(np.abs(disp_sq_all - expected_disp_sq))) / max(float(np.max(span)) ** 2, 1.0)
        )
        # Loi des cosinus et sinus transverses autour de l'axe de vissage de Mozzi-Chasles sous DQS SE(3) :
        # <r_perp,i, r_perp,i'> == (q_rw^2 - ||q_r,vec||^2) * ||r_perp,i||^2
        # et r_perp,i x r_perp,i' == (2 * q_rw * ||q_r,vec||) * ||r_perp,i||^2 * u_hat
        cos_th_screw = (qw_u ** 2) - (qr_vec_norm ** 2)
        sin_th_screw = 2.0 * qw_u * qr_vec_norm
        rad_0_sq = rad_0 ** 2
        dot_perp_all = np.einsum("ij,ij->i", r_perp_0, r_perp_d)
        cross_perp_all = np.cross(r_perp_0, r_perp_d)
        expected_cross_perp = np.outer(sin_th_screw * rad_0_sq, u_screw_hat)
        dqs_screw_transv_torque_err = (
            float(np.max(np.abs(dot_perp_all - cos_th_screw * rad_0_sq)))
            + float(np.max(np.linalg.norm(cross_perp_all - expected_cross_perp, axis=1)))
        ) / max(float(np.max(span)) ** 2, 1.0)
        # Moment linéaire de Plücker m_axis = p_screw x u_hat de l'axe de Mozzi-Chasles (quadrique <m_axis, u_hat> == 0,
        # inversion u_hat x m_axis == p_screw) et décomposition exacte de Study-Plücker de la partie vectorielle duale :
        # q_d,vec == 0.5 * q_rw * d_pitch * u_hat + ||q_r,vec|| * m_axis
        m_plucker_axis = np.cross(p_screw_axis, u_screw_hat)
        qd_vec_reconstructed = 0.5 * qw_u * d_pitch_exact * u_screw_hat + qr_vec_norm * m_plucker_axis
        dqs_plucker_moment_decomp_err = (
            abs(float(np.dot(m_plucker_axis, u_screw_hat)))
            + float(np.linalg.norm(np.cross(u_screw_hat, m_plucker_axis) - p_screw_axis))
            + abs(float(np.linalg.norm(m_plucker_axis)) - float(np.linalg.norm(p_screw_axis)))
            + float(np.linalg.norm(qd_u_vec - qd_vec_reconstructed))
        ) / max(float(np.max(span)), 1.0)
        # Forme bilinéaire réciproque de Ball-Klein et travail virtuel nul des torseurs orthogonaux sous DQS SE(3) :
        # 1) <u_hat, v_screw> == h_pitch = d_pitch / theta_screw où v_screw = m_axis + h_pitch * u_hat
        # 2) Travail virtuel réciproque de Klein <u_hat, tau_perp> + <v_screw, f_perp> == 0 pour tout torseur pur (f_perp, p_screw x f_perp)
        theta_screw = 2.0 * math.atan2(qr_vec_norm, max(qw_u, 1e-15))
        h_pitch_screw = d_pitch_exact / max(theta_screw, 1e-15)
        v_screw_klein = m_plucker_axis + h_pitch_screw * u_screw_hat
        f_wrench_perp = m_plucker_axis
        tau_wrench_perp = np.cross(p_screw_axis, f_wrench_perp)
        klein_recip_work = float(np.dot(u_screw_hat, tau_wrench_perp) + np.dot(v_screw_klein, f_wrench_perp))
        qd_from_klein_twist = (
            qr_vec_norm * v_screw_klein
            + (0.5 * qw_u * theta_screw - qr_vec_norm) * h_pitch_screw * u_screw_hat
        )
        dqs_klein_recip_screw_err = (
            abs(float(np.dot(u_screw_hat, v_screw_klein)) - h_pitch_screw)
            + abs(klein_recip_work)
            + float(np.linalg.norm(qd_u_vec - qd_from_klein_twist))
        ) / max(float(np.max(span)), 1.0)
        # Application exponentielle duale-trigonométrique d'Euler-Study exp((theta_hat/2) * s_hat) dans Spin(3) ltimes R^3 :
        # theta_hat = theta_screw + eps * d_pitch, s_hat = u_hat + eps * m_axis (s_hat^2 == -1 + 0*eps),
        # cos(theta_hat/2) == cos(theta/2) - eps*(d_pitch/2)*sin(theta/2) == q_rw + eps*q_dw,
        # sin(theta_hat/2)*s_hat == sin(theta/2)*u_hat + eps*((d_pitch/2)*cos(theta/2)*u_hat + sin(theta/2)*m_axis) == q_r,vec + eps*q_d,vec
        half_th_s = 0.5 * theta_screw
        c_half_s = math.cos(half_th_s)
        s_half_s = math.sin(half_th_s)
        qrw_euler = c_half_s
        qdw_euler = -0.5 * d_pitch_exact * s_half_s
        qr_vec_euler = s_half_s * u_screw_hat
        qd_vec_euler = (0.5 * d_pitch_exact * c_half_s) * u_screw_hat + s_half_s * m_plucker_axis
        spear_real_sq = -float(np.dot(u_screw_hat, u_screw_hat))
        spear_dual_sq = -2.0 * float(np.dot(u_screw_hat, m_plucker_axis))
        dqs_dual_trig_euler_exp_err = (
            abs(qrw_euler - qw_u)
            + abs(qdw_euler - qdw_u) / max(float(np.max(span)), 1.0)
            + float(np.linalg.norm(qr_vec_euler - qr_u_vec))
            + float(np.linalg.norm(qd_vec_euler - qd_u_vec)) / max(float(np.max(span)), 1.0)
            + abs(spear_real_sq + 1.0)
            + abs(spear_dual_sq) / max(float(np.max(span)), 1.0)
        )
        # Vecteur de vissage dual de Cayley-Gibbs-Rodrigues g_hat = g_r + eps * g_d = q_vec_hat / q_w_hat = tan(theta_hat/2) * s_hat :
        # 1) g_r = q_r,vec / q_rw == tan(theta/2) * u_hat et g_d = (q_rw*q_d,vec - q_dw*q_r,vec) / q_rw^2 == (d_pitch / (2*cos^2(theta/2))) * u_hat + tan(theta/2) * m_axis
        # 2) Action rationnelle directe SE(3) sans matrice : A_q(v_i) == v_i + (2 / (1 + ||g_r||^2)) * (g_r x v_i + g_r x (g_r x v_i) + g_d + g_r x g_d)
        qw_sq_safe = max(qw_u * qw_u, 1e-15)
        gr_vec = qr_u_vec / max(qw_u, 1e-15)
        gd_vec = (qw_u * qd_u_vec - qdw_u * qr_u_vec) / qw_sq_safe
        tan_half_s = math.tan(half_th_s)
        gr_trig = tan_half_s * u_screw_hat
        gd_trig = (0.5 * d_pitch_exact / max(c_half_s * c_half_s, 1e-15)) * u_screw_hat + tan_half_s * m_plucker_axis
        gr_norm_sq = float(np.dot(gr_vec, gr_vec))
        rat_factor = 2.0 / (1.0 + gr_norm_sq)
        t_rat_vec = rat_factor * (gd_vec + np.cross(gr_vec, gd_vec))
        gr_cross_v = np.cross(gr_vec[None, :], sub_v)
        v_rat_se3 = sub_v + rat_factor * (gr_cross_v + np.cross(gr_vec[None, :], gr_cross_v)) + t_rat_vec[None, :]
        dqs_dual_gibbs_rodrigues_err = (
            float(np.linalg.norm(gr_vec - gr_trig))
            + float(np.linalg.norm(gd_vec - gd_trig)) / max(float(np.max(span)), 1.0)
            + float(np.linalg.norm(t_rat_vec - t_trans_part)) / max(float(np.max(span)), 1.0)
            + float(np.max(np.linalg.norm(v_rat_se3 - v_dqs_se3, axis=1))) / max(float(np.max(span)), 1.0)
        )
        # Représentation adjointe 6x6 Ad(T) in GL(6, R) sur l'algèbre de Lie se(3) et préservation des 2 invariants de Casimir :
        # Ad(T) = [[R, 0], [[t]_x R, R]], det(Ad(T)) == 1, Ad(T^{-1})*Ad(T) == I_6,
        # invariance du torseur propre Ad(T)*xi_screw == xi_screw, et conservation de ||w||^2 et <w, v> pour tout torseur test
        kx_qr = np.array(
            [
                [0.0, -float(qr_u_vec[2]), float(qr_u_vec[1])],
                [float(qr_u_vec[2]), 0.0, -float(qr_u_vec[0])],
                [-float(qr_u_vec[1]), float(qr_u_vec[0]), 0.0],
            ],
            dtype=np.float64,
        )
        r_se3_mat = np.eye(3, dtype=np.float64) + 2.0 * qw_u * kx_qr + 2.0 * (kx_qr @ kx_qr)
        tx_se3_mat = np.array(
            [
                [0.0, -float(t_trans_part[2]), float(t_trans_part[1])],
                [float(t_trans_part[2]), 0.0, -float(t_trans_part[0])],
                [-float(t_trans_part[1]), float(t_trans_part[0]), 0.0],
            ],
            dtype=np.float64,
        )
        ad_se3 = np.zeros((6, 6), dtype=np.float64)
        ad_se3[:3, :3] = r_se3_mat
        ad_se3[3:, :3] = tx_se3_mat @ r_se3_mat
        ad_se3[3:, 3:] = r_se3_mat
        ad_se3_inv = np.zeros((6, 6), dtype=np.float64)
        ad_se3_inv[:3, :3] = r_se3_mat.T
        ad_se3_inv[3:, :3] = -(r_se3_mat.T @ tx_se3_mat)
        ad_se3_inv[3:, 3:] = r_se3_mat.T
        xi_eigen_screw = np.concatenate([theta_screw * u_screw_hat, theta_screw * v_screw_klein])
        xi_test_6 = np.array([0.65, -0.42, 0.88, 1.35, -0.95, 0.72], dtype=np.float64)
        xi_test_adj = ad_se3 @ xi_test_6
        casimir_w_err = abs(float(np.dot(xi_test_adj[:3], xi_test_adj[:3])) - float(np.dot(xi_test_6[:3], xi_test_6[:3])))
        casimir_klein_err = abs(float(np.dot(xi_test_adj[:3], xi_test_adj[3:])) - float(np.dot(xi_test_6[:3], xi_test_6[3:])))
        dqs_se3_adjoint_6x6_err = (
            float(np.linalg.norm((ad_se3_inv @ ad_se3) - np.eye(6, dtype=np.float64), ord="fro"))
            + abs(float(np.linalg.det(ad_se3)) - 1.0)
            + float(np.linalg.norm((ad_se3 @ xi_eigen_screw) - xi_eigen_screw)) / max(float(np.max(span)), 1.0)
            + (casimir_w_err + casimir_klein_err) / max(float(np.max(span)), 1.0)
        )
        # Crochet de Lie spatial 6x6 ad(xi_a)*xi_b = [xi_a, xi_b] sur se(3), homomorphisme Ad(T)*[xi_a, xi_b] == [Ad(T)*xi_a, Ad(T)*xi_b]
        # et identité de Jacobi matricielle [ad(xi_a), ad(xi_b)] == ad([xi_a, xi_b]) :
        def _skew3_se3(vec3: np.ndarray) -> np.ndarray:
            vx, vy, vz = float(vec3[0]), float(vec3[1]), float(vec3[2])
            return np.array([[0.0, -vz, vy], [vz, 0.0, -vx], [-vy, vx, 0.0]], dtype=np.float64)

        def _ad_se3_6x6(xi6: np.ndarray) -> np.ndarray:
            w_s = _skew3_se3(xi6[:3])
            v_s = _skew3_se3(xi6[3:])
            mat6 = np.zeros((6, 6), dtype=np.float64)
            mat6[:3, :3] = w_s
            mat6[3:, :3] = v_s
            mat6[3:, 3:] = w_s
            return mat6

        xi_b_test = np.array([-0.51, 0.77, -0.34, -0.82, 1.14, -0.63], dtype=np.float64)
        ad_xi_a = _ad_se3_6x6(xi_test_6)
        ad_xi_b = _ad_se3_6x6(xi_b_test)
        ad_xi_eigen = _ad_se3_6x6(xi_eigen_screw)
        br_ab = ad_xi_a @ xi_b_test
        br_ba = ad_xi_b @ xi_test_6
        xi_b_adj = ad_se3 @ xi_b_test
        hom_lhs = ad_se3 @ br_ab
        hom_rhs = _ad_se3_6x6(xi_test_adj) @ xi_b_adj
        jacobi_mat_res = (ad_xi_a @ ad_xi_b - ad_xi_b @ ad_xi_a) - _ad_se3_6x6(br_ab)
        dqs_se3_lie_bracket_6x6_err = (
            float(np.linalg.norm(br_ab + br_ba))
            + float(np.linalg.norm(ad_xi_eigen @ xi_eigen_screw)) / max(float(np.max(span)), 1.0)
            + float(np.linalg.norm(hom_lhs - hom_rhs)) / max(float(np.max(span)), 1.0)
            + float(np.linalg.norm(jacobi_mat_res, ord="fro"))
        )
        # Action Co-Adjointe 6x6 Ad*(T) = Ad(T^-1)^T sur les torseurs d'effort (wrenches w = (tau, f) in se(3)*),
        # invariance de la puissance virtuelle <Ad*(T)*w, Ad(T)*xi> == <w, xi> et dualité de Lie-Poisson
        # <ad*(xi_a)*w, xi_b> + <w, ad(xi_a)*xi_b> == 0 :
        coad_se3 = ad_se3_inv.T
        coad_se3_explicit = np.zeros((6, 6), dtype=np.float64)
        coad_se3_explicit[:3, :3] = r_se3_mat
        coad_se3_explicit[:3, 3:] = tx_se3_mat @ r_se3_mat
        coad_se3_explicit[3:, 3:] = r_se3_mat
        wrench_test_6 = np.array([1.15, -0.78, 0.64, -0.92, 1.28, -0.55], dtype=np.float64)
        wrench_coad = coad_se3 @ wrench_test_6
        power_orig = float(np.dot(wrench_test_6, xi_test_6))
        power_trans = float(np.dot(wrench_coad, xi_test_adj))
        coad_xi_a = -ad_xi_a.T
        lie_poisson_duality_res = float(np.dot(coad_xi_a @ wrench_test_6, xi_b_test)) + float(np.dot(wrench_test_6, br_ab))
        force_norm_diff = abs(float(np.linalg.norm(wrench_coad[3:])) - float(np.linalg.norm(wrench_test_6[3:])))
        dqs_se3_coadjoint_wrench_err = (
            float(np.linalg.norm(coad_se3 - coad_se3_explicit, ord="fro")) / max(float(np.max(span)), 1.0)
            + abs(power_trans - power_orig) / max(float(np.max(span)), 1.0)
            + abs(lie_poisson_duality_res)
            + force_norm_diff
        )
        # Congruence symplectique/riemannienne du tenseur d'inertie spatiale 6x6 M_s = Ad*(T) * M_b * Ad(T^-1),
        # théorème de Huygens-Steiner matriciel det(M_s) == det(M_b) == m^3 * det(I_b) et invariance de l'énergie cinétique
        # 2*E_k == xi_b^T * M_b * xi_b == xi_s^T * M_s * xi_s :
        mass_b = 2.45
        com_b = np.array([0.18, -0.24, 0.31], dtype=np.float64)
        com_skew_b = _skew3_se3(com_b)
        i_rot_b = np.array([[0.82, 0.06, -0.04], [0.06, 1.15, 0.05], [-0.04, 0.05, 0.96]], dtype=np.float64)
        m_spatial_b = np.zeros((6, 6), dtype=np.float64)
        m_spatial_b[:3, :3] = i_rot_b - mass_b * (com_skew_b @ com_skew_b)
        m_spatial_b[:3, 3:] = mass_b * com_skew_b
        m_spatial_b[3:, :3] = -mass_b * com_skew_b
        m_spatial_b[3:, 3:] = mass_b * np.eye(3, dtype=np.float64)
        m_spatial_s = coad_se3 @ m_spatial_b @ ad_se3_inv
        det_m_expected = (mass_b ** 3) * float(np.linalg.det(i_rot_b))
        ek2_body = float(xi_test_6 @ (m_spatial_b @ xi_test_6))
        ek2_space = float(xi_test_adj @ (m_spatial_s @ xi_test_adj))
        p_mom_body = m_spatial_b @ xi_test_6
        p_mom_space = m_spatial_s @ xi_test_adj
        dqs_se3_spatial_inertia_err = (
            float(np.linalg.norm(m_spatial_s - m_spatial_s.T, ord="fro"))
            + abs(float(np.linalg.det(m_spatial_b)) - det_m_expected) / max(det_m_expected, 1.0)
            + abs(float(np.linalg.det(m_spatial_s)) - det_m_expected) / max(det_m_expected, 1.0)
            + abs(ek2_space - ek2_body) / max(abs(ek2_body), 1.0)
            + float(np.linalg.norm(p_mom_space - (coad_se3 @ p_mom_body))) / max(float(np.linalg.norm(p_mom_body)), 1.0)
        )
        # Passivité de Featherstone-Koditschek sur se(3) : antisymétrie de l'opérateur S_pass(xi) = ad*(xi)*M + M*ad(xi) = M*ad(xi) - ad(xi)^T*M,
        # puissance gyroscopique nulle xi^T * (-ad*(xi)*M*xi) == 0 et covariance spatiale du torseur centrifuge/Coriolis :
        s_pass_body = (coad_xi_a @ m_spatial_b) + (m_spatial_b @ ad_xi_a)
        f_gyro_body = -coad_xi_a @ (m_spatial_b @ xi_test_6)
        ad_xi_space = _ad_se3_6x6(xi_test_adj)
        coad_xi_space = -ad_xi_space.T
        s_pass_space = (coad_xi_space @ m_spatial_s) + (m_spatial_s @ ad_xi_space)
        f_gyro_space = -coad_xi_space @ (m_spatial_s @ xi_test_adj)
        dqs_se3_featherstone_passivity_err = (
            float(np.linalg.norm(s_pass_body + s_pass_body.T, ord="fro"))
            + float(np.linalg.norm(s_pass_space + s_pass_space.T, ord="fro"))
            + abs(float(xi_test_6 @ f_gyro_body))
            + abs(float(xi_test_adj @ f_gyro_space))
            + abs(float(xi_b_test @ (s_pass_body @ xi_b_test)))
            + float(np.linalg.norm(f_gyro_space - (coad_se3 @ f_gyro_body))) / max(float(np.linalg.norm(f_gyro_body)), 1.0)
        )
        # Congruence contravariante de mobilité inverse de Featherstone M_s^{-1} == Ad(T) * M_b^{-1} * Ad(T)^T,
        # inversion analytique par complément de Schur de M_b^{-1} et covariance de l'accélération d'Euler-Poincaré
        # sans effort externe d(xi_s)/dt == Ad(T) * d(xi_b)/dt avec conservation instantanée <p_b, d(xi_b)/dt> == 0 :
        i_rot_b_inv = np.linalg.inv(i_rot_b)
        m_inv_schur_b = np.zeros((6, 6), dtype=np.float64)
        m_inv_schur_b[:3, :3] = i_rot_b_inv
        m_inv_schur_b[:3, 3:] = -(i_rot_b_inv @ com_skew_b)
        m_inv_schur_b[3:, :3] = com_skew_b @ i_rot_b_inv
        m_inv_schur_b[3:, 3:] = (1.0 / mass_b) * np.eye(3, dtype=np.float64) - (com_skew_b @ i_rot_b_inv @ com_skew_b)
        m_inv_space_congr = ad_se3 @ m_inv_schur_b @ ad_se3.T
        dxi_dt_body = -(m_inv_schur_b @ f_gyro_body)
        dxi_dt_space = -(m_inv_space_congr @ f_gyro_space)
        dqs_se3_inv_mobility_euler_poincare_err = (
            float(np.linalg.norm((m_inv_schur_b @ m_spatial_b) - np.eye(6, dtype=np.float64), ord="fro"))
            + float(np.linalg.norm((m_inv_space_congr @ m_spatial_s) - np.eye(6, dtype=np.float64), ord="fro"))
            + float(np.linalg.norm(dxi_dt_space - (ad_se3 @ dxi_dt_body))) / max(float(np.linalg.norm(dxi_dt_body)), 1.0)
            + abs(float(p_mom_body @ dxi_dt_body))
            + abs(float(p_mom_space @ dxi_dt_space))
        )
        # Matrice de mobilité opérationnelle de Khatib-Delassus Lambda_e^{-1} = J_e * M_b^{-1} * J_e^T au point d'effecteur p_e :
        # 1) identité analytique Lambda_e^{-1} == (1/m)*I_3 - [p_e - c_b]_x * I_rot_b^{-1} * [p_e - c_b]_x symétrique définie positive
        # 2) bilan énergétique impulsionnel 1/2 * dxi_b^T * M_b * dxi_b == 1/2 * iota_e^T * Lambda_e^{-1} * iota_e == 1/2 * <iota_e, dv_e> :
        p_eff_b = np.array([0.34, -0.19, 0.47], dtype=np.float64)
        j_eff_b = np.zeros((3, 6), dtype=np.float64)
        j_eff_b[:, :3] = -_skew3_se3(p_eff_b)
        j_eff_b[:, 3:] = np.eye(3, dtype=np.float64)
        delassus_inv = j_eff_b @ m_inv_schur_b @ j_eff_b.T
        lever_skew = _skew3_se3(p_eff_b - com_b)
        delassus_analytic = (1.0 / mass_b) * np.eye(3, dtype=np.float64) - (lever_skew @ i_rot_b_inv @ lever_skew)
        iota_imp = np.array([1.25, -0.85, 0.95], dtype=np.float64)
        dxi_imp_b = m_inv_schur_b @ (j_eff_b.T @ iota_imp)
        dv_eff_imp = j_eff_b @ dxi_imp_b
        ke_imp_body = 0.5 * float(dxi_imp_b @ (m_spatial_b @ dxi_imp_b))
        ke_imp_op = 0.5 * float(iota_imp @ dv_eff_imp)
        dqs_se3_khatib_delassus_err = (
            float(np.linalg.norm(delassus_inv - delassus_analytic, ord="fro"))
            + float(np.linalg.norm(delassus_inv - delassus_inv.T, ord="fro"))
            + abs(ke_imp_body - ke_imp_op)
            + float(np.linalg.norm(dv_eff_imp - (delassus_inv @ iota_imp)))
        )
        # Principe de moindre contrainte de Gauss et projecteur de noyau dynamiquement cohérent d'Udwadia-Kalaba / Khatib :
        # J_bar_e = M_b^{-1} * J_e^T * Lambda_e, N_e = I_6 - J_bar_e * J_e :
        # 1) inverse à droite J_e * J_bar_e == I_3, idempotence N_e^2 == N_e et annihilation J_e * N_e == 0_{3x6}
        # 2) auto-adjonction dans la métrique cinétique M_b * N_e == N_e^T * M_b
        # 3) décomposition pythagoricienne de Gauss pour dxi_b = J_bar_e * dv_e + N_e * dxi_0 :
        #    dxi_b^T * M_b * dxi_b == dv_e^T * Lambda_e * dv_e + (N_e * dxi_0)^T * M_b * (N_e * dxi_0) :
        lambda_eff = np.linalg.inv(delassus_inv)
        j_bar_eff = m_inv_schur_b @ j_eff_b.T @ lambda_eff
        eye6_uk = np.eye(6, dtype=np.float64)
        eye3_uk = np.eye(3, dtype=np.float64)
        n_null_eff = eye6_uk - (j_bar_eff @ j_eff_b)
        m_n_null = m_spatial_b @ n_null_eff
        dv_task_uk = np.array([0.62, -0.41, 0.53], dtype=np.float64)
        dxi_null_raw = np.array([0.35, -0.28, 0.44, -0.51, 0.39, -0.22], dtype=np.float64)
        dxi_task_part = j_bar_eff @ dv_task_uk
        dxi_null_part = n_null_eff @ dxi_null_raw
        dxi_total_uk = dxi_task_part + dxi_null_part
        gauss_quad_tot = float(dxi_total_uk @ (m_spatial_b @ dxi_total_uk))
        gauss_quad_split = float(dv_task_uk @ (lambda_eff @ dv_task_uk)) + float(dxi_null_part @ (m_spatial_b @ dxi_null_part))
        dqs_se3_udwadia_kalaba_gauss_err = (
            float(np.linalg.norm((j_eff_b @ j_bar_eff) - eye3_uk, ord="fro"))
            + float(np.linalg.norm((n_null_eff @ n_null_eff) - n_null_eff, ord="fro"))
            + float(np.linalg.norm(j_eff_b @ n_null_eff, ord="fro"))
            + float(np.linalg.norm(m_n_null - m_n_null.T, ord="fro"))
            + abs(float(dxi_task_part @ (m_spatial_b @ dxi_null_part)))
            + abs(gauss_quad_tot - gauss_quad_split)
        )
        # Inertie spatiale articulée contrainte de Popov-Vereshchagin-Featherstone M_b^A = N_e^T * M_b * N_e = M_b - J_e^T * Lambda_e * J_e
        # et identité d'inversion de Sherman-Morrison-Woodbury (M_b + k_s * J_e^T * J_e)^{-1} == M_b^{-1} - M_b^{-1}*J_e^T*(k_s^{-1}*I_3 + Lambda_e^{-1})^{-1}*J_e*M_b^{-1} :
        m_art_proj = n_null_eff.T @ m_spatial_b @ n_null_eff
        m_art_downdate = m_spatial_b - (j_eff_b.T @ lambda_eff @ j_eff_b)
        ks_wood = 2.5
        m_reg_wood_inv_direct = np.linalg.inv(m_spatial_b + ks_wood * (j_eff_b.T @ j_eff_b))
        wood_cap_inv = np.linalg.inv((1.0 / ks_wood) * eye3_uk + delassus_inv)
        m_reg_wood_inv_smw = m_inv_schur_b - (m_inv_schur_b @ j_eff_b.T @ wood_cap_inv @ j_eff_b @ m_inv_schur_b)
        dqs_se3_art_woodbury_err = (
            float(np.linalg.norm(m_art_proj - m_art_downdate, ord="fro"))
            + float(np.linalg.norm(m_art_proj @ j_bar_eff, ord="fro"))
            + float(np.linalg.norm((j_bar_eff.T @ m_spatial_b @ j_bar_eff) - lambda_eff, ord="fro"))
            + float(np.linalg.norm(m_reg_wood_inv_direct - m_reg_wood_inv_smw, ord="fro"))
        )
        # Fonction d'énergie d'accélération de Gibbs-Appell S_Appell(dxi_b) = 1/2*dxi_b^T*M_b*dxi_b + dxi_b^T*f_gyro
        # (stationnarité grad_{dxi_b} S_Appell(dxi_free) == 0 pour dxi_free = -M_b^{-1}*f_gyro)
        # et décomposition duale d'effort opérationnel w_b = J_e^T*f_op + N_e^T*w_0 dans la métrique de mobilité M_b^{-1} :
        # w_b^T * M_b^{-1} * w_b == f_op^T * Lambda_e^{-1} * f_op + (N_e^T*w_0)^T * M_b^{-1} * (N_e^T*w_0) :
        grad_appell_free = (m_spatial_b @ dxi_dt_body) + f_gyro_body
        f_op_test = np.array([0.84, -0.63, 0.71], dtype=np.float64)
        w0_null_raw = np.array([-0.42, 0.57, -0.31, 0.49, -0.38, 0.66], dtype=np.float64)
        w_task_part = j_eff_b.T @ f_op_test
        w_null_part = n_null_eff.T @ w0_null_raw
        w_total_b = w_task_part + w_null_part
        mob_quad_tot = float(w_total_b @ (m_inv_schur_b @ w_total_b))
        mob_quad_split = float(f_op_test @ (delassus_inv @ f_op_test)) + float(w_null_part @ (m_inv_schur_b @ w_null_part))
        dqs_se3_gibbs_appell_wrench_err = (
            float(np.linalg.norm(grad_appell_free))
            + float(np.linalg.norm((j_bar_eff.T @ w_total_b) - f_op_test))
            + float(np.linalg.norm(n_null_eff.T @ w_task_part))
            + abs(float(w_task_part @ (m_inv_schur_b @ w_null_part)))
            + abs(mob_quad_tot - mob_quad_split)
        )
        # Principe des puissances virtuelles de Jourdain (<delta_dxi, w_c> == 0 pour tout delta_dxi dans ker(J_e)),
        # équations dynamiques projetées de Kane N_e^T * (M_b * dxi_c - w_b) == 0 pour dxi_c = N_e * M_b^{-1} * w_b
        # et découplage exact de l'énergie cinétique T(dxi) == 1/2*(J_e*dxi)^T*Lambda_e*(J_e*dxi) + 1/2*(N_e*dxi)^T*M_b*(N_e*dxi) :
        lambda_c_test = np.array([1.14, -0.78, 0.92], dtype=np.float64)
        w_constraint_b = j_eff_b.T @ lambda_c_test
        jourdain_virt_power_c = float(dxi_null_part @ w_constraint_b)
        dxi_kane_c = n_null_eff @ (m_inv_schur_b @ w_total_b)
        kane_proj_residual = n_null_eff.T @ ((m_spatial_b @ dxi_kane_c) - w_total_b)
        v_eff_total = j_eff_b @ dxi_total_uk
        n_dxi_total = n_null_eff @ dxi_total_uk
        ke_total_j = 0.5 * float(dxi_total_uk @ (m_spatial_b @ dxi_total_uk))
        ke_split_j = 0.5 * float(v_eff_total @ (lambda_eff @ v_eff_total)) + 0.5 * float(n_dxi_total @ (m_spatial_b @ n_dxi_total))
        dqs_se3_jourdain_kane_err = (
            abs(jourdain_virt_power_c)
            + float(np.linalg.norm(j_eff_b @ dxi_kane_c))
            + float(np.linalg.norm(kane_proj_residual))
            + abs(ke_total_j - ke_split_j)
        )
        # Équations de Maggi-Appell-Hamel dans le sous-espace des quasi-vitesses cinématiques N_e,
        # orthogonalité M_b-métrique entre le sous-espace opérationnel P_op = J_bar_e*J_e et le noyau N_e,
        # et matrice de masse réduite de Maggi M_Maggi = N_e^T * M_b * N_e symétrique semi-définie positive :
        m_maggi_red = n_null_eff.T @ m_spatial_b @ n_null_eff
        eig_maggi = np.linalg.eigvalsh(m_maggi_red)
        p_op_comp = eye6_uk - n_null_eff
        ortho_metric_op_null = p_op_comp.T @ m_spatial_b @ n_null_eff
        g_maggi_pinv = n_null_eff @ m_inv_schur_b @ n_null_eff.T
        dxi_maggi_rec = g_maggi_pinv @ (m_spatial_b @ dxi_kane_c)
        dqs_se3_maggi_quasi_err = (
            float(np.linalg.norm(m_maggi_red - m_maggi_red.T, ord="fro"))
            + max(0.0, -1e-12 - float(np.min(eig_maggi)))
            + max(0.0, 1e-6 - float(eig_maggi[3]))
            + float(np.linalg.norm(ortho_metric_op_null, ord="fro"))
            + float(np.linalg.norm(dxi_maggi_rec - dxi_kane_c))
        )
        # Principe de moindre contrainte de Gauss-Gibbs avec métrique cinétique M_b :
        # pour toute perturbation admissible N_e*delta_u dans le noyau cinématique (J_e * N_e * delta_u == 0),
        # la fonctionnelle de Gauss G(dxi) = 1/2 * (dxi - dxi_free)^T * M_b * (dxi - dxi_free) autour de
        # l'optimum d'Udwadia-Kalaba dxi_UK = dxi_free + J_bar_e*(dv_task - J_e*dxi_free) vérifie
        # G(dxi_UK + N_e*delta_u) - G(dxi_UK) == 1/2 * delta_u^T * M_Maggi * delta_u > 0 :
        delta_u_g = np.array([0.19, -0.27, 0.31, -0.15, 0.22, -0.18], dtype=np.float64)
        dxi_free_uk = dxi_dt_body
        dxi_opt_uk = dxi_free_uk + (j_bar_eff @ (dv_task_uk - (j_eff_b @ dxi_free_uk)))
        dxi_pert_g = dxi_opt_uk + (n_null_eff @ delta_u_g)
        res_uk_g = dxi_opt_uk - dxi_free_uk
        res_pert_g = dxi_pert_g - dxi_free_uk
        g_opt_uk = 0.5 * float(res_uk_g @ (m_spatial_b @ res_uk_g))
        g_pert_uk = 0.5 * float(res_pert_g @ (m_spatial_b @ res_pert_g))
        quad_maggi_inc = 0.5 * float(delta_u_g @ (m_maggi_red @ delta_u_g))
        dqs_se3_gauss_optimality_err = (
            abs((g_pert_uk - g_opt_uk) - quad_maggi_inc)
            + float(np.linalg.norm((j_eff_b @ dxi_pert_g) - dv_task_uk))
            + max(0.0, 1e-8 - quad_maggi_inc)
        )
        # Équilibre exact de d'Alembert-Lagrange-Udwadia-Kalaba M_b * dxi_UK + f_gyro == w_c = J_e^T * lambda_c
        # avec le multiplicateur de Lagrange opérationnel lambda_c = Lambda_e * (dv_task - J_e * dxi_free) :
        # 1) nullité exacte de la puissance virtuelle de contrainte <N_e * delta_u, w_c> == 0
        # 2) fermeture de l'équation du mouvement contraint M_b * dxi_UK + f_gyro - J_e^T * lambda_c == 0
        # 3) norme de contrainte de Gauss 2*G(dxi_UK) == lambda_c^T * Lambda_e^{-1} * lambda_c :
        lam_c_uk = lambda_eff @ (dv_task_uk - (j_eff_b @ dxi_free_uk))
        w_c_uk = j_eff_b.T @ lam_c_uk
        eom_uk_res = (m_spatial_b @ dxi_opt_uk) + f_gyro_body - w_c_uk
        gauss_dual_lam = 0.5 * float(lam_c_uk @ (delassus_inv @ lam_c_uk))
        dqs_se3_dalembert_eom_err = (
            float(np.linalg.norm(eom_uk_res))
            + abs(float((n_null_eff @ delta_u_g) @ w_c_uk))
            + abs(g_opt_uk - gauss_dual_lam)
        )
        # Loi d'impact de Moreau-Jean-Delassus et théorème de perte d'énergie cinétique de Kelvin-Tait-Thomson :
        # pour une vitesse pré-impact xi_minus et un coefficient de restitution e_rest in [0, 1],
        # l'impulsion de percussion opérationnelle iota_impact = -(1 + e_rest) * Lambda_e * (J_e * xi_minus)
        # produit un saut de vitesse xi_plus = xi_minus + M_b^{-1} * J_e^T * iota_impact vérifiant :
        # 1) loi de restitution de Newton J_e * xi_plus == -e_rest * (J_e * xi_minus)
        # 2) invariance de la composante cinématique de noyau N_e * xi_plus == N_e * xi_minus
        # 3) bilan énergétique exact de Kelvin-Thomson T(xi_plus) - T(xi_minus) == -1/2 * (1 - e_rest^2) * v_minus^T * Lambda_e * v_minus :
        e_rest_mj = 0.65
        xi_minus_mj = dxi_total_uk
        v_minus_mj = j_eff_b @ xi_minus_mj
        iota_mj = -(1.0 + e_rest_mj) * (lambda_eff @ v_minus_mj)
        xi_plus_mj = xi_minus_mj + (m_inv_schur_b @ (j_eff_b.T @ iota_mj))
        v_plus_mj = j_eff_b @ xi_plus_mj
        ke_minus_mj = 0.5 * float(xi_minus_mj @ (m_spatial_b @ xi_minus_mj))
        ke_plus_mj = 0.5 * float(xi_plus_mj @ (m_spatial_b @ xi_plus_mj))
        kelvin_loss_exact = -0.5 * (1.0 - (e_rest_mj ** 2)) * float(v_minus_mj @ (lambda_eff @ v_minus_mj))
        dqs_se3_moreau_jean_impact_err = (
            float(np.linalg.norm(v_plus_mj - (-e_rest_mj * v_minus_mj)))
            + float(np.linalg.norm((n_null_eff @ xi_plus_mj) - (n_null_eff @ xi_minus_mj)))
            + abs((ke_plus_mj - ke_minus_mj) - kelvin_loss_exact)
        )
        # Équations en quasi-coordonnées de Poincaré-Chetaev sur se(3) et théorème de puissance gyroscopique nulle :
        # pour T(xi) = 1/2 * xi^T * M_b * xi et p_b = dT/dxi = M_b * xi, l'opérateur d'Euler-Poincaré-Chetaev
        # E_PC(T) = M_b * dxi_dt - ad_{xi}^T * p_b == M_b * dxi_dt + f_gyro_body vérifie :
        # 1) théorème de l'énergie cinétique xi^T * E_PC(T) == xi^T * M_b * dxi_dt == dT/dt (car <ad_{xi}^T * p_b, xi> == <p_b, [xi, xi]> == 0)
        # 2) antisymétrie exacte du crochet de Lie-Poisson sur se(3)^* :
        #    {{F, G}}(p_b) = -<p_b, [xi_F, xi_G]> == -{{G, F}}(p_b) et invariance de Casimir <ad_{xi}^T * p_b, xi> == 0 :
        ad_xi_b = _ad_se3_6x6(xi_b_test)
        e_pc_vec = (m_spatial_b @ dxi_total_uk) + f_gyro_body
        dt_kinetic_uk = float(xi_test_6 @ (m_spatial_b @ dxi_total_uk))
        power_pc_uk = float(xi_test_6 @ e_pc_vec)
        ad_xi1_xi2 = ad_xi_a @ xi_b_test
        ad_xi2_xi1 = ad_xi_b @ xi_test_6
        lp_fg = -float(p_mom_body @ ad_xi1_xi2)
        lp_gf = -float(p_mom_body @ ad_xi2_xi1)
        dqs_se3_poincare_chetaev_err = (
            abs(power_pc_uk - dt_kinetic_uk)
            + abs(float(xi_test_6 @ f_gyro_body))
            + abs(lp_fg + lp_gf)
            + abs(lp_fg + float((ad_xi_a.T @ p_mom_body) @ xi_b_test))
        )
        # Équations de transitivity de Hamel-Boltzmann, dualité de Legendre-Fenchel T(xi) + T*(p) == <p, xi>
        # et identité de courbure coadjointe de Jacobi-Hamel sur se(3)^* :
        # ad_{[xi_1, xi_2]}^T * p_b == (ad_{xi_2}^T * ad_{xi_1}^T - ad_{xi_1}^T * ad_{xi_2}^T) * p_b :
        t_primal_hb = 0.5 * float(xi_test_6 @ (m_spatial_b @ xi_test_6))
        t_dual_hb = 0.5 * float(p_mom_body @ (m_inv_schur_b @ p_mom_body))
        legendre_fenchel_hb = float(p_mom_body @ xi_test_6) - (t_primal_hb + t_dual_hb)
        grad_t_dual_hb = (m_inv_schur_b @ p_mom_body) - xi_test_6
        xi_12_bracket = ad_xi_a @ xi_b_test
        ad_xi12 = _ad_se3_6x6(xi_12_bracket)
        coad_comm_lhs = ad_xi12.T @ p_mom_body
        coad_comm_rhs = ((ad_xi_b.T @ ad_xi_a.T) - (ad_xi_a.T @ ad_xi_b.T)) @ p_mom_body
        dqs_se3_hamel_boltzmann_err = (
            abs(legendre_fenchel_hb)
            + float(np.linalg.norm(grad_t_dual_hb))
            + float(np.linalg.norm(coad_comm_lhs - coad_comm_rhs))
        )
        # Stabilité gyroscopique de Kelvin-Tait-Chetaev sur se(3) :
        # pour la matrice gyroscopique antisymétrique G_gyro = S_pass(xi) = coad(xi)*M_b + M_b*ad(xi) (G_gyro^T == -G_gyro)
        # et une raideur symétrique définie positive K_pos, le faisceau quadratique P(lam) = lam^2 * M_b + lam * G_gyro + K_pos
        # vérifie P(lam)^T == P(-lam), la parité exacte du déterminant séculaire det(P(lam)) == det(P(-lam))
        # et la nullité exacte de la puissance gyroscopique v^T * G_gyro * v == 0 :
        g_gyro_ktc = s_pass_body
        k_pos_ktc = 1.5 * np.eye(6, dtype=np.float64) + 0.25 * (m_spatial_b.T @ m_spatial_b)
        lam_ktc = 0.73
        p_plus_ktc = (lam_ktc ** 2) * m_spatial_b + lam_ktc * g_gyro_ktc + k_pos_ktc
        p_minus_ktc = (lam_ktc ** 2) * m_spatial_b - lam_ktc * g_gyro_ktc + k_pos_ktc
        det_p_plus = float(np.linalg.det(p_plus_ktc))
        det_p_minus = float(np.linalg.det(p_minus_ktc))
        dqs_se3_kelvin_tait_chetaev_err = (
            float(np.linalg.norm(p_plus_ktc.T - p_minus_ktc, ord="fro"))
            + abs(det_p_plus - det_p_minus) / max(abs(det_p_plus), 1.0)
            + abs(float(xi_b_test @ (g_gyro_ktc @ xi_b_test)))
        )
        # Projecteur symplectique-métrique de Dirac-Bergmann pour systèmes hamiltoniens contraints sur se(3)* :
        # le projecteur dual d'impulsion Pi_Dirac = N_e^T = I_6 - J_e^T * J_bar_e^T vérifie :
        # 1) idempotence Pi_Dirac^2 == Pi_Dirac et annihilation de la jacobienne transposée Pi_Dirac * J_e^T == 0_{6x3}
        # 2) symétrie vis-à-vis de la métrique d'inertie Pi_Dirac * M_b == M_b * N_e et de la mobilité N_e * M_b^{-1} == M_b^{-1} * Pi_Dirac
        # 3) invariance de l'impulsion contrainte p_c = Pi_Dirac * p_b sous l'addition de toute réaction idéale J_e^T * lambda_c :
        pi_dirac = n_null_eff.T
        p_constrained_db = pi_dirac @ p_mom_body
        p_shifted_db = pi_dirac @ (p_mom_body + (j_eff_b.T @ lam_c_uk))
        dqs_se3_dirac_bergmann_err = (
            float(np.linalg.norm((pi_dirac @ pi_dirac) - pi_dirac, ord="fro"))
            + float(np.linalg.norm(pi_dirac @ j_eff_b.T, ord="fro"))
            + float(np.linalg.norm((pi_dirac @ m_spatial_b) - (m_spatial_b @ n_null_eff), ord="fro"))
            + float(np.linalg.norm((n_null_eff @ m_inv_schur_b) - (m_inv_schur_b @ pi_dirac), ord="fro"))
            + float(np.linalg.norm(p_shifted_db - p_constrained_db))
        )
        # Bilan de puissance cinétique contrainte et nullité du travail virtuel de la réaction idéale de d'Alembert-Lagrange :
        # pour toute vitesse admissible xi_c = N_e * xi_b (vérifiant J_e * xi_c == 0), la puissance de la réaction idéale
        # <xi_c, F_c> = xi_c^T * (J_e^T * lambda_c) == 0 et le taux de variation d'énergie cinétique contrainte
        # xi_c^T * M_b * a_UK == xi_c^T * (F_act - b_gyro) :
        xi_c_adm = n_null_eff @ xi_b_test
        virtual_power_reaction = float(xi_c_adm @ w_c_uk)
        ke_rate_lhs = float(xi_c_adm @ (m_spatial_b @ dxi_opt_uk))
        ke_rate_rhs = float(xi_c_adm @ (-f_gyro_body))
        dqs_se3_constrained_power_balance_err = (
            abs(virtual_power_reaction)
            + float(np.linalg.norm(j_eff_b @ xi_c_adm))
            + abs(ke_rate_lhs - ke_rate_rhs) / max(abs(ke_rate_rhs), 1.0)
        )
        # Fonction de dissipation visqueuse de Rayleigh R_diss(xi) = 1/2 * xi^T * D_visc * xi sur se(3) :
        # pour D_visc = 0.40 * I_6 + 0.15 * M_b symétrique définie positive, le torseur dissipatif f_diss = -D_visc * xi
        # vérifie l'identité homogène d'Euler <xi, f_diss> == -2 * R_diss(xi) < 0, et la matrice d'amortissement projetée
        # sur le sous-espace contraint D_c = N_e^T * D_visc * N_e est symétrique positive (D_c^T == D_c, xi_b^T * D_c * xi_b == 2*R_diss(xi_c)) :
        d_visc_se3 = 0.40 * np.eye(6, dtype=np.float64) + 0.15 * m_spatial_b
        r_diss_c = 0.5 * float(xi_c_adm @ (d_visc_se3 @ xi_c_adm))
        f_diss_c = -d_visc_se3 @ xi_c_adm
        d_proj_c = n_null_eff.T @ d_visc_se3 @ n_null_eff
        quad_d_proj = float(xi_b_test @ (d_proj_c @ xi_b_test))
        dqs_se3_rayleigh_dissipation_err = (
            float(np.linalg.norm(d_proj_c - d_proj_c.T, ord="fro"))
            + abs(float(xi_c_adm @ f_diss_c) + 2.0 * r_diss_c)
            + abs(quad_d_proj - 2.0 * r_diss_c)
        )
        # Dualité variationnelle de Gauss-Appell dans l'espace des torseurs d'effort se(3)^* :
        # la réaction idéale w_c = J_e^T * lambda_c minimise la co-énergie d'accélération G*(w) = 1/2 * w^T * M_b^{-1} * w
        # sous la contrainte cinématique J_e * M_b^{-1} * w == dv_task - J_e * dxi_free ;
        # pour toute perturbation de torseur dans le noyau de Dirac dw_perp = Pi_Dirac * df_test (vérifiant J_e * M_b^{-1} * dw_perp == 0),
        # on a l'orthogonalité métrique exacte w_c^T * M_b^{-1} * dw_perp == 0 et l'excès pythagoricien G*(w_c + dw_perp) - G*(w_c) == 1/2 * dw_perp^T * M_b^{-1} * dw_perp :
        df_test_6 = np.array([0.35, -0.28, 0.42, -0.19, 0.31, -0.24], dtype=np.float64)
        dw_perp_db = pi_dirac @ df_test_6
        w_pert_db = w_c_uk + dw_perp_db
        g_dual_opt = 0.5 * float(w_c_uk @ (m_inv_schur_b @ w_c_uk))
        g_dual_pert = 0.5 * float(w_pert_db @ (m_inv_schur_b @ w_pert_db))
        g_dual_excess = 0.5 * float(dw_perp_db @ (m_inv_schur_b @ dw_perp_db))
        dqs_se3_dual_gauss_wrench_err = (
            float(np.linalg.norm(j_eff_b @ (m_inv_schur_b @ dw_perp_db)))
            + abs(float(w_c_uk @ (m_inv_schur_b @ dw_perp_db)))
            + abs((g_dual_pert - g_dual_opt) - g_dual_excess)
        )
        # Décomposition orthogonale de Routh-Voss-Maggi de l'espace des accélérations R^6 = ker(J_e) (+) im(M_b^{-1}*J_e^T) :
        # les projecteurs complémentaires P_null = I_6 - M_b^{-1}*J_e^T*Lambda_c*J_e et P_range = M_b^{-1}*J_e^T*Lambda_c*J_e
        # vérifient M_b*P_range == P_range^T*M_b == J_e^T*Lambda_c*J_e, (P_null*xi)^T*M_b*(P_range*xi) == 0,
        # et 1/2*xi^T*M_b*xi == 1/2*(P_null*xi)^T*M_b*(P_null*xi) + 1/2*(J_e*xi)^T*Lambda_c*(J_e*xi) :
        p_range_rm = np.eye(6, dtype=np.float64) - n_null_eff
        xi_rm_test = np.array([0.52, -0.37, 0.44, 0.61, -0.29, 0.33], dtype=np.float64)
        xi_rm_null = n_null_eff @ xi_rm_test
        xi_rm_range = p_range_rm @ xi_rm_test
        v_rm_task = j_eff_b @ xi_rm_test
        t_rm_tot = 0.5 * float(xi_rm_test @ (m_spatial_b @ xi_rm_test))
        t_rm_null = 0.5 * float(xi_rm_null @ (m_spatial_b @ xi_rm_null))
        t_rm_range = 0.5 * float(xi_rm_range @ (m_spatial_b @ xi_rm_range))
        t_rm_op_task = 0.5 * float(v_rm_task @ (lambda_eff @ v_rm_task))
        m_p_range = m_spatial_b @ p_range_rm
        dqs_se3_routh_maggi_splitting_err = (
            float(np.linalg.norm(m_p_range - m_p_range.T, ord="fro"))
            + abs(float(xi_rm_null @ (m_spatial_b @ xi_rm_range)))
            + abs(t_rm_tot - (t_rm_null + t_rm_range))
            + abs(t_rm_range - t_rm_op_task)
        )
        # Système selle de Karush-Kuhn-Tucker (KKT) de la dynamique contrainte sur se(3) et complément de Schur de Delassus :
        # la matrice K_KKT = [[M_b, J_e^T], [J_e, 0_{3x3}]] (9x9) admet l'inverse analytique exact par blocs :
        # K_KKT^{-1} == [[N_e * M_b^{-1}, J_bar_e], [J_bar_e^T, -Lambda_e]],
        # et son déterminant vérifie la formule de Schur : det(K_KKT) == (-1)^3 * det(M_b) * det(J_e * M_b^{-1} * J_e^T) :
        k_kkt = np.zeros((9, 9), dtype=np.float64)
        k_kkt[:6, :6] = m_spatial_b
        k_kkt[:6, 6:] = j_eff_b.T
        k_kkt[6:, :6] = j_eff_b
        k_kkt_inv_analytic = np.zeros((9, 9), dtype=np.float64)
        k_kkt_inv_analytic[:6, :6] = n_null_eff @ m_inv_schur_b
        k_kkt_inv_analytic[:6, 6:] = j_bar_eff
        k_kkt_inv_analytic[6:, :6] = j_bar_eff.T
        k_kkt_inv_analytic[6:, 6:] = -lambda_eff
        det_kkt_direct = float(np.linalg.det(k_kkt))
        det_kkt_schur = -float(np.linalg.det(m_spatial_b)) * float(np.linalg.det(delassus_inv))
        dqs_se3_kkt_schur_err = (
            float(np.linalg.norm((k_kkt @ k_kkt_inv_analytic) - np.eye(9, dtype=np.float64), ord="fro"))
            + float(np.linalg.norm(k_kkt_inv_analytic - k_kkt_inv_analytic.T, ord="fro"))
            + abs(det_kkt_direct - det_kkt_schur) / max(abs(det_kkt_schur), 1.0)
        )
        # Minimalité variationnelle de Gauss-Khatib de la pseudo-inverse dynamiquement cohérente J_bar_e = M_b^{-1} * J_e^T * Lambda_e :
        # 1) identités exactes de Moore-Penrose pondérée : J_e * J_bar_e == I_3, J_bar_e^T * M_b * J_bar_e == Lambda_e, J_bar_e^T * M_b * N_e == 0_{3x6}
        # 2) parmi tous les inverses à droite J_tilde = J_bar_e + N_e * Delta_J (vérifiant J_e * J_tilde == I_3),
        #    J_bar_e minimise exactement la métrique d'inertie opérationnelle : J_tilde^T * M_b * J_tilde - Lambda_e == Delta_J^T * N_e^T * M_b * N_e * Delta_J >= 0 :
        delta_j_pert = np.array(
            [
                [0.25, -0.18, 0.31],
                [-0.22, 0.29, -0.14],
                [0.19, 0.24, -0.27],
                [-0.33, 0.16, 0.21],
                [0.28, -0.25, 0.17],
                [-0.15, 0.32, -0.23],
            ],
            dtype=np.float64,
        )
        j_tilde_pert = j_bar_eff + (n_null_eff @ delta_j_pert)
        excess_op_lhs = (j_tilde_pert.T @ m_spatial_b @ j_tilde_pert) - lambda_eff
        excess_op_rhs = delta_j_pert.T @ (n_null_eff.T @ m_spatial_b @ n_null_eff) @ delta_j_pert
        dqs_se3_khatib_min_ke_err = (
            float(np.linalg.norm((j_eff_b @ j_bar_eff) - np.eye(3, dtype=np.float64), ord="fro"))
            + float(np.linalg.norm((j_eff_b @ j_tilde_pert) - np.eye(3, dtype=np.float64), ord="fro"))
            + float(np.linalg.norm((j_bar_eff.T @ m_spatial_b @ j_bar_eff) - lambda_eff, ord="fro"))
            + float(np.linalg.norm(j_bar_eff.T @ m_spatial_b @ n_null_eff, ord="fro"))
            + float(np.linalg.norm(excess_op_lhs - excess_op_rhs, ord="fro"))
        )
        # Décomposition opérationnelle des torseurs de Khatib-Gauss f_unc = J_e^T * F_op + N_e^T * f_unc
        # avec F_op = J_bar_e^T * f_unc et théorème de Pythagore dual dans la métrique de mobilité M_b^{-1} :
        # 1) f_task^T * M_b^{-1} * f_null == 0 (orthogonalité exacte entre torseur opérationnel et torseur du noyau)
        # 2) f_unc^T * M_b^{-1} * f_unc == F_op^T * Lambda_e^{-1} * F_op + f_null^T * M_b^{-1} * f_null :
        f_unc = np.array([1.35, -0.92, 0.78, -1.14, 0.86, 1.22], dtype=np.float64)
        f_op_eff = j_bar_eff.T @ f_unc
        f_task_6 = j_eff_b.T @ f_op_eff
        f_null_6 = n_null_eff.T @ f_unc
        quad_f_unc = float(f_unc @ (m_inv_schur_b @ f_unc))
        quad_f_task = float(f_task_6 @ (m_inv_schur_b @ f_task_6))
        quad_f_op_delassus = float(f_op_eff @ (delassus_inv @ f_op_eff))
        quad_f_null = float(f_null_6 @ (m_inv_schur_b @ f_null_6))
        dqs_se3_op_wrench_pyth_err = (
            float(np.linalg.norm((f_task_6 + f_null_6) - f_unc))
            + abs(float(f_task_6 @ (m_inv_schur_b @ f_null_6)))
            + abs(quad_f_task - quad_f_op_delassus)
            + abs(quad_f_unc - (quad_f_op_delassus + quad_f_null))
        )
        # Équivalence de norme quadratique duale de Gauss-Delassus-Pontryagin sur la réaction de contrainte :
        # (dxi_UK - dxi_free)^T * M_b * (dxi_UK - dxi_free) == lam_c^T * Delassus * lam_c
        # == (dv_task - J_e*dxi_free)^T * Lambda_e * (dv_task - J_e*dxi_free) == (dxi_UK - dxi_free)^T * w_c :
        err_task_acc = dv_task_uk - (j_eff_b @ dxi_free_uk)
        g2_primal_acc = float(res_uk_g @ (m_spatial_b @ res_uk_g))
        g2_dual_lam = float(lam_c_uk @ (delassus_inv @ lam_c_uk))
        g2_task_err = float(err_task_acc @ (lambda_eff @ err_task_acc))
        g2_virtual_work = float(res_uk_g @ w_c_uk)
        dqs_se3_gauss_delassus_dual_err = (
            abs(g2_primal_acc - g2_dual_lam)
            + abs(g2_primal_acc - g2_task_err)
            + abs(g2_primal_acc - g2_virtual_work)
        )
        # Tenseur de mobilité contrainte de Khatib-Dirac P_mob = N_e * M_b^{-1} = M_b^{-1} * N_e^T = M_b^{-1} - J_bar_e * Lambda_e^{-1} * J_bar_e^T :
        # 1) symétrie exacte P_mob == P_mob^T et annulation sur la Jacobienne de tâche J_e * P_mob == 0_{3x6}, P_mob * J_e^T == 0_{6x3}
        # 2) décomposition additive de la mobilité totale M_b^{-1} == J_bar_e * Lambda_e^{-1} * J_bar_e^T + P_mob :
        p_mob_left = n_null_eff @ m_inv_schur_b
        p_mob_right = m_inv_schur_b @ n_null_eff.T
        p_mob_deflated = m_inv_schur_b - (j_bar_eff @ delassus_inv @ j_bar_eff.T)
        dqs_se3_khatib_constrained_mobility_err = (
            float(np.linalg.norm(p_mob_left - p_mob_left.T, ord="fro"))
            + float(np.linalg.norm(p_mob_left - p_mob_right, ord="fro"))
            + float(np.linalg.norm(p_mob_left - p_mob_deflated, ord="fro"))
            + float(np.linalg.norm(j_eff_b @ p_mob_left, ord="fro"))
            + float(np.linalg.norm(p_mob_left @ j_eff_b.T, ord="fro"))
            + abs(float(f_unc @ (p_mob_left @ f_unc)) - quad_f_null)
        )
        # Les 4 identités de Moore-Penrose pondérées par la métrique cinétique M_b (Udwadia-Kalaba / Khatib) pour J_bar_e = M_b^{-1} * J_e^T * Lambda_e :
        # 1) J_e * J_bar_e * J_e == J_e et J_bar_e * J_e * J_bar_e == J_bar_e
        # 2) auto-adjonction M_b-pondérée : (M_b * J_bar_e * J_e)^T == M_b * J_bar_e * J_e == J_e^T * Lambda_e * J_e et M_b * N_e == N_e^T * M_b :
        mp_cond1 = (j_eff_b @ j_bar_eff @ j_eff_b) - j_eff_b
        mp_cond2 = (j_bar_eff @ j_eff_b @ j_bar_eff) - j_bar_eff
        m_proj_task = m_spatial_b @ (j_bar_eff @ j_eff_b)
        m_proj_task_exact = j_eff_b.T @ lambda_eff @ j_eff_b
        m_null_sym = (m_spatial_b @ n_null_eff) - (n_null_eff.T @ m_spatial_b)
        dqs_se3_udwadia_kalaba_mp_err = (
            float(np.linalg.norm(mp_cond1, ord="fro"))
            + float(np.linalg.norm(mp_cond2, ord="fro"))
            + float(np.linalg.norm(m_proj_task - m_proj_task.T, ord="fro"))
            + float(np.linalg.norm(m_proj_task - m_proj_task_exact, ord="fro"))
            + float(np.linalg.norm(m_null_sym, ord="fro"))
        )
        # Projecteur oblique d'espace opérationnel de Khatib P_op = J_bar_e * J_e, projecteur complémentaire N_e = I_6 - P_op
        # et réflexion d'espace de tâche R_op = P_op - N_e :
        # 1) idempotence et annihilation mutuelle : P_op^2 == P_op, N_e^2 == N_e, P_op * N_e == 0_{6x6}, N_e * P_op == 0_{6x6}
        # 2) partition de trace de rang exact : tr(P_op) == 3, tr(N_e) == 3 et involution R_op^2 == I_6 avec tr(R_op) == 0 et |det(R_op)| == 1 :
        p_op_khatib = j_bar_eff @ j_eff_b
        r_op_khatib = p_op_khatib - n_null_eff
        dqs_se3_khatib_oblique_proj_err = (
            float(np.linalg.norm((p_op_khatib @ p_op_khatib) - p_op_khatib, ord="fro"))
            + float(np.linalg.norm((n_null_eff @ n_null_eff) - n_null_eff, ord="fro"))
            + float(np.linalg.norm(p_op_khatib @ n_null_eff, ord="fro"))
            + float(np.linalg.norm(n_null_eff @ p_op_khatib, ord="fro"))
            + abs(float(np.trace(p_op_khatib)) - 3.0)
            + abs(float(np.trace(n_null_eff)) - 3.0)
            + float(np.linalg.norm((r_op_khatib @ r_op_khatib) - eye6_uk, ord="fro"))
            + abs(float(np.trace(r_op_khatib)))
            + abs(abs(float(np.linalg.det(r_op_khatib))) - 1.0)
        )
        # Découplage additif exact de l'énergie cinétique entre espace de tâche et espace nul de Khatib :
        # pour toute vitesse généralisée qdot = qdot_task + qdot_null avec qdot_task = P_op * qdot et qdot_null = N_e * qdot :
        # 1) M_q-orthogonalité exacte : qdot_task^T * M_q * qdot_null == 0
        # 2) théorème de Pythagore cinétique : 1/2*qdot^T*M_q*qdot == 1/2*qdot_task^T*M_q*qdot_task + 1/2*qdot_null^T*M_q*qdot_null
        # 3) équivalence de l'énergie cinétique opérationnelle : 1/2*qdot_task^T*M_q*qdot_task == 1/2*(J_e*qdot)^T * Lambda_e * (J_e*qdot) :
        qdot_gen = np.array([0.52, -0.37, 0.64, -0.29, 0.45, -0.58], dtype=np.float64)
        qdot_task_k = p_op_khatib @ qdot_gen
        qdot_null_k = n_null_eff @ qdot_gen
        v_task_op = j_eff_b @ qdot_gen
        ke_tot_q = 0.5 * float(qdot_gen @ (m_spatial_b @ qdot_gen))
        ke_task_q = 0.5 * float(qdot_task_k @ (m_spatial_b @ qdot_task_k))
        ke_null_q = 0.5 * float(qdot_null_k @ (m_spatial_b @ qdot_null_k))
        ke_task_op = 0.5 * float(v_task_op @ (lambda_eff @ v_task_op))
        cross_mq_task_null = float(qdot_task_k @ (m_spatial_b @ qdot_null_k))
        dqs_se3_khatib_ke_decoupling_err = (
            abs(cross_mq_task_null)
            + abs(ke_tot_q - (ke_task_q + ke_null_q))
            + abs(ke_task_q - ke_task_op)
            + float(np.linalg.norm((qdot_task_k + qdot_null_k) - qdot_gen))
        )
        # Dualité puissance virtuelle / travail virtuel de Khatib entre vitesses généralisées (P_op, N_e) et couples généralisés (P_op^T, N_e^T) :
        # pour tout couple articulaire tau = tau_task + tau_null avec tau_task = P_op^T * tau = J_e^T * f_op (f_op = J_bar_e^T * tau) et tau_null = N_e^T * tau :
        # 1) puissance virtuelle croisée identiquement nulle : <tau_task, qdot_null> == 0 et <tau_null, qdot_task> == 0
        # 2) équivalence du travail virtuel opérationnel : <tau_task, qdot> == <tau_task, qdot_task> == <f_op, J_e * qdot>
        # 3) partition exacte de la puissance totale : <tau, qdot> == <f_op, J_e * qdot> + <tau_null, qdot_null> :
        tau_gen_k = np.array([-0.65, 0.48, -0.33, 0.71, -0.54, 0.39], dtype=np.float64)
        f_op_k = j_bar_eff.T @ tau_gen_k
        tau_task_k = p_op_khatib.T @ tau_gen_k
        tau_null_k = n_null_eff.T @ tau_gen_k
        vw_tot = float(np.dot(tau_gen_k, qdot_gen))
        vw_task_op = float(np.dot(f_op_k, v_task_op))
        vw_null = float(np.dot(tau_null_k, qdot_null_k))
        dqs_se3_khatib_virtual_work_err = (
            abs(float(np.dot(tau_task_k, qdot_null_k)))
            + abs(float(np.dot(tau_null_k, qdot_task_k)))
            + abs(float(np.dot(tau_task_k, qdot_task_k)) - vw_task_op)
            + abs(vw_tot - (vw_task_op + vw_null))
            + float(np.linalg.norm(tau_task_k - (j_eff_b.T @ f_op_k)))
        )
        # Décomposition de l'impulsion généralisée p_q = M_q * qdot = p_task + p_null (p_task = P_op^T * p_q = J_e^T * p_e, p_null = N_e^T * p_q)
        # et découplage de la co-énergie cinétique dans la métrique de mobilité inverse M_q^{-1} :
        # 1) entrelacement symétrique M_q * P_op == P_op^T * M_q == J_e^T * Lambda_e * J_e
        # 2) M_q^{-1}-orthogonalité des impulsions : p_task^T * M_q^{-1} * p_null == 0
        # 3) partition exacte de la co-énergie : 1/2 * p_q^T * M_q^{-1} * p_q == 1/2 * p_e^T * Lambda_e^{-1} * p_e + 1/2 * p_null^T * M_q^{-1} * p_null :
        p_mom_q = m_spatial_b @ qdot_gen
        p_e_op = j_bar_eff.T @ p_mom_q
        p_task_q = p_op_khatib.T @ p_mom_q
        p_null_q = n_null_eff.T @ p_mom_q
        co_ke_tot = 0.5 * float(p_mom_q @ (m_inv_schur_b @ p_mom_q))
        co_ke_task = 0.5 * float(p_e_op @ (delassus_inv @ p_e_op))
        co_ke_null = 0.5 * float(p_null_q @ (m_inv_schur_b @ p_null_q))
        dqs_se3_khatib_momentum_decomp_err = (
            float(np.linalg.norm((m_spatial_b @ p_op_khatib) - (p_op_khatib.T @ m_spatial_b), ord="fro"))
            + float(np.linalg.norm(p_task_q - (j_eff_b.T @ p_e_op)))
            + abs(float(p_task_q @ (m_inv_schur_b @ p_null_q)))
            + abs(co_ke_tot - (co_ke_task + co_ke_null))
        )
        # Commande d'impédance opérationnelle de Khatib et modelage d'énergie potentielle (Energy Shaping) avec posture dans l'espace nul :
        # pour un écart opérationnel dx_e, une raideur SPD K_p = diag(k1, k2, k3) et un couple de posture tau_post :
        # 1) découplage exact de la loi d'impédance tau_imp = J_e^T * K_p * dx_e + N_e^T * tau_post :
        #    J_bar_e^T * tau_imp == K_p * dx_e et J_e * M_q^{-1} * tau_imp == Lambda_e^{-1} * K_p * dx_e (zéro perturbation posturale)
        # 2) invariance de l'énergie potentielle élastique opérationnelle V_el(dq) = 1/2 * (J_e*dq)^T * K_p * (J_e*dq)
        #    sous toute variation dans l'espace nul dq -> dq + N_e * dq_null :
        kp_imp_op = np.diag([18.0, 24.0, 30.0])
        dx_e_imp = np.array([0.14, -0.22, 0.19], dtype=np.float64)
        tau_post_imp = np.array([0.41, -0.53, 0.28, -0.62, 0.35, -0.47], dtype=np.float64)
        f_el_imp = kp_imp_op @ dx_e_imp
        tau_imp_tot = (j_eff_b.T @ f_el_imp) + (n_null_eff.T @ tau_post_imp)
        f_op_rec_imp = j_bar_eff.T @ tau_imp_tot
        acc_op_imp = j_eff_b @ (m_inv_schur_b @ tau_imp_tot)
        acc_op_imp_exact = delassus_inv @ f_el_imp
        k_joint_imp = j_eff_b.T @ kp_imp_op @ j_eff_b
        dq_imp = qdot_gen
        dq_shifted_imp = dq_imp + (n_null_eff @ tau_post_imp)
        v_el_joint = 0.5 * float(dq_imp @ (k_joint_imp @ dq_imp))
        v_el_shifted = 0.5 * float(dq_shifted_imp @ (k_joint_imp @ dq_shifted_imp))
        v_el_op = 0.5 * float((j_eff_b @ dq_imp) @ (kp_imp_op @ (j_eff_b @ dq_imp)))
        dqs_se3_khatib_impedance_shaping_err = (
            float(np.linalg.norm(f_op_rec_imp - f_el_imp))
            + float(np.linalg.norm(acc_op_imp - acc_op_imp_exact))
            + abs(v_el_joint - v_el_op)
            + abs(v_el_shifted - v_el_op)
        )
        # Passivité dissipative de Rayleigh-Khatib à deux niveaux (amortissement opérationnel Kd_op > 0 + amortissement postural Kd_null > 0) :
        # pour la loi d'amortissement découplée tau_diss = -J_e^T * Kd_op * v_e - N_e^T * Kd_null * N_e * dq :
        # 1) la puissance mécanique dissipée totale dq^T * tau_diss == -2 * (R_op(v_e) + R_null(dq_null)) < 0 se sépare exactement
        #    sans terme croisé entre l'espace de tâche (R_op = 1/2 * v_e^T * Kd_op * v_e) et l'espace nul (R_null = 1/2 * dq_null^T * Kd_null * dq_null)
        # 2) l'accélération opérationnelle induite par l'amortissement de posture est identiquement nulle : J_e * M^{-1} * (N_e^T * Kd_null * N_e * dq) == 0 :
        kd_op_pass = np.diag([4.5, 6.0, 7.5])
        kd_null_pass = np.diag([1.2, 1.5, 1.8, 2.1, 2.4, 2.7])
        ve_pass = j_eff_b @ qdot_gen
        dq_null_pass = n_null_eff @ qdot_gen
        tau_diss_op = -(j_eff_b.T @ (kd_op_pass @ ve_pass))
        tau_diss_null = -(n_null_eff.T @ (kd_null_pass @ dq_null_pass))
        tau_diss_tot = tau_diss_op + tau_diss_null
        r_op_diss = 0.5 * float(ve_pass @ (kd_op_pass @ ve_pass))
        r_null_diss = 0.5 * float(dq_null_pass @ (kd_null_pass @ dq_null_pass))
        p_diss_tot = float(qdot_gen @ tau_diss_tot)
        acc_op_from_null_diss = j_eff_b @ (m_inv_schur_b @ tau_diss_null)
        dqs_se3_khatib_damping_passivity_err = (
            abs(p_diss_tot + 2.0 * (r_op_diss + r_null_diss))
            + abs(float(qdot_gen @ tau_diss_op) + 2.0 * r_op_diss)
            + abs(float(qdot_gen @ tau_diss_null) + 2.0 * r_null_diss)
            + float(np.linalg.norm(acc_op_from_null_diss))
            + (0.0 if (r_op_diss > 0.0 and r_null_diss > 0.0) else 1.0)
        )
        # Découplage dynamique opérationnel de Khatib sous potentiel de posture secondaire V_post(q) = 1/2*(q - q_ref)^T * K_post * (q - q_ref) :
        # pour la loi de commande complète tau_ctrl = J_e^T * Lambda_e * xdd_des - N_e^T * grad_V_post(q) :
        # 1) l'accélération opérationnelle de tâche xdd_e = J_e * M_q^{-1} * tau_ctrl coïncide exactement avec xdd_des
        #    (invariance totale vis-à-vis de la raideur posturale K_post dans l'espace nul)
        # 2) l'accélération articulaire induite dans l'espace nul qdd_null = -M_q^{-1} * N_e^T * grad_V_post(q) appartient au noyau de J_e
        #    et vérifie la descente quadratique stricte <grad_V_post, qdd_null> == -(N_e^T * grad_V_post)^T * M_q^{-1} * (N_e^T * grad_V_post) < 0 :
        k_post_q = np.diag([8.0, 10.0, 12.0, 14.0, 16.0, 18.0])
        dq_post_err = np.array([0.18, -0.24, 0.31, -0.15, 0.27, -0.21], dtype=np.float64)
        grad_v_post = k_post_q @ dq_post_err
        xdd_des_op = np.array([0.65, -0.48, 0.82], dtype=np.float64)
        tau_task_des = j_eff_b.T @ (lambda_eff @ xdd_des_op)
        tau_post_grad = -(n_null_eff.T @ grad_v_post)
        tau_ctrl_tot = tau_task_des + tau_post_grad
        xdd_achieved_op = j_eff_b @ (m_inv_schur_b @ tau_ctrl_tot)
        qdd_null_post = m_inv_schur_b @ tau_post_grad
        desc_post_lhs = float(grad_v_post @ qdd_null_post)
        desc_post_rhs = -float(tau_post_grad @ (m_inv_schur_b @ tau_post_grad))
        dqs_se3_khatib_posture_grad_inv_err = (
            float(np.linalg.norm(xdd_achieved_op - xdd_des_op))
            + float(np.linalg.norm(j_eff_b @ qdd_null_post))
            + abs(desc_post_lhs - desc_post_rhs)
            + (0.0 if desc_post_lhs < 0.0 else 1.0)
        )
        # Hiérarchie de tâches prioritaires de Siciliano-Slotine-Khatib (tâche primaire 2-DDL J_1 = J_e[0:2, :] et tâche secondaire 1-DDL J_2 = J_e[2:3, :]) :
        # avec J_bar_1 = M_q^{-1} * J_1^T * (J_1 * M_q^{-1} * J_1^T)^{-1}, N_1 = I_6 - J_bar_1 * J_1, et le jacobien projeté J_tilde_2 = J_2 * N_1 :
        # 1) zéro interférence de la correction secondaire qdot_2 = J_tilde_2^{#} * (v_2 - J_2 * qdot_1) sur la tâche primaire : J_1 * qdot_2 == 0
        # 2) réalisation simultanée exacte des deux niveaux de priorité : J_1 * (qdot_1 + qdot_2) == v_1 et J_2 * (qdot_1 + qdot_2) == v_2
        # 3) idempotence récursive N_12^2 == N_12 et trace Tr(N_12) == 6 - 3 == 3 du projecteur nul combiné N_12 = N_1 * (I_6 - J_tilde_2^{#} * J_tilde_2) :
        j1_pri = j_eff_b[0:2, :]
        j2_sec = j_eff_b[2:3, :]
        lam1_pri = np.linalg.inv(j1_pri @ m_inv_schur_b @ j1_pri.T)
        jbar1_pri = m_inv_schur_b @ j1_pri.T @ lam1_pri
        n1_pri = eye6_uk - (jbar1_pri @ j1_pri)
        jtilde2_sec = j2_sec @ n1_pri
        lam2_sec = np.linalg.inv(jtilde2_sec @ m_inv_schur_b @ jtilde2_sec.T)
        jbar2_sec = m_inv_schur_b @ jtilde2_sec.T @ lam2_sec
        v1_des_h = np.array([0.42, -0.35], dtype=np.float64)
        v2_des_h = np.array([0.58], dtype=np.float64)
        qdot1_h = jbar1_pri @ v1_des_h
        qdot2_h = n1_pri @ (jbar2_sec @ (v2_des_h - (j2_sec @ qdot1_h)))
        qdot_tot_h = qdot1_h + qdot2_h
        n12_comb = n1_pri @ (eye6_uk - (jbar2_sec @ jtilde2_sec))
        dqs_se3_khatib_priority_hierarchy_err = (
            float(np.linalg.norm(j1_pri @ qdot2_h))
            + float(np.linalg.norm((j1_pri @ qdot_tot_h) - v1_des_h))
            + float(np.linalg.norm((j2_sec @ qdot_tot_h) - v2_des_h))
            + float(np.linalg.norm((n12_comb @ n12_comb) - n12_comb, ord="fro"))
            + abs(float(np.trace(n12_comb)) - 3.0)
        )
        # Décomposition pythagoricienne hiérarchique à 3 niveaux d'énergie cinétique de Siciliano-Slotine-Khatib dans la métrique M_q (m_spatial_b) :
        # pour qdot_full = qdot_1 + qdot_2 + qdot_3 avec qdot_3 = N_12 * qdot_0 (tâche tertiaire de posture résiduelle) :
        # 1) M_q-orthogonalité mutuelle exacte des trois niveaux : qdot_1^T * M_q * qdot_2 == 0, qdot_1^T * M_q * qdot_3 == 0, qdot_2^T * M_q * qdot_3 == 0
        # 2) symétrie de cohérence dynamique du projecteur combiné : M_q * N_12 == N_12^T * M_q
        # 3) théorème de Pythagore cinétique exact : 1/2 * qdot_full^T * M_q * qdot_full == 1/2 * v_1^T * Lambda_1 * v_1 + 1/2 * u_2^T * Lambda_2 * u_2 + 1/2 * qdot_3^T * M_q * qdot_3 :
        qdot0_post_h = np.array([0.31, -0.44, 0.27, -0.19, 0.52, -0.36], dtype=np.float64)
        qdot3_h = n12_comb @ qdot0_post_h
        qdot_full_3h = qdot1_h + qdot2_h + qdot3_h
        u2_eff_h = v2_des_h - (j2_sec @ qdot1_h)
        ke_full_3h = 0.5 * float(qdot_full_3h @ (m_spatial_b @ qdot_full_3h))
        ke_tier1_h = 0.5 * float(v1_des_h @ (lam1_pri @ v1_des_h))
        ke_tier2_h = 0.5 * float(u2_eff_h @ (lam2_sec @ u2_eff_h))
        ke_tier3_h = 0.5 * float(qdot3_h @ (m_spatial_b @ qdot3_h))
        dqs_se3_khatib_hierarchy_ke_pyth_err = (
            abs(float(qdot1_h @ (m_spatial_b @ qdot2_h)))
            + abs(float(qdot1_h @ (m_spatial_b @ qdot3_h)))
            + abs(float(qdot2_h @ (m_spatial_b @ qdot3_h)))
            + float(np.linalg.norm((m_spatial_b @ n12_comb) - (n12_comb.T @ m_spatial_b), ord="fro"))
            + abs(ke_full_3h - (ke_tier1_h + ke_tier2_h + ke_tier3_h))
        )
        # Décomposition hiérarchique des couples d'actionnement à 3 niveaux de Khatib-Sentis-Park
        # tau_tot = J_1^T * F_1 + N_1^T * J_2^T * F_2 + N_12^T * tau_0 dans la métrique de mobilité inverse M_q^{-1} :
        # 1) découplage dynamique strict sans interférence montante : J_bar_1^T * tau_tot == F_1 et J_bar_{2|1}^T * tau_tot == F_2
        # 2) M_q^{-1}-orthogonalité mutuelle exacte des trois niveaux de couples :
        #    tau_1^T * M_q^{-1} * tau_2 == 0, tau_1^T * M_q^{-1} * tau_3 == 0, tau_2^T * M_q^{-1} * tau_3 == 0
        # 3) théorème de Pythagore dual de co-énergie cinétique :
        #    1/2 * tau_tot^T * M_q^{-1} * tau_tot == 1/2 * F_1^T * Lambda_1^{-1} * F_1 + 1/2 * F_2^T * Lambda_{2|1}^{-1} * F_2 + 1/2 * tau_3^T * M_q^{-1} * tau_3 :
        f1_des_h = np.array([1.25, -0.85], dtype=np.float64)
        f2_des_h = np.array([0.95], dtype=np.float64)
        tau0_post_h = np.array([0.44, -0.37, 0.51, -0.29, 0.63, -0.48], dtype=np.float64)
        tau1_h = j1_pri.T @ f1_des_h
        tau2_h = n1_pri.T @ (j2_sec.T @ f2_des_h)
        tau3_h = n12_comb.T @ tau0_post_h
        tau_tot_3h = tau1_h + tau2_h + tau3_h
        co_e_tot_3h = 0.5 * float(tau_tot_3h @ (m_inv_schur_b @ tau_tot_3h))
        co_e_tier1_h = 0.5 * float(f1_des_h @ np.linalg.solve(lam1_pri, f1_des_h))
        co_e_tier2_h = 0.5 * float(f2_des_h @ np.linalg.solve(lam2_sec, f2_des_h))
        co_e_tier3_h = 0.5 * float(tau3_h @ (m_inv_schur_b @ tau3_h))
        dqs_se3_khatib_hierarchical_torque_nullspace_decoupling_err = (
            float(np.linalg.norm((jbar1_pri.T @ tau_tot_3h) - f1_des_h))
            + float(np.linalg.norm((jbar2_sec.T @ tau_tot_3h) - f2_des_h))
            + abs(float(tau1_h @ (m_inv_schur_b @ tau2_h)))
            + abs(float(tau1_h @ (m_inv_schur_b @ tau3_h)))
            + abs(float(tau2_h @ (m_inv_schur_b @ tau3_h)))
            + abs(co_e_tot_3h - (co_e_tier1_h + co_e_tier2_h + co_e_tier3_h))
        )
        # Hiérarchie d'accélération opérationnelle à 2 niveaux de priorité de Khatib-Sentis-Park avec compensation de Coriolis/centrifuge mu_cor :
        # sous M_q * qddot + mu_cor = tau, pour xddot_1 = J_1 * qddot + b_j1 et xddot_2 = J_2 * qddot + b_j2 :
        # avec F_1^{acc} = Lambda_1 * (xddot_{1,d} - b_j1), F_2^{acc} = Lambda_{2|1} * (xddot_{2,d} - b_j2 - J_2 * J_bar_1 * (xddot_{1,d} - b_j1))
        # et tau = mu_cor + J_1^T * F_1^{acc} + N_1^T * J_2^T * F_2^{acc} + N_12^T * tau_damp :
        # 1) réalisation simultanée exacte des deux accélérations de tâche malgré tau_damp arbitraire : xddot_1 == xddot_{1,d} et xddot_2 == xddot_{2,d}
        # 2) optimalité de moindre contrainte de Gauss sur qddot_0 (pour tau_damp = 0) : pour toute variation admissible qddot_cand = qddot_0 + N_12 * z_acc,
        #    1/2 * qddot_cand^T * M_q * qddot_cand == 1/2 * qddot_0^T * M_q * qddot_0 + 1/2 * (N_12 * z_acc)^T * M_q * (N_12 * z_acc) :
        mu_cor_h = np.array([0.38, -0.52, 0.29, -0.41, 0.47, -0.33], dtype=np.float64)
        bj1_bias_h = np.array([0.19, -0.27], dtype=np.float64)
        bj2_bias_h = np.array([-0.16], dtype=np.float64)
        xdd1_des_h = np.array([0.84, -0.63], dtype=np.float64)
        xdd2_des_h = np.array([0.71], dtype=np.float64)
        u1_acc_h = xdd1_des_h - bj1_bias_h
        f1_acc_h = lam1_pri @ u1_acc_h
        f2_acc_h = lam2_sec @ (xdd2_des_h - bj2_bias_h - (j2_sec @ (jbar1_pri @ u1_acc_h)))
        tau_damp_h = np.array([-0.34, 0.46, -0.28, 0.39, -0.51, 0.22], dtype=np.float64)
        tau_acc_tot_h = mu_cor_h + (j1_pri.T @ f1_acc_h) + (n1_pri.T @ (j2_sec.T @ f2_acc_h)) + (n12_comb.T @ tau_damp_h)
        qdd_tot_h = m_inv_schur_b @ (tau_acc_tot_h - mu_cor_h)
        xdd1_ach_h = (j1_pri @ qdd_tot_h) + bj1_bias_h
        xdd2_ach_h = (j2_sec @ qdd_tot_h) + bj2_bias_h
        qdd0_min_h = m_inv_schur_b @ ((j1_pri.T @ f1_acc_h) + (n1_pri.T @ (j2_sec.T @ f2_acc_h)))
        dqdd_null_h = n12_comb @ np.array([0.57, -0.43, 0.61, -0.35, 0.48, -0.26], dtype=np.float64)
        qdd_cand_h = qdd0_min_h + dqdd_null_h
        ga_cand_h = 0.5 * float(qdd_cand_h @ (m_spatial_b @ qdd_cand_h))
        ga_min0_h = 0.5 * float(qdd0_min_h @ (m_spatial_b @ qdd0_min_h))
        ga_null_h = 0.5 * float(dqdd_null_h @ (m_spatial_b @ dqdd_null_h))
        dqs_se3_khatib_sentis_hierarchical_accel_coriolis_gauss_err = (
            float(np.linalg.norm(xdd1_ach_h - xdd1_des_h))
            + float(np.linalg.norm(xdd2_ach_h - xdd2_des_h))
            + abs(float(qdd0_min_h @ (m_spatial_b @ dqdd_null_h)))
            + abs(ga_cand_h - (ga_min0_h + ga_null_h))
        )
        # Découplage d'impédance hiérarchique et passivité de Rayleigh dans l'espace nul dynamiquement cohérent
        # de Dietrich-Ott-Albu-Schäffer (IJRR 2015) : D_hier = J_1^T * D_{x,1} * J_1 + N_1^T * D_0 * N_1 :
        # 1) perturbation nulle d'accélération primaire par tout couple d'impédance de posture : J_1 * M^{-1} * (N_1^T * tau_0) == 0_{2x1}
        # 2) annihilation croisée exacte des opérateurs d'amortissement : (J_1^T * D_{x,1} * J_1) * N_1 == 0_{6x6}
        # 3) définie-positivité stricte SPD de D_hier (lambda_min(D_hier) > 0) et découplage exact de la puissance dissipée de Rayleigh :
        #    qdot^T * D_hier * qdot == xdot_1^T * D_{x,1} * xdot_1 + (N_1 * qdot)^T * D_0 * (N_1 * qdot) :
        dx1_imp = np.array([[3.40, 0.45], [0.45, 2.70]], dtype=np.float64)
        d0_post = (1.80 * np.eye(6, dtype=np.float64)) + (0.35 * m_spatial_b)
        d_pri_6x6 = j1_pri.T @ dx1_imp @ j1_pri
        d_null_6x6 = n1_pri.T @ d0_post @ n1_pri
        d_hier_6x6 = d_pri_6x6 + d_null_6x6
        tau0_imp_arb = np.array([0.67, -0.49, 0.53, -0.38, 0.72, -0.44], dtype=np.float64)
        xdd1_disturb_imp = j1_pri @ (m_inv_schur_b @ (n1_pri.T @ tau0_imp_arb))
        qd_imp_test = np.array([0.58, -0.73, 0.41, -0.62, 0.49, -0.37], dtype=np.float64)
        xd1_imp = j1_pri @ qd_imp_test
        qd_null_imp = n1_pri @ qd_imp_test
        p_diss_tot = float(qd_imp_test @ (d_hier_6x6 @ qd_imp_test))
        p_diss_sum = float(xd1_imp @ (dx1_imp @ xd1_imp)) + float(qd_null_imp @ (d0_post @ qd_null_imp))
        lam_min_dhier = float(np.min(np.linalg.eigvalsh(0.5 * (d_hier_6x6 + d_hier_6x6.T))))
        dqs_se3_dietrich_ott_hierarchical_nullspace_impedance_passivity_err = (
            float(np.linalg.norm(xdd1_disturb_imp))
            + float(np.linalg.norm(d_pri_6x6 @ n1_pri, ord="fro"))
            + float(np.linalg.norm(d_hier_6x6 - d_hier_6x6.T, ord="fro"))
            + abs(p_diss_tot - p_diss_sum)
            + (0.0 if (lam_min_dhier > 0.0 and p_diss_tot > 0.0) else 1.0)
        )
        # Dualité algébrique de projection de Riccati de l'inertie de corps articulé (ABI) de Featherstone (2008) / Jain (2010) sur SE(3) :
        # pour un sous-espace de mouvement S_mot in R^{6x3} et la base réciproque complémentaire d'efforts de liaison T_con in R^{6x3} (T_con^T * S_mot == 0_{3x3}) :
        # 1) identité primale-duale exacte : I^A_primal = M - M*S*(S^T*M*S)^{-1}*S^T*M == T*(T^T*M^{-1}*T)^{-1}*T^T = I^A_dual
        # 2) annihilation du sous-espace libre I^A * S == 0_{6x3}, idempotence pondérée par la mobilité I^A * M^{-1} * I^A == I^A et Tr(I^A * M^{-1}) == 3
        # 3) théorème de Pythagore de l'énergie d'accélération de Gauss : 1/2*a^T*M*a == 1/2*a^T*I^A*a + 1/2*(qdd^*)^T*(S^T*M*S)*qdd^* :
        a_cpl_3x3 = np.array(
            [
                [0.42, -0.31, 0.25],
                [0.19, 0.53, -0.37],
                [-0.28, 0.24, 0.46],
            ],
            dtype=np.float64,
        )
        eye3_abi = np.eye(3, dtype=np.float64)
        s_mot_6x3 = np.vstack([eye3_abi, a_cpl_3x3])
        t_con_6x3 = np.vstack([-a_cpl_3x3.T, eye3_abi])
        ds_abi_3x3 = s_mot_6x3.T @ m_spatial_b @ s_mot_6x3
        gt_abi_3x3 = t_con_6x3.T @ m_inv_schur_b @ t_con_6x3
        ia_primal_6x6 = m_spatial_b - (m_spatial_b @ s_mot_6x3 @ np.linalg.solve(ds_abi_3x3, s_mot_6x3.T @ m_spatial_b))
        ia_dual_6x6 = t_con_6x3 @ np.linalg.solve(gt_abi_3x3, t_con_6x3.T)
        a_sp_abi = np.array([0.74, -0.59, 0.48, -0.66, 0.51, -0.39], dtype=np.float64)
        qdd_opt_abi = -np.linalg.solve(ds_abi_3x3, s_mot_6x3.T @ (m_spatial_b @ a_sp_abi))
        a_tot_abi = a_sp_abi + (s_mot_6x3 @ qdd_opt_abi)
        e_acc_min_abi = 0.5 * float(a_tot_abi @ (m_spatial_b @ a_tot_abi))
        e_acc_ia_abi = 0.5 * float(a_sp_abi @ (ia_primal_6x6 @ a_sp_abi))
        e_acc_raw_abi = 0.5 * float(a_sp_abi @ (m_spatial_b @ a_sp_abi))
        e_acc_red_abi = 0.5 * float(qdd_opt_abi @ (ds_abi_3x3 @ qdd_opt_abi))
        dqs_se3_featherstone_jain_articulated_body_riccati_duality_err = (
            float(np.linalg.norm(t_con_6x3.T @ s_mot_6x3, ord="fro"))
            + float(np.linalg.norm(ia_primal_6x6 - ia_dual_6x6, ord="fro"))
            + float(np.linalg.norm(ia_primal_6x6 @ s_mot_6x3, ord="fro"))
            + float(np.linalg.norm((ia_primal_6x6 @ m_inv_schur_b @ ia_primal_6x6) - ia_primal_6x6, ord="fro"))
            + abs(float(np.trace(ia_primal_6x6 @ m_inv_schur_b)) - 3.0)
            + abs(e_acc_min_abi - e_acc_ia_abi)
            + abs(e_acc_raw_abi - (e_acc_ia_abi + e_acc_red_abi))
        )
        # Décomposition orthogonale de mobilité spatiale 6x6 de Rodriguez-Jain-Kreutz-Delgado (1991/1992) sur SE(3) :
        # M^{-1} = Phi_free + Phi_con avec Phi_free = S*(S^T*M*S)^{-1}*S^T et Phi_con = M^{-1}*T*(T^T*M^{-1}*T)^{-1}*T^T*M^{-1} = M^{-1}*I^A*M^{-1} :
        # 1) partition exacte de la mobilité inverse : Phi_free + Phi_con == M^{-1} et M-orthogonalité mutuelle Phi_free * M * Phi_con == 0_{6x6}
        # 2) idempotence pondérée par M : Phi_free * M * Phi_free == Phi_free, Phi_con * M * Phi_con == Phi_con et Tr(Phi_free * M) == Tr(Phi_con * M) == 3
        # 3) théorème de Pythagore de la co-énergie de torseur d'effort : 1/2*f_w^T*M^{-1}*f_w == 1/2*tau_S^T*D_S^{-1}*tau_S + 1/2*v_con^T*G_T^{-1}*v_con :
        phi_free_6x6 = s_mot_6x3 @ np.linalg.solve(ds_abi_3x3, s_mot_6x3.T)
        phi_con_6x6 = m_inv_schur_b @ t_con_6x3 @ np.linalg.solve(gt_abi_3x3, t_con_6x3.T @ m_inv_schur_b)
        fw_sp_rjk = np.array([0.83, -0.47, 0.65, -0.52, 0.71, -0.38], dtype=np.float64)
        tau_s_rjk = s_mot_6x3.T @ fw_sp_rjk
        v_con_rjk = t_con_6x3.T @ (m_inv_schur_b @ fw_sp_rjk)
        lam_con_rjk = -np.linalg.solve(gt_abi_3x3, v_con_rjk)
        a_con_rjk = m_inv_schur_b @ (fw_sp_rjk + (t_con_6x3 @ lam_con_rjk))
        co_e_tot_rjk = 0.5 * float(fw_sp_rjk @ (m_inv_schur_b @ fw_sp_rjk))
        co_e_free_rjk = 0.5 * float(tau_s_rjk @ np.linalg.solve(ds_abi_3x3, tau_s_rjk))
        co_e_con_rjk = 0.5 * float(v_con_rjk @ np.linalg.solve(gt_abi_3x3, v_con_rjk))
        dqs_se3_rodriguez_jain_mobility_splitting_wrench_pythagoras_err = (
            float(np.linalg.norm((phi_free_6x6 + phi_con_6x6) - m_inv_schur_b, ord="fro"))
            + float(np.linalg.norm(phi_con_6x6 - (m_inv_schur_b @ ia_primal_6x6 @ m_inv_schur_b), ord="fro"))
            + float(np.linalg.norm(phi_free_6x6 @ m_spatial_b @ phi_con_6x6, ord="fro"))
            + float(np.linalg.norm((phi_free_6x6 @ m_spatial_b @ phi_free_6x6) - phi_free_6x6, ord="fro"))
            + abs(float(np.trace(phi_free_6x6 @ m_spatial_b)) - 3.0)
            + float(np.linalg.norm(a_con_rjk - (phi_free_6x6 @ fw_sp_rjk)))
            + abs(co_e_tot_rjk - (co_e_free_rjk + co_e_con_rjk))
        )
        # Dualité variationnelle de point-selle de Legendre-Fenchel / Gauss-Moreau sur SE(3) entre la minimisation primale
        # sous contrainte cinématique min_{T^T*a = 0} [1/2*a^T*M*a - f_tot^T*a] et la maximisation duale de Delassus-Lagrange
        # max_{lambda in R^3} [-1/2*(f_tot + T*lambda)^T*M^{-1}*(f_tot + T*lambda)] :
        # 1) coïncidence exacte des solutions primale a* = Phi_free * f_tot et duale a* = M^{-1} * (f_tot + T*lambda*)
        # 2) biorthogonalité de puissance de réaction nulle : (a*)^T * (T*lambda*) == 0, T^T*a* == 0_3 et S^T*(M*a* - f_tot) == 0_3
        # 3) saut de dualité de Fenchel-Young strictement nul : P_Gauss(a*) == D_Delassus(lambda*) == -1/2 * f_tot^T * Phi_free * f_tot :
        a0_lf = np.array([0.44, -0.37, 0.29, -0.51, 0.63, -0.27], dtype=np.float64)
        fe_lf = np.array([-0.68, 0.54, -0.41, 0.77, -0.35, 0.49], dtype=np.float64)
        ftot_lf = (m_spatial_b @ a0_lf) + fe_lf
        a_star_prim = phi_free_6x6 @ ftot_lf
        lam_star_dual = -np.linalg.solve(gt_abi_3x3, t_con_6x3.T @ (m_inv_schur_b @ ftot_lf))
        f_react_dual = t_con_6x3 @ lam_star_dual
        a_star_dual = m_inv_schur_b @ (ftot_lf + f_react_dual)
        p_gauss_opt = (0.5 * float(a_star_prim @ (m_spatial_b @ a_star_prim))) - float(ftot_lf @ a_star_prim)
        w_dual_vec = ftot_lf + f_react_dual
        d_delassus_opt = -0.5 * float(w_dual_vec @ (m_inv_schur_b @ w_dual_vec))
        closed_val_lf = -0.5 * float(ftot_lf @ (phi_free_6x6 @ ftot_lf))
        dqs_se3_legendre_fenchel_gauss_delassus_zero_duality_gap_err = (
            float(np.linalg.norm(a_star_prim - a_star_dual))
            + float(np.linalg.norm(t_con_6x3.T @ a_star_prim))
            + float(np.linalg.norm(s_mot_6x3.T @ ((m_spatial_b @ a_star_prim) - ftot_lf)))
            + abs(float(a_star_prim @ f_react_dual))
            + abs(p_gauss_opt - d_delassus_opt)
            + abs(p_gauss_opt - closed_val_lf)
        )
        # Régularisation compliante de Moreau-Yosida / Tikhonov-Woodbury-Delassus des contraintes articulaires sur SE(3) :
        # pour une compliance articulaire définie positive C_c = eps * K_c^{-1} > 0 et M_eps = M + T * C_c^{-1} * T^T :
        # 1) identité exacte de Woodbury-Delassus : M_eps^{-1} == M^{-1} - M^{-1} * T * (C_c + G_T)^{-1} * T^T * M^{-1}
        # 2) bilan énergétique cinétique + élastique exact du système KKT compliant : 1/2*a_eps^T*M*a_eps + 1/2*lam_eps^T*C_c*lam_eps == 1/2*f_tot^T*M_eps^{-1}*f_tot
        # 3) déterminant de Sylvester-Weinstein det(M_eps)*det(C_c) == det(M)*det(C_c + G_T) et sandwich monotone de Loewner (eps_2 < eps_1) :
        kc_inv_base = np.diag([0.42, 0.55, 0.37])
        eps1_my = 0.24
        eps2_my = 0.06
        cc1_3x3 = eps1_my * kc_inv_base
        cc2_3x3 = eps2_my * kc_inv_base
        cc1_inv_3x3 = np.diag([1.0 / (eps1_my * 0.42), 1.0 / (eps1_my * 0.55), 1.0 / (eps1_my * 0.37)])
        cc2_inv_3x3 = np.diag([1.0 / (eps2_my * 0.42), 1.0 / (eps2_my * 0.55), 1.0 / (eps2_my * 0.37)])
        m_eps1_6x6 = m_spatial_b + (t_con_6x3 @ cc1_inv_3x3 @ t_con_6x3.T)
        m_eps2_6x6 = m_spatial_b + (t_con_6x3 @ cc2_inv_3x3 @ t_con_6x3.T)
        m_eps1_inv_wood = m_inv_schur_b - (m_inv_schur_b @ t_con_6x3 @ np.linalg.solve(cc1_3x3 + gt_abi_3x3, t_con_6x3.T @ m_inv_schur_b))
        m_eps2_inv_wood = m_inv_schur_b - (m_inv_schur_b @ t_con_6x3 @ np.linalg.solve(cc2_3x3 + gt_abi_3x3, t_con_6x3.T @ m_inv_schur_b))
        a_eps1_primal = np.linalg.solve(m_eps1_6x6, ftot_lf)
        lam_eps1_dual = -np.linalg.solve(cc1_3x3 + gt_abi_3x3, t_con_6x3.T @ (m_inv_schur_b @ ftot_lf))
        a_eps1_kkt = m_inv_schur_b @ (ftot_lf + (t_con_6x3 @ lam_eps1_dual))
        e_kin_el_1 = (0.5 * float(a_eps1_primal @ (m_spatial_b @ a_eps1_primal))) + (
            0.5 * float(lam_eps1_dual @ (cc1_3x3 @ lam_eps1_dual))
        )
        e_dual_mob_1 = 0.5 * float(ftot_lf @ (m_eps1_inv_wood @ ftot_lf))
        det_lhs_my = float(np.linalg.det(m_eps1_6x6)) * float(np.linalg.det(cc1_3x3))
        det_rhs_my = float(np.linalg.det(m_spatial_b)) * float(np.linalg.det(cc1_3x3 + gt_abi_3x3))
        q_rigid_my = float(ftot_lf @ (phi_free_6x6 @ ftot_lf))
        q_eps2_my = float(ftot_lf @ (m_eps2_inv_wood @ ftot_lf))
        q_eps1_my = float(ftot_lf @ (m_eps1_inv_wood @ ftot_lf))
        q_free_my = float(ftot_lf @ (m_inv_schur_b @ ftot_lf))
        dqs_se3_moreau_yosida_compliant_delassus_woodbury_err = (
            float(np.linalg.norm((m_eps1_6x6 @ m_eps1_inv_wood) - np.eye(6, dtype=np.float64), ord="fro"))
            + float(np.linalg.norm((m_eps2_6x6 @ m_eps2_inv_wood) - np.eye(6, dtype=np.float64), ord="fro"))
            + float(np.linalg.norm(a_eps1_primal - a_eps1_kkt))
            + float(np.linalg.norm((t_con_6x3.T @ a_eps1_primal) + (cc1_3x3 @ lam_eps1_dual)))
            + abs(e_kin_el_1 - e_dual_mob_1)
            + (abs(det_lhs_my - det_rhs_my) / max(abs(det_rhs_my), 1.0))
            + (0.0 if (0.0 < q_rigid_my < q_eps2_my < q_eps1_my < q_free_my) else 1.0)
        )
        # Méthode du Lagrangien augmenté de Hestenes-Powell (1969) et contraction spectrale d'Uzawa sur SE(3) :
        # pour M_rho = M + rho * T * T^T (rho = 8.5 > 0) et la récurrence duale a^{(k)} = M_rho^{-1}*(f_tot + T*lam^{(k)}), lam^{(k+1)} = lam^{(k)} - rho*T^T*a^{(k)} :
        # 1) inverse de Woodbury M_rho^{-1} == M^{-1} - M^{-1}*T*(rho^{-1}*I_3 + G_T)^{-1}*T^T*M^{-1} et point fixe exact a(lam*) == a*
        # 2) propagation linéaire exacte de l'erreur duale : lam^{(k+1)} - lam* == (I_3 + rho*G_T)^{-1} * (lam^{(k)} - lam*)
        # 3) contraction géométrique inconditionnelle de taux spectral kappa_ALM = 1 / (1 + rho * lambda_min(G_T)) < 1 :
        rho_alm_hp = 8.5
        eye3_alm = np.eye(3, dtype=np.float64)
        eye6_alm = np.eye(6, dtype=np.float64)
        m_rho_alm = m_spatial_b + (rho_alm_hp * (t_con_6x3 @ t_con_6x3.T))
        inv_rho_gt_alm = np.linalg.inv(((1.0 / rho_alm_hp) * eye3_alm) + gt_abi_3x3)
        m_rho_inv_wood = m_inv_schur_b - (m_inv_schur_b @ t_con_6x3 @ inv_rho_gt_alm @ t_con_6x3.T @ m_inv_schur_b)
        c_uzawa_mat = np.linalg.inv(eye3_alm + (rho_alm_hp * gt_abi_3x3))
        ev_gt_alm = np.linalg.eigvalsh(0.5 * (gt_abi_3x3 + gt_abi_3x3.T))
        ev_c_uzawa = np.linalg.eigvalsh(0.5 * (c_uzawa_mat + c_uzawa_mat.T))
        kappa_alm_hp = 1.0 / (1.0 + (rho_alm_hp * float(np.min(ev_gt_alm))))
        a_fp_alm = np.linalg.solve(m_rho_alm, ftot_lf + (t_con_6x3 @ lam_star_dual))
        lam_cur_alm = np.array([0.85, -0.62, 0.47], dtype=np.float64)
        uzawa_step_err = 0.0
        uzawa_strict_dec = True
        for _ in range(3):
            err_prev_alm = lam_cur_alm - lam_star_dual
            a_cur_alm = np.linalg.solve(m_rho_alm, ftot_lf + (t_con_6x3 @ lam_cur_alm))
            lam_next_alm = lam_cur_alm - (rho_alm_hp * (t_con_6x3.T @ a_cur_alm))
            err_next_alm = lam_next_alm - lam_star_dual
            uzawa_step_err += float(np.linalg.norm(err_next_alm - (c_uzawa_mat @ err_prev_alm)))
            if float(np.linalg.norm(err_next_alm)) > (kappa_alm_hp * float(np.linalg.norm(err_prev_alm))) + 1e-14:
                uzawa_strict_dec = False
            lam_cur_alm = lam_next_alm
        dqs_se3_hestenes_powell_augmented_lagrangian_uzawa_contraction_err = (
            float(np.linalg.norm((m_rho_alm @ m_rho_inv_wood) - eye6_alm, ord="fro"))
            + float(np.linalg.norm(a_fp_alm - a_star_prim))
            + float(np.linalg.norm(t_con_6x3.T @ a_fp_alm))
            + abs(float(np.max(ev_c_uzawa)) - kappa_alm_hp)
            + uzawa_step_err
            + (0.0 if (0.0 < kappa_alm_hp < 1.0 and uzawa_strict_dec) else 1.0)
        )
        # Splitting d'opérateurs ADMM de Gabay-Mercier (1976) / Douglas-Rachford (Lions-Mercier 1979) sur la dynamique SE(3) compliante :
        # pour min_{a, z} (1/2*a^T*M*a - f_tot^T*a) + 1/2*z^T*C_1^{-1}*z sous T^T*a - z = 0 (rho_admm = 4.0 > 0) :
        # 1) point fixe KKT exact (a_eps1_primal, z* = -C_1*lam_eps1_dual, lam_eps1_dual) et invariant dual z^{(k+1)} == -C_1*lam^{(k+1)}
        # 2) réflexions de Cayley contractantes R_A = (I_3 - rho*G_T)*(I_3 + rho*G_T)^{-1}, R_B = (I_3 - rho*C_1)*(I_3 + rho*C_1)^{-1} (||R_A||_2 < 1, ||R_B||_2 < 1)
        #    et équivalence exacte de Gabay-Eckstein : w^{(k+1)} == T_DR * w^{(k)} avec T_DR = 1/2*(I_3 + R_A*R_B) et w^{(k)} = (I_3 + rho*C_1)*(lam^{(k)} - lam*)
        # 3) non-expansivité ferme exacte de Lions-Mercier : <v, T_DR*v> - ||T_DR*v||_2^2 == 1/4*(||v||_2^2 - ||R_A*R_B*v||_2^2) > 0 :
        rho_dr_admm = 4.0
        m_admm_6x6 = m_spatial_b + (rho_dr_admm * (t_con_6x3 @ t_con_6x3.T))
        z_denom_admm = cc1_inv_3x3 + (rho_dr_admm * eye3_alm)
        z_star_admm = -(cc1_3x3 @ lam_eps1_dual)
        a_fp_admm = np.linalg.solve(m_admm_6x6, ftot_lf + (t_con_6x3 @ (lam_eps1_dual + (rho_dr_admm * z_star_admm))))
        z_fp_admm = np.linalg.solve(z_denom_admm, (-lam_eps1_dual) + (rho_dr_admm * (t_con_6x3.T @ a_fp_admm)))
        ra_cayley_dr = (eye3_alm - (rho_dr_admm * gt_abi_3x3)) @ np.linalg.inv(eye3_alm + (rho_dr_admm * gt_abi_3x3))
        rb_cayley_dr = (eye3_alm - (rho_dr_admm * cc1_3x3)) @ np.linalg.inv(eye3_alm + (rho_dr_admm * cc1_3x3))
        t_dr_mat = 0.5 * (eye3_alm + (ra_cayley_dr @ rb_cayley_dr))
        norm2_ra_dr = float(np.linalg.norm(ra_cayley_dr, ord=2))
        norm2_rb_dr = float(np.linalg.norm(rb_cayley_dr, ord=2))
        kappa_dr_admm = 0.5 * (1.0 + (norm2_ra_dr * norm2_rb_dr))
        v_probe_dr = np.array([0.73, -0.51, 0.64], dtype=np.float64)
        tv_probe_dr = t_dr_mat @ v_probe_dr
        rarbv_probe_dr = ra_cayley_dr @ (rb_cayley_dr @ v_probe_dr)
        fne_lhs_dr = float(v_probe_dr @ tv_probe_dr) - float(tv_probe_dr @ tv_probe_dr)
        fne_rhs_dr = 0.25 * (float(v_probe_dr @ v_probe_dr) - float(rarbv_probe_dr @ rarbv_probe_dr))
        lam_k_admm = np.array([0.68, -0.49, 0.57], dtype=np.float64)
        z_k_admm = -(cc1_3x3 @ lam_k_admm)
        admm_dr_step_err = 0.0
        admm_dr_strict_dec = True
        scale_w_admm = eye3_alm + (rho_dr_admm * cc1_3x3)
        for _ in range(3):
            w_prev_admm = scale_w_admm @ (lam_k_admm - lam_eps1_dual)
            a_next_admm = np.linalg.solve(m_admm_6x6, ftot_lf + (t_con_6x3 @ (lam_k_admm + (rho_dr_admm * z_k_admm))))
            z_next_admm = np.linalg.solve(z_denom_admm, (-lam_k_admm) + (rho_dr_admm * (t_con_6x3.T @ a_next_admm)))
            lam_next_admm = lam_k_admm - (rho_dr_admm * ((t_con_6x3.T @ a_next_admm) - z_next_admm))
            w_next_admm = scale_w_admm @ (lam_next_admm - lam_eps1_dual)
            admm_dr_step_err += float(np.linalg.norm(z_next_admm + (cc1_3x3 @ lam_next_admm)))
            admm_dr_step_err += float(np.linalg.norm(w_next_admm - (t_dr_mat @ w_prev_admm)))
            if float(np.linalg.norm(w_next_admm)) > (kappa_dr_admm * float(np.linalg.norm(w_prev_admm))) + 1e-14:
                admm_dr_strict_dec = False
            lam_k_admm = lam_next_admm
            z_k_admm = z_next_admm
        dqs_se3_gabay_mercier_admm_douglas_rachford_contraction_err = (
            float(np.linalg.norm(a_fp_admm - a_eps1_primal))
            + float(np.linalg.norm(z_fp_admm - z_star_admm))
            + abs(fne_lhs_dr - fne_rhs_dr)
            + admm_dr_step_err
            + (
                0.0
                if (
                    0.0 < norm2_ra_dr < 1.0
                    and 0.0 < norm2_rb_dr < 1.0
                    and 0.0 < kappa_dr_admm < 1.0
                    and fne_rhs_dr > 1e-4
                    and admm_dr_strict_dec
                )
                else 1.0
            )
        )
        # Éclatement symétrique d'opérateurs de Peaceman-Rachford (1955) / Kellogg (1969) T_{PR}(rho*) = R_B(rho*)*R_A(rho*)
        # et pénalité minimax optimale de Cayley rho* = 1/sqrt(lambda_min(G_T)*lambda_max(G_T)) sur la dynamique conforme SE(3) :
        # 1) au paramètre optimal de Kellogg rho*, ||R_A(rho*)||_2 == (sqrt(kappa(G_T)) - 1)/(sqrt(kappa(G_T)) + 1) < min(||R_A(0.5*rho*)||_2, ||R_A(2*rho*)||_2) < 1
        # 2) point fixe exact v* = lam* + rho* * z* invariant par les deux demi-pas primal-dual de Peaceman-Rachford (a_fp == a*, z_fp == z*)
        # 3) récurrence linéaire exacte v_{k+1} - v* == R_B(rho*)*R_A(rho*)*(v_k - v*) et accélération stricte 0 < kappa_{PR}(rho*) < kappa_{DR}(rho*) < 1 :
        ev_gt_pr = np.linalg.eigvalsh(0.5 * (gt_abi_3x3 + gt_abi_3x3.T))
        lmin_gt_pr = float(ev_gt_pr[0])
        lmax_gt_pr = float(ev_gt_pr[2])
        rho_opt_pr = 1.0 / math.sqrt(max(lmin_gt_pr * lmax_gt_pr, 1e-30))
        sqrt_kap_gt_pr = math.sqrt(lmax_gt_pr / max(lmin_gt_pr, 1e-30))
        ra_opt_expected_pr = (sqrt_kap_gt_pr - 1.0) / (sqrt_kap_gt_pr + 1.0)
        ra_opt_pr = (eye3_alm - (rho_opt_pr * gt_abi_3x3)) @ np.linalg.inv(eye3_alm + (rho_opt_pr * gt_abi_3x3))
        rb_opt_pr = (eye3_alm - (rho_opt_pr * cc1_3x3)) @ np.linalg.inv(eye3_alm + (rho_opt_pr * cc1_3x3))
        ra_low_pr = (eye3_alm - (0.5 * rho_opt_pr * gt_abi_3x3)) @ np.linalg.inv(eye3_alm + (0.5 * rho_opt_pr * gt_abi_3x3))
        ra_high_pr = (eye3_alm - (2.0 * rho_opt_pr * gt_abi_3x3)) @ np.linalg.inv(eye3_alm + (2.0 * rho_opt_pr * gt_abi_3x3))
        nrm_ra_opt_pr = float(np.linalg.norm(ra_opt_pr, ord=2))
        nrm_rb_opt_pr = float(np.linalg.norm(rb_opt_pr, ord=2))
        nrm_ra_low_pr = float(np.linalg.norm(ra_low_pr, ord=2))
        nrm_ra_high_pr = float(np.linalg.norm(ra_high_pr, ord=2))
        t_pr_mat = rb_opt_pr @ ra_opt_pr
        kappa_pr_opt = nrm_ra_opt_pr * nrm_rb_opt_pr
        kappa_dr_at_opt = 0.5 * (1.0 + kappa_pr_opt)
        m_pr_6x6 = m_spatial_b + (rho_opt_pr * (t_con_6x3 @ t_con_6x3.T))
        z_denom_pr = cc1_inv_3x3 + (rho_opt_pr * eye3_alm)
        v_star_pr = lam_eps1_dual + (rho_opt_pr * z_star_admm)
        a_fp_pr = np.linalg.solve(m_pr_6x6, ftot_lf + (t_con_6x3 @ v_star_pr))
        u_fp_pr = v_star_pr - ((2.0 * rho_opt_pr) * (t_con_6x3.T @ a_fp_pr))
        z_fp_pr = np.linalg.solve(z_denom_pr, -u_fp_pr)
        v_fp_next_pr = u_fp_pr + ((2.0 * rho_opt_pr) * z_fp_pr)
        v_k_pr = np.array([0.81, -0.57, 0.46], dtype=np.float64)
        pr_step_err = 0.0
        pr_strict_dec = True
        for _ in range(3):
            dv_prev_pr = v_k_pr - v_star_pr
            ak_pr = np.linalg.solve(m_pr_6x6, ftot_lf + (t_con_6x3 @ v_k_pr))
            uk_pr = v_k_pr - ((2.0 * rho_opt_pr) * (t_con_6x3.T @ ak_pr))
            zk_pr = np.linalg.solve(z_denom_pr, -uk_pr)
            lamk_pr = uk_pr + (rho_opt_pr * zk_pr)
            v_next_pr = uk_pr + ((2.0 * rho_opt_pr) * zk_pr)
            dv_next_pr = v_next_pr - v_star_pr
            pr_step_err += float(np.linalg.norm(zk_pr + (cc1_3x3 @ lamk_pr)))
            pr_step_err += float(np.linalg.norm(v_next_pr - (lamk_pr + (rho_opt_pr * zk_pr))))
            pr_step_err += float(np.linalg.norm(dv_next_pr - (t_pr_mat @ dv_prev_pr)))
            if float(np.linalg.norm(dv_next_pr)) > (kappa_pr_opt * float(np.linalg.norm(dv_prev_pr))) + 1e-14:
                pr_strict_dec = False
            v_k_pr = v_next_pr
        dqs_se3_peaceman_rachford_kellogg_optimal_cayley_contraction_err = (
            abs(nrm_ra_opt_pr - ra_opt_expected_pr)
            + float(np.linalg.norm(a_fp_pr - a_eps1_primal))
            + float(np.linalg.norm(z_fp_pr - z_star_admm))
            + float(np.linalg.norm(v_fp_next_pr - v_star_pr))
            + pr_step_err
            + (
                0.0
                if (
                    0.0 < nrm_ra_opt_pr < min(nrm_ra_low_pr, nrm_ra_high_pr) < 1.0
                    and 0.0 < nrm_rb_opt_pr < 1.0
                    and 0.0 < kappa_pr_opt < kappa_dr_at_opt < 1.0
                    and pr_strict_dec
                )
                else 1.0
            )
        )
        # Algorithme primal-dual hybride de Chambolle-Pock (2011, J. Math. Imaging Vis. 40:120, theta=1)
        # et identité variationnelle de dissipation de He-Yuan (2012, SIAM J. Imaging Sci. 5:119) sur le point-selle conforme SE(3) :
        # 1) condition spectrale tau*sigma*||T||_2^2 = 0.7225 < 1 garantissant la définie-positivité stricte P_{HY} = [[I_6/tau, T], [T^T, I_3/sigma]] > 0
        # 2) stationnarité exacte du point-selle conforme (a*, lam*) sous l'itération PDHG à extrapolation d'inertie a_bar = 2*a_{k+1} - a_k
        # 3) identité de dissipation exacte ||w_k - w*||_{P_{HY}}^2 - ||w_{k+1} - w*||_{P_{HY}}^2 == ||w_k - w_{k+1}||_{P_{HY}}^2 + 2*(||a_{k+1} - a*||_M^2 + ||lam_{k+1} - lam*||_{C_1}^2) > 0 :
        nrm2_t_cp = float(np.linalg.norm(t_con_6x3, ord=2))
        tau_cp = 0.85 / max(nrm2_t_cp, 1e-12)
        sigma_cp = 0.85 / max(nrm2_t_cp, 1e-12)
        eye6_cp = np.eye(6, dtype=np.float64)
        p_hy_9x9 = np.block([[eye6_cp / tau_cp, t_con_6x3], [t_con_6x3.T, eye3_alm / sigma_cp]])
        ev_phy_cp = np.linalg.eigvalsh(0.5 * (p_hy_9x9 + p_hy_9x9.T))
        m_cp_lhs = (eye6_cp / tau_cp) + m_spatial_b
        c_cp_lhs = (eye3_alm / sigma_cp) + cc1_3x3
        a_fp_cp = np.linalg.solve(m_cp_lhs, (a_eps1_primal / tau_cp) + ftot_lf + (t_con_6x3 @ lam_eps1_dual))
        abar_fp_cp = (2.0 * a_fp_cp) - a_eps1_primal
        lam_fp_cp = np.linalg.solve(c_cp_lhs, (lam_eps1_dual / sigma_cp) - (t_con_6x3.T @ abar_fp_cp))
        w_star_cp = np.concatenate([a_eps1_primal, lam_eps1_dual])
        ak_cp = a_eps1_primal + np.array([0.42, -0.31, 0.27, -0.48, 0.19, 0.35], dtype=np.float64)
        lk_cp = lam_eps1_dual + np.array([-0.54, 0.46, -0.39], dtype=np.float64)
        cp_hy_id_err = 0.0
        cp_strict_dec = True
        for _ in range(3):
            wk_cp = np.concatenate([ak_cp, lk_cp])
            an_cp = np.linalg.solve(m_cp_lhs, (ak_cp / tau_cp) + ftot_lf + (t_con_6x3 @ lk_cp))
            abar_cp = (2.0 * an_cp) - ak_cp
            ln_cp = np.linalg.solve(c_cp_lhs, (lk_cp / sigma_cp) - (t_con_6x3.T @ abar_cp))
            wn_cp = np.concatenate([an_cp, ln_cp])
            dw_prev_cp = wk_cp - w_star_cp
            dw_next_cp = wn_cp - w_star_cp
            dw_step_cp = wk_cp - wn_cp
            da_next_cp = an_cp - a_eps1_primal
            dl_next_cp = ln_cp - lam_eps1_dual
            lhs_hy_cp = float((dw_prev_cp @ p_hy_9x9 @ dw_prev_cp) - (dw_next_cp @ p_hy_9x9 @ dw_next_cp))
            dissip_mc_cp = 2.0 * float((da_next_cp @ m_spatial_b @ da_next_cp) + (dl_next_cp @ cc1_3x3 @ dl_next_cp))
            rhs_hy_cp = float(dw_step_cp @ p_hy_9x9 @ dw_step_cp) + dissip_mc_cp
            cp_hy_id_err += abs(lhs_hy_cp - rhs_hy_cp) / max(abs(rhs_hy_cp), 1.0)
            if lhs_hy_cp <= 0.0:
                cp_strict_dec = False
            ak_cp = an_cp
            lk_cp = ln_cp
        dqs_se3_chambolle_pock_pdhg_he_yuan_saddle_contraction_err = (
            float(np.linalg.norm(a_fp_cp - a_eps1_primal))
            + float(np.linalg.norm(lam_fp_cp - lam_eps1_dual))
            + cp_hy_id_err
            + (
                0.0
                if (
                    0.0 < (tau_cp * sigma_cp * nrm2_t_cp * nrm2_t_cp) < 1.0
                    and float(ev_phy_cp[0]) > 1e-3
                    and cp_strict_dec
                )
                else 1.0
            )
        )
        # Splitting extragradient avant-arrière-avant (Forward-Backward-Forward) de Tseng (2000, SIAM J. Control Optim. 38:431)
        # sur l'opérateur monotone fortement coercif KKT de selle SE(3) K_ts = [[M, -T], [T^T, C_1]] :
        # 1) identité algébrique exacte de dissipation quadratique de Tseng à chaque pas y_k = z_k - gamma*(K_ts*z_k - b_ts), z_{k+1} = z_k - gamma*(K_ts*y_k - b_ts) :
        #    ||z_k - z*||_2^2 - ||z_{k+1} - z*||_2^2 == (1 - gamma^2*||K_ts||_2^2?) -> exacte :
        #    ||z_k - z*||_2^2 - ||z_{k+1} - z*||_2^2 == ||z_k - y_k||_2^2 - ||z_{k+1} - y_k||_2^2 + 2*gamma*((y_a - a*)^T*M*(y_a - a*) + (y_l - lam*)^T*C_1*(y_l - lam*)) > 0
        # 2) rayon spectral strictement contractant rho(I_9 - gamma*K_ts + gamma^2*K_ts^2) < 1 pour gamma = 0.7/||K_ts||_2 :
        k_ts_9x9 = np.block([[m_spatial_b, -t_con_6x3], [t_con_6x3.T, cc1_3x3]])
        b_ts_9 = np.concatenate([ftot_lf, np.zeros(3, dtype=np.float64)])
        z_star_ts = np.concatenate([a_eps1_primal, lam_eps1_dual])
        lip_k_ts = float(np.linalg.norm(k_ts_9x9, ord=2))
        gam_ts = 0.70 / max(lip_k_ts, 1e-9)
        eye9_ts = np.eye(9, dtype=np.float64)
        g_ts_op = eye9_ts - (gam_ts * k_ts_9x9) + ((gam_ts * gam_ts) * (k_ts_9x9 @ k_ts_9x9))
        rho_ts_fbf = float(np.max(np.abs(np.linalg.eigvals(g_ts_op))))
        zk_ts = np.array([0.85, -0.62, 0.44, -0.37, 0.53, -0.28, 0.91, -0.74, 0.58], dtype=np.float64)
        tseng_id_err = 0.0
        tseng_strict_dec = True
        for _ in range(8):
            yk_ts = zk_ts - (gam_ts * ((k_ts_9x9 @ zk_ts) - b_ts_9))
            zn_ts = zk_ts - (gam_ts * ((k_ts_9x9 @ yk_ts) - b_ts_9))
            dz_prev_ts = zk_ts - z_star_ts
            dz_next_ts = zn_ts - z_star_ts
            dy_pred_ts = zk_ts - yk_ts
            dy_corr_ts = zn_ts - yk_ts
            ya_err_ts = yk_ts[:6] - a_eps1_primal
            yl_err_ts = yk_ts[6:] - lam_eps1_dual
            lhs_ts = float((dz_prev_ts @ dz_prev_ts) - (dz_next_ts @ dz_next_ts))
            rhs_ts = (
                float((dy_pred_ts @ dy_pred_ts) - (dy_corr_ts @ dy_corr_ts))
                + (2.0 * gam_ts * float((ya_err_ts @ m_spatial_b @ ya_err_ts) + (yl_err_ts @ cc1_3x3 @ yl_err_ts)))
            )
            tseng_id_err += abs(lhs_ts - rhs_ts) / max(abs(rhs_ts), 1.0)
            if lhs_ts <= 0.0:
                tseng_strict_dec = False
            zk_ts = zn_ts
        dqs_se3_tseng_fbf_extragradient_monotone_saddle_dissipation_err = (
            float(np.linalg.norm((k_ts_9x9 @ z_star_ts) - b_ts_9))
            + tseng_id_err
            + (0.0 if (0.0 < rho_ts_fbf < 1.0 - 1e-4 and tseng_strict_dec) else 1.0)
        )
        # Splitting avant-réfléchi-arrière à une seule évaluation par pas (Forward-Reflected-Backward, FRB)
        # de Malitsky-Tam (2020, SIAM J. Optim. 30:1451, Thm 2.5) sur le système KKT monotone de selle SE(3) :
        # z_{k+1} = z_k - 2*gamma*F(z_k) + gamma*F(z_{k-1}) pour gamma = 0.35 / ||K_ts||_2 < 1/(2*L) :
        # 1) identité algébrique exacte de potentiel réfléchi Phi_k = ||z_k - z*||_2^2 + 2*gamma*<F(z_{k-1}), z_k - z*> + gamma*L*||z_k - z_{k-1}||_2^2 :
        #    Phi_k - Phi_{k+1} == 2*gamma*<F(z_k), z_k - z*> + (1 - gamma*L)*||z_{k+1} - z_k||_2^2 + gamma*L*||z_k - z_{k-1}||_2^2 + 2*gamma*<F(z_k) - F(z_{k-1}), z_{k+1} - z_k>
        # 2) décroissance stricte de Lyapunov Phi_k - Phi_{k+1} >= 2*gamma*<F(z_k), z_k - z*> + (1 - 2*gamma*L)*||z_{k+1} - z_k||_2^2 > 0
        #    et rayon spectral strictement contractant rho(G_{FRB, 18x18}) < 1 :
        gam_mt = 0.35 / max(lip_k_ts, 1e-9)
        zero9_mt = np.zeros((9, 9), dtype=np.float64)
        g_frb_18x18 = np.block([[eye9_ts - (2.0 * gam_mt * k_ts_9x9), gam_mt * k_ts_9x9], [eye9_ts, zero9_mt]])
        rho_mt_frb = float(np.max(np.abs(np.linalg.eigvals(g_frb_18x18))))
        zm1_mt = np.array([0.85, -0.62, 0.44, -0.37, 0.53, -0.28, 0.91, -0.74, 0.58], dtype=np.float64)
        fm1_mt = (k_ts_9x9 @ zm1_mt) - b_ts_9
        zk_mt = zm1_mt - (gam_mt * fm1_mt)
        fk_mt = (k_ts_9x9 @ zk_mt) - b_ts_9
        mt_id_err = 0.0
        mt_strict_dec = True
        for _ in range(8):
            zn_mt = zk_mt - (2.0 * gam_mt * fk_mt) + (gam_mt * fm1_mt)
            dz_k_mt = zk_mt - z_star_ts
            dz_n_mt = zn_mt - z_star_ts
            step_cur_mt = zn_mt - zk_mt
            step_prv_mt = zk_mt - zm1_mt
            phi_k_mt = (
                float(dz_k_mt @ dz_k_mt)
                + (2.0 * gam_mt * float(fm1_mt @ dz_k_mt))
                + ((gam_mt * lip_k_ts) * float(step_prv_mt @ step_prv_mt))
            )
            phi_n_mt = (
                float(dz_n_mt @ dz_n_mt)
                + (2.0 * gam_mt * float(fk_mt @ dz_n_mt))
                + ((gam_mt * lip_k_ts) * float(step_cur_mt @ step_cur_mt))
            )
            lhs_mt = phi_k_mt - phi_n_mt
            coerc_mt = 2.0 * gam_mt * float(fk_mt @ dz_k_mt)
            rhs_mt = (
                coerc_mt
                + ((1.0 - (gam_mt * lip_k_ts)) * float(step_cur_mt @ step_cur_mt))
                + ((gam_mt * lip_k_ts) * float(step_prv_mt @ step_prv_mt))
                + (2.0 * gam_mt * float((fk_mt - fm1_mt) @ step_cur_mt))
            )
            lb_mt = coerc_mt + ((1.0 - (2.0 * gam_mt * lip_k_ts)) * float(step_cur_mt @ step_cur_mt))
            mt_id_err += abs(lhs_mt - rhs_mt) / max(abs(rhs_mt), 1.0)
            if lhs_mt + 1e-15 < lb_mt or lb_mt <= 0.0:
                mt_strict_dec = False
            zm1_mt = zk_mt
            fm1_mt = fk_mt
            zk_mt = zn_mt
            fk_mt = (k_ts_9x9 @ zk_mt) - b_ts_9
        dqs_se3_malitsky_tam_frb_single_eval_saddle_lyapunov_err = (
            mt_id_err + (0.0 if (0.0 < rho_mt_frb < 1.0 - 1e-3 and mt_strict_dec) else 1.0)
        )
        # Méthode Past-Extragradient à une seule évaluation d'opérateur par pas de Leonid Popov (1980, Math. Notes 28:845)
        # sur le système KKT monotone de selle SE(3) : w_k = z_k - gamma*F(w_{k-1}), z_{k+1} = z_k - gamma*F(w_k) pour gamma = 0.25/||K_ts||_2 < 1/(3*L) :
        # 1) identité télescopique exacte à 3 points :
        #    ||z_k - z*||_2^2 - ||z_{k+1} - z*||_2^2 == 2*gamma*<F(w_k), w_k - z*> + ||z_{k+1} - w_k||_2^2 + ||w_k - z_k||_2^2 - 2*gamma*<F(w_k) - F(w_{k-1}), w_k - z_{k+1}>
        # 2) décroissance stricte du potentiel de Lyapunov Psi_k = ||z_k - z*||_2^2 + gamma*L*||z_k - w_{k-1}||_2^2 :
        #    Psi_k - Psi_{k+1} >= 2*gamma*<F(w_k), w_k - z*> + (1 - 2*gamma*L)*||z_{k+1} - w_k||_2^2 + (1 - gamma*L)*||w_k - z_k||_2^2 > 0
        #    et contraction spectrale stricte rho(G_{Popov, 18x18}) < 1 :
        gam_pop = 0.25 / max(lip_k_ts, 1e-9)
        g_pop_18x18 = np.block(
            [
                [eye9_ts - (gam_pop * k_ts_9x9), (gam_pop * gam_pop) * (k_ts_9x9 @ k_ts_9x9)],
                [eye9_ts, (-gam_pop) * k_ts_9x9],
            ]
        )
        rho_pop = float(np.max(np.abs(np.linalg.eigvals(g_pop_18x18))))
        zk_pop = np.array([0.82, -0.59, 0.47, -0.34, 0.56, -0.31, 0.88, -0.71, 0.62], dtype=np.float64)
        wm1_pop = zk_pop.copy()
        fwm1_pop = (k_ts_9x9 @ wm1_pop) - b_ts_9
        pop_id_err = 0.0
        pop_strict_dec = True
        for _ in range(8):
            wk_pop = zk_pop - (gam_pop * fwm1_pop)
            fwk_pop = (k_ts_9x9 @ wk_pop) - b_ts_9
            zn_pop = zk_pop - (gam_pop * fwk_pop)
            dz_k_pop = zk_pop - z_star_ts
            dz_n_pop = zn_pop - z_star_ts
            dw_k_pop = wk_pop - z_star_ts
            zn_minus_wk = zn_pop - wk_pop
            wk_minus_zk = wk_pop - zk_pop
            zk_minus_wm1 = zk_pop - wm1_pop
            lhs_3pt_pop = float(dz_k_pop @ dz_k_pop) - float(dz_n_pop @ dz_n_pop)
            coerc_pop = 2.0 * gam_pop * float(fwk_pop @ dw_k_pop)
            rhs_3pt_pop = (
                coerc_pop
                + float(zn_minus_wk @ zn_minus_wk)
                + float(wk_minus_zk @ wk_minus_zk)
                - (2.0 * gam_pop * float((fwk_pop - fwm1_pop) @ (wk_pop - zn_pop)))
            )
            psi_k_pop = float(dz_k_pop @ dz_k_pop) + ((gam_pop * lip_k_ts) * float(zk_minus_wm1 @ zk_minus_wm1))
            psi_n_pop = float(dz_n_pop @ dz_n_pop) + ((gam_pop * lip_k_ts) * float(zn_minus_wk @ zn_minus_wk))
            lb_psi_pop = (
                coerc_pop
                + ((1.0 - (2.0 * gam_pop * lip_k_ts)) * float(zn_minus_wk @ zn_minus_wk))
                + ((1.0 - (gam_pop * lip_k_ts)) * float(wk_minus_zk @ wk_minus_zk))
            )
            pop_id_err += abs(lhs_3pt_pop - rhs_3pt_pop) / max(abs(rhs_3pt_pop), 1.0)
            if (psi_k_pop - psi_n_pop) + 1e-15 < lb_psi_pop or lb_psi_pop <= 0.0:
                pop_strict_dec = False
            wm1_pop = wk_pop
            fwm1_pop = fwk_pop
            zk_pop = zn_pop
        dqs_se3_popov_past_extragradient_single_eval_saddle_lyapunov_err = (
            pop_id_err + (0.0 if (0.0 < rho_pop < 1.0 - 1e-3 and pop_strict_dec) else 1.0)
        )
        # Méthode Extragradient à deux pas de Galina Korpelevich (1976, Ekonomika i Mat. Metody 12:747) sur le système KKT monotone de selle SE(3) :
        # zbar_k = z_k - gamma*F(z_k), z_{k+1} = z_k - gamma*F(zbar_k) pour gamma = 0.55/||K_ts||_2 < 1/L :
        # 1) identité algébrique exacte à 3 points de Fejér :
        #    ||z_k - z*||_2^2 - ||z_{k+1} - z*||_2^2 == ||zbar_k - z_k||_2^2 - ||z_{k+1} - zbar_k||_2^2 + 2*gamma*<F(zbar_k), zbar_k - z*>
        # 2) contraction stricte de Fejér ||z_k - z*||_2^2 - ||z_{k+1} - z*||_2^2 >= 2*gamma*<F(zbar_k), zbar_k - z*> + (1 - gamma^2*L^2)*||zbar_k - z_k||_2^2 > 0
        #    et rayon spectral strict rho(I_9 - gamma*K_ts + gamma^2*K_ts^2) < 1 :
        gam_kor = 0.55 / max(lip_k_ts, 1e-9)
