        dqs_se3_featherstone_jain_articulated_body_riccati_duality_err = 0.0
        dqs_se3_rodriguez_jain_mobility_splitting_wrench_pythagoras_err = 0.0
        dqs_se3_legendre_fenchel_gauss_delassus_zero_duality_gap_err = 0.0
        dqs_se3_moreau_yosida_compliant_delassus_woodbury_err = 0.0
        dqs_se3_hestenes_powell_augmented_lagrangian_uzawa_contraction_err = 0.0
        dqs_se3_gabay_mercier_admm_douglas_rachford_contraction_err = 0.0
