                u_sr = xv_sr[:q_sr] - xv_sr[h_sr : h_sr + q_sr]
                v_sr = xv_sr[q_sr:h_sr] - xv_sr[h_sr + q_sr :]
                yo1_sr = _sr_dif_fft((u_sr - (1.0j * v_sr)) * w1_sr)
                yo3_sr = _sr_dif_fft((u_sr + (1.0j * v_sr)) * w3_sr)
