            # True 2D Vector-Radix (2x2) Decimation-in-Time FFT on 16x16 Block u_blk16:
            # Simultaneous 4-quadrant 2D butterfly combining (y00, y01, y10, y11) with joint 2D twiddle factors
            # W_N^{k1*r} * W_N^{k2*s} * W_N^{k1*s + k2*r} saving 25% complex multiplications over row-column FFT.
            def _vrfft2d_radix2x2_rh(x2d_rh: np.ndarray) -> np.ndarray:
                n_rh = x2d_rh.shape[0]
                if n_rh == 1:
                    return x2d_rh.astype(np.complex128)
                h_rh = n_rh // 2
                y00_rh = _vrfft2d_radix2x2_rh(x2d_rh[0::2, 0::2])
                y01_rh = _vrfft2d_radix2x2_rh(x2d_rh[0::2, 1::2])
                y10_rh = _vrfft2d_radix2x2_rh(x2d_rh[1::2, 0::2])
                y11_rh = _vrfft2d_radix2x2_rh(x2d_rh[1::2, 1::2])
                idx_rh = np.arange(h_rh, dtype=np.float64)
                w1d_rh = np.exp((-2.0j * math.pi * idx_rh) / float(n_rh))
                t01_rh = y01_rh * w1d_rh[None, :]
                t10_rh = y10_rh * w1d_rh[:, None]
                t11_rh = y11_rh * (w1d_rh[:, None] * w1d_rh[None, :])
                s0_rh = y00_rh + t01_rh
                d0_rh = y00_rh - t01_rh
                s1_rh = t10_rh + t11_rh
                d1_rh = t10_rh - t11_rh
                out_rh = np.zeros((n_rh, n_rh), dtype=np.complex128)
                out_rh[:h_rh, :h_rh] = s0_rh + s1_rh
                out_rh[:h_rh, h_rh:] = d0_rh + d1_rh
                out_rh[h_rh:, :h_rh] = s0_rh - s1_rh
                out_rh[h_rh:, h_rh:] = d0_rh - d1_rh
                return out_rh

