            #      Pi(x, y; theta) = theta*(x + y) + gamma*x*y - c*(x + y), x, y in {0, 1}.
            #      Différences croisées strictes Pi(1,1) - Pi(1,0) - Pi(0,1) + Pi(0,0) = gamma > 0
            #      => l'adoption conjointe (1,1) domine strictement l'adoption partielle (1,0) dès que c - gamma < theta < c
            s_mr90 = z3.Solver()
            theta_mr, gamma_mr, c_mr = z3.Reals("theta_mr gamma_mr c_mr")
            pi00_mr, pi10_mr, pi01_mr, pi11_mr, cross_mr = z3.Reals(
                "pi00_mr pi10_mr pi01_mr pi11_mr cross_mr"
            )
            s_mr90.add(
                theta_mr == z3.RealVal("5"),
                gamma_mr == z3.RealVal("4"),
                c_mr == z3.RealVal("6"),
                pi00_mr == z3.RealVal("0"),
                pi10_mr == (theta_mr - c_mr),
                pi01_mr == (theta_mr - c_mr),
                pi11_mr == ((2 * theta_mr) + gamma_mr - (2 * c_mr)),
                cross_mr == (pi11_mr - pi10_mr - pi01_mr + pi00_mr),
                z3.Or(
                    cross_mr != gamma_mr,
                    cross_mr <= 0,
                    pi10_mr >= pi00_mr,
                    pi11_mr <= pi00_mr,
                    pi11_mr != z3.RealVal("2"),
                ),
            )
            milgrom_roberts_1990_topkis_1978_supermodular_complementarities_adoption_unsat = s_mr90.check() == z3.unsat
            # 104) Valeur de Shapley (1953, Ann. Math. Studies 28:307) & Allocation sur graphe de communication de Myerson (1977, Math. Oper. Res. 2:225) :
            #      Sur le graphe linéaire G = {(1,2), (2,3)} où v({1,2})=v({2,3})=6, v({1,3})^G = v({1})+v({3}) = 0 et v({1,2,3})^G = 12,
            #      la valeur de Myerson phi^G = (3, 6, 3) vérifie l'efficience exacte (sum = 12) et les contributions équilibrées
            #      phi_1^G - phi_1^{G \ {12}} == phi_2^G - phi_2^{G \ {12}} (avec phi^{G \ {12}} = (0, 3, 3)) :
            s_sm77 = z3.Solver()
            v12_sm, v23_sm, v13_g_sm, v123_g_sm = z3.Reals("v12_sm v23_sm v13_g_sm v123_g_sm")
            phi1_g_sm, phi2_g_sm, phi3_g_sm, phi1_no12_sm, phi2_no12_sm = z3.Reals(
                "phi1_g_sm phi2_g_sm phi3_g_sm phi1_no12_sm phi2_no12_sm"
            )
            s_sm77.add(
                v12_sm == z3.RealVal("6"),
                v23_sm == z3.RealVal("6"),
                v13_g_sm == z3.RealVal("0"),
                v123_g_sm == z3.RealVal("12"),
                phi1_g_sm == ((v12_sm + v13_g_sm + (2 * (v123_g_sm - v23_sm))) / 6),
                phi2_g_sm == ((v12_sm + v23_sm + (2 * (v123_g_sm - v13_g_sm))) / 6),
                phi3_g_sm == ((v23_sm + v13_g_sm + (2 * (v123_g_sm - v12_sm))) / 6),
                phi1_no12_sm == z3.RealVal("0"),
                phi2_no12_sm == (v23_sm / 2),
                z3.Or(
                    (phi1_g_sm + phi2_g_sm + phi3_g_sm) != v123_g_sm,
                    phi2_g_sm <= phi1_g_sm,
                    (phi1_g_sm - phi1_no12_sm) != (phi2_g_sm - phi2_no12_sm),
                    phi2_g_sm != z3.RealVal("6"),
                ),
            )
            shapley_1953_myerson_1977_cooperative_value_and_communication_graph_allocation_unsat = s_sm77.check() == z3.unsat
            # 105) Gillies (1959) & Bondareva (1963, Probl. Kibern. 10:119) — Shapley (1967/1971, Int. J. Game Theory 1:11)
            #      Balanced Cooperative Game Core Non-Emptiness & Convex Game Shapley-Value-in-Core Theorem :
            #      Pour le jeu convexe (supermodulaire) v(1)=2, v(2)=3, v(3)=4, v(12)=7, v(13)=8, v(23)=10, v(123)=18,
            #      la condition équilibrée de Bondareva-Shapley 0.5*(v(12)+v(13)+v(23)) = 12.5 <= 18 est vérifiée et la valeur
            #      de Shapley phi = (28/6, 37/6, 43/6) appartient strictement à l'intérieur du Cœur (sum = 18, phi(S) > v(S)) :
            s_bs67 = z3.Solver()
            v1_bs, v2_bs, v3_bs, v12_bs, v13_bs, v23_bs, v123_bs = z3.Reals(
                "v1_bs v2_bs v3_bs v12_bs v13_bs v23_bs v123_bs"
            )
            phi1_bs, phi2_bs, phi3_bs, bal_sum_bs = z3.Reals("phi1_bs phi2_bs phi3_bs bal_sum_bs")
            s_bs67.add(
                v1_bs == z3.RealVal("2"),
                v2_bs == z3.RealVal("3"),
                v3_bs == z3.RealVal("4"),
                v12_bs == z3.RealVal("7"),
                v13_bs == z3.RealVal("8"),
                v23_bs == z3.RealVal("10"),
                v123_bs == z3.RealVal("18"),
                bal_sum_bs == (z3.RealVal("0.5") * (v12_bs + v13_bs + v23_bs)),
                phi1_bs == (((2 * v1_bs) + (v12_bs - v2_bs) + (v13_bs - v3_bs) + (2 * (v123_bs - v23_bs))) / 6),
                phi2_bs == (((2 * v2_bs) + (v12_bs - v1_bs) + (v23_bs - v3_bs) + (2 * (v123_bs - v13_bs))) / 6),
                phi3_bs == (((2 * v3_bs) + (v13_bs - v1_bs) + (v23_bs - v2_bs) + (2 * (v123_bs - v12_bs))) / 6),
                z3.Or(
                    bal_sum_bs > v123_bs,
                    (v123_bs + v1_bs) < (v12_bs + v13_bs),
                    (phi1_bs + phi2_bs + phi3_bs) != v123_bs,
                    (phi1_bs + phi2_bs) <= v12_bs,
                    (phi1_bs + phi3_bs) <= v13_bs,
                    (phi2_bs + phi3_bs) <= v23_bs,
                ),
            )
            bondareva_1963_shapley_1967_1971_balanced_core_and_convex_game_shapley_in_core_unsat = s_bs67.check() == z3.unsat
            # 106) Enchère d'Initié et Impact de Prix de Kyle (1985, Econometrica 53:1315) :
            #      Pour un actif de valeur fondamentale v ~ N(p0, sigma_v^2) avec sigma_v = 6 et flux bruité u ~ N(0, sigma_u^2)
            #      avec sigma_u = 3, l'initié soumet x = beta*(v - p0) et le teneur de marché fixe p = p0 + lam*(x + u) ;
            #      à l'équilibre linéaire unique beta = sigma_u / sigma_v = 1/2, lam = sigma_v / (2*sigma_u) = 1, beta*lam == 1/2,
            #      la variance conditionnelle résiduelle Var(v | x + u) = sigma_v^2 / 2 = 18 révèle exactement la moitié de l'information,
            #      et le profit espéré de l'initié pi* = (v - p0)^2 / (4*lam) domine toute déviation x_alt != x* :
            s_ky85 = z3.Solver()
            sig_v_ky, sig_u_ky, beta_ky, lam_ky, var_post_ky, dv_ky, x_star_ky, pi_star_ky, x_alt_ky, pi_alt_ky = z3.Reals(
                "sig_v_ky sig_u_ky beta_ky lam_ky var_post_ky dv_ky x_star_ky pi_star_ky x_alt_ky pi_alt_ky"
            )
            s_ky85.add(
                sig_v_ky == z3.RealVal("6"),
                sig_u_ky == z3.RealVal("3"),
                beta_ky == (sig_u_ky / sig_v_ky),
                lam_ky == (sig_v_ky / (2 * sig_u_ky)),
                var_post_ky == ((sig_v_ky * sig_v_ky) * (1 - (beta_ky * lam_ky))),
                dv_ky == z3.RealVal("8"),
                x_star_ky == (dv_ky / (2 * lam_ky)),
                pi_star_ky == ((dv_ky - (lam_ky * x_star_ky)) * x_star_ky),
                x_alt_ky == z3.RealVal("5"),
                pi_alt_ky == ((dv_ky - (lam_ky * x_alt_ky)) * x_alt_ky),
                z3.Or(
                    (beta_ky * lam_ky) != z3.RealVal("1/2"),
                    var_post_ky != ((sig_v_ky * sig_v_ky) / 2),
                    pi_star_ky != ((dv_ky * dv_ky) / (4 * lam_ky)),
                    pi_alt_ky >= pi_star_ky,
                ),
            )
            kyle_1985_continuous_insider_auction_lambda_price_impact_and_half_variance_unsat = s_ky85.check() == z3.unsat
            # 107) Glosten & Milgrom (1985, J. Financ. Econ. 14:71, "Bid, Ask and Transaction Prices in a Specialist Market with Heterogeneously Informed Traders") :
            #      Pour V in {V_L=40, V_H=100} équiprobable (pi_0 = 1/2) et proportion d'initiés mu = 2/5,
            #      les prix zéro-profit d'équilibre bayésien A* = E[V | Buy] = ((1-mu)/2)*V_L + ((1+mu)/2)*V_H = 82
            #      et B* = E[V | Sell] = ((1+mu)/2)*V_L + ((1-mu)/2)*V_H = 58 donnent une fourchette exacte
            #      S* = A* - B* = mu*(V_H - V_L) = 24 > 0, un point médian (A* + B*)/2 == E[V] = 70, et une perte
            #      sur initiés mu*(V_H - A*) exactement compensée par le gain sur non-initiés ((1-mu)/2)*(A* - E[V]) :
