                vl_gm == z3.RealVal("40"),
                vh_gm == z3.RealVal("100"),
                mu_gm == z3.RealVal("2/5"),
                ev_gm == ((vl_gm + vh_gm) / 2),
                ask_gm == ((((1 - mu_gm) / 2) * vl_gm) + (((1 + mu_gm) / 2) * vh_gm)),
                bid_gm == ((((1 + mu_gm) / 2) * vl_gm) + (((1 - mu_gm) / 2) * vh_gm)),
                spr_gm == (ask_gm - bid_gm),
                loss_inf_gm == ((mu_gm / 2) * (vh_gm - ask_gm)),
                gain_uninf_gm == (((1 - mu_gm) / 2) * (ask_gm - ev_gm)),
