                ((tau_kp * sp.diff(tau_kp, x_w, t_sym)) - (sp.diff(tau_kp, x_w) * sp.diff(tau_kp, t_sym)))
                + ((tau_kp * sp.diff(tau_kp, x_w, 4)) - (4 * sp.diff(tau_kp, x_w) * sp.diff(tau_kp, x_w, 3)) + (3 * (sp.diff(tau_kp, x_w, 2) ** 2)))
