            ch_h1_res = sp.expand(sp.diff(ch_h1_dens, t_sym) + sp.diff(ch_h1_flux, x_w) - (u_ch * r_ch))
            l2_dens_ch = sp.Rational(1, 2) * ((u_ch ** 3) + ((al_ch ** 2) * u_ch * (sp.diff(u_ch, x_w) ** 2)))
            var_h2_u_ch = sp.diff(l2_dens_ch, u_ch) - sp.diff(sp.diff(l2_dens_ch, sp.diff(u_ch, x_w)), x_w)
            j2_u_ch = -((u_ch * sp.diff(m_ch, x_w)) + (2 * sp.diff(u_ch, x_w) * m_ch))
            ch_biham_res = sp.expand(j2_u_ch + sp.diff(var_h2_u_ch, x_w))
            f_ch_fn = sp.Function("f_ch_fn")(x_w)
            g_ch_fn = sp.Function("g_ch_fn")(x_w)
            j2_g_ch = -((2 * m_ch * sp.diff(g_ch_fn, x_w)) + (sp.diff(m_ch, x_w) * g_ch_fn))
            j2_f_ch = -((2 * m_ch * sp.diff(f_ch_fn, x_w)) + (sp.diff(m_ch, x_w) * f_ch_fn))
            ch_skew_res = sp.expand((f_ch_fn * j2_g_ch) + (g_ch_fn * j2_f_ch) + sp.diff(2 * m_ch * f_ch_fn * g_ch_fn, x_w))
            camassa_holm_bihamiltonian_shallow_water_momentum_and_h1_conservation_ok = bool(
                ch_mom_res == 0 and ch_h1_res == 0 and ch_biham_res == 0 and ch_skew_res == 0
            )
            # 67) Équation d'eau peu profonde intégrable à peakons de Degasperis-Procesi (1999) / Degasperis-Holm-Hone (2002) :
            #     m_t + u*m_x + 3*u_x*m = 0 avec m = u - alpha^2*u_{xx} :
            #     1) loi de conservation locale exacte de l'impulsion d_t(m) + d_x(2*u^2 - alpha^2*u_x^2 - alpha^2*u*u_{xx}) == 0
            #     2) génération hamiltonienne exacte m_t == B_0^{DP}*(delta H_{-1}/delta m) == d_x*(4 - alpha^2*d_x^2)*(-1/2*u^2) pour H_{-1} = -1/6*int u^3 dx
            #     3) anti-auto-adjonction formelle exacte du 5e ordre de B_0^{DP} = d_x*(1 - alpha^2*d_x^2)*(4 - alpha^2*d_x^2) = d_x - 5*alpha^2*d_x^3 + 4*alpha^4*d_x^5 :
            a_dp = sp.Symbol("a_dp", positive=True)
