            v_mn = sp.Matrix(
                [
                    [
                        -6 * sp.I * (lam_mn ** 2) + sp.I * i_mn,
                        3 * lam_mn * q1_mn + sp.I * sp.diff(q1_mn, x_mn),
                        3 * lam_mn * q2_mn + sp.I * sp.diff(q2_mn, x_mn),
                    ],
                    [
                        -3 * lam_mn * r1_mn + sp.I * sp.diff(r1_mn, x_mn),
                        3 * sp.I * (lam_mn ** 2) - sp.I * q1_mn * r1_mn,
                        -sp.I * q2_mn * r1_mn,
                    ],
                    [
                        -3 * lam_mn * r2_mn + sp.I * sp.diff(r2_mn, x_mn),
                        -sp.I * q1_mn * r2_mn,
                        3 * sp.I * (lam_mn ** 2) - sp.I * q2_mn * r2_mn,
                    ],
                ]
            )
