            q_ss = sp.Function("q_ss")(x_mn, t_sym)
            r_ss = sp.Function("r_ss")(x_mn, t_sym)
            eta_ss = -3 * sp.I * lam_mn
            ss_subs = {
                sp.diff(q_ss, t_sym): -sp.diff(q_ss, x_mn, 3) - (9 * q_ss * r_ss * sp.diff(q_ss, x_mn)) - (3 * (q_ss ** 2) * sp.diff(r_ss, x_mn)),
                sp.diff(r_ss, t_sym): -sp.diff(r_ss, x_mn, 3) - (9 * q_ss * r_ss * sp.diff(r_ss, x_mn)) - (3 * (r_ss ** 2) * sp.diff(q_ss, x_mn)),
            }
