            s_ovf = z3.Solver()
            a_v, b_v = z3.Ints("a_v b_v")
            max_i = z3.IntVal(2147483647)
            s_ovf.add(a_v >= 0, b_v >= 0, a_v <= max_i - b_v)
            s_ovf.add(z3.Or(a_v + b_v < a_v, a_v + b_v > max_i))
            ovf_unsat = s_ovf.check() == z3.unsat
            # 3) CWE-416 Use-After-Free : après nullification post-free (step >= free_step => ptr_alive == False), prouver UNSAT
            s_uaf = z3.Solver()
            step_t, free_t = z3.Ints("step_t free_t")
            ptr_alive, deref_allowed = z3.Bools("ptr_alive deref_allowed")
            s_uaf.add(ptr_alive == (step_t < free_t))
            s_uaf.add(deref_allowed == ptr_alive)
            s_uaf.add(step_t >= free_t, deref_allowed)
            uaf_unsat = s_uaf.check() == z3.unsat
            # 4) CWE-362 Concurrent Race Condition : après verrou atomique (lock_owner == tid requis pour écriture), prouver UNSAT
            s_race = z3.Solver()
            lock_owner = z3.Int("lock_owner")
            write_t1, write_t2 = z3.Bools("write_t1 write_t2")
            s_race.add(z3.Implies(write_t1, lock_owner == 1))
            s_race.add(z3.Implies(write_t2, lock_owner == 2))
            s_race.add(write_t1, write_t2)
            race_unsat = s_race.check() == z3.unsat
            # 5) CWE-269 Improper Privilege Management : confinement RBAC (exec_admin => role==2 & token_ok & !session_expired)
            s_priv = z3.Solver()
            role_id = z3.Int("role_id")
            token_ok, session_expired, exec_admin = z3.Bools("token_ok session_expired exec_admin")
            s_priv.add(z3.Implies(exec_admin, z3.And(role_id == 2, token_ok, z3.Not(session_expired))))
            s_priv.add(exec_admin, z3.Or(role_id != 2, z3.Not(token_ok), session_expired))
            priv_unsat = s_priv.check() == z3.unsat
            # 6) CWE-89 SQL Injection : requête paramétrée à AST immuable (query_parameterized => !ast_predicate_mutated)
            s_sqli = z3.Solver()
            query_parameterized, input_has_metachar, ast_predicate_mutated = z3.Bools(
                "query_parameterized input_has_metachar ast_predicate_mutated"
            )
            s_sqli.add(query_parameterized, input_has_metachar)
            s_sqli.add(z3.Implies(query_parameterized, z3.Not(ast_predicate_mutated)))
            s_sqli.add(ast_predicate_mutated)
            sqli_unsat = s_sqli.check() == z3.unsat
            # 7) CWE-22 Path Traversal : confinement canonique realpath (allow_io <=> depth>=root_depth & prefix_ok & !dotdot)
            s_pt = z3.Solver()
            res_depth, root_depth = z3.Ints("res_depth root_depth")
            prefix_ok, has_dotdot, allow_io = z3.Bools("prefix_ok has_dotdot allow_io")
            s_pt.add(allow_io == z3.And(res_depth >= root_depth, prefix_ok, z3.Not(has_dotdot)))
            s_pt.add(allow_io, z3.Or(res_depth < root_depth, z3.Not(prefix_ok), has_dotdot))
            pt_unsat = s_pt.check() == z3.unsat
            # 8) CWE-347 Improper Verification of Cryptographic Signature : HMAC constant-time & fenêtre anti-rejeu
            s_sig = z3.Solver()
            tag_len = z3.Int("tag_len")
            ct_tag_eq, ts_fresh, accept_msg = z3.Bools("ct_tag_eq ts_fresh accept_msg")
            s_sig.add(accept_msg == z3.And(tag_len == 32, ct_tag_eq, ts_fresh))
            s_sig.add(accept_msg, z3.Or(tag_len != 32, z3.Not(ct_tag_eq), z3.Not(ts_fresh)))
            sig_unsat = s_sig.check() == z3.unsat
            # 9) CWE-611 Improper Restriction of XML External Entity Reference (XXE) : DTD & entités externes interdites
            s_xxe = z3.Solver()
            dtd_disallowed, resolve_externals, has_system_entity, ext_entity_expanded = z3.Bools(
                "dtd_disallowed resolve_externals has_system_entity ext_entity_expanded"
            )
            s_xxe.add(dtd_disallowed, z3.Not(resolve_externals), has_system_entity)
            s_xxe.add(ext_entity_expanded == z3.And(has_system_entity, resolve_externals, z3.Not(dtd_disallowed)))
            s_xxe.add(ext_entity_expanded)
            xxe_unsat = s_xxe.check() == z3.unsat
