            nonce_reused_for_key, allow_aead_seal = z3.Bools("nonce_reused_for_key allow_aead_seal")
            s_aead.add(
                allow_aead_seal
                == z3.And(key_bits >= 256, auth_tag_bits == 128, z3.Not(nonce_reused_for_key))
            )
            s_aead.add(allow_aead_seal, z3.Or(key_bits < 256, auth_tag_bits != 128, nonce_reused_for_key))
