                + abs(sum(b_mcl5) - 1.0)
                + abs((2.0 * ((w1_mcl ** 3) + (w2_mcl ** 3))) + (w3_mcl ** 3))
                + float(np.linalg.norm((dfmcl_4.T @ j4_symp_hh @ dfmcl_4) - j4_symp_hh, ord="fro"))
                + float(np.linalg.norm((dfmcl_8.T @ j4_symp_hh @ dfmcl_8) - j4_symp_hh, ord="fro"))
                + abs(float(np.linalg.det(dfmcl_8)) - 1.0)
                + float(np.linalg.norm(zmcl_rev - z0_hh))
                + (0.0 if (14.5 <= rich_mcl_ord4 <= 17.5 and (15.0 * edrift_mcl_16) <= edrift_y4_hh16) else 1.0)
