                + abs(sum(wj_k ** 3 for wj_k in w_kl9))
                + abs(sum(wj_k ** 5 for wj_k in w_kl9))
                + float(np.linalg.norm((dfkl_4.T @ j4_symp_hh @ dfkl_4) - j4_symp_hh, ord="fro"))
