            #        mais violant [X_1, [X_1, X_3]] (|c_{1,1,3}| > 0.30) et faisant chuter Richardson de 2^6=64 à 2^4=16
            #     3) gain >= 7.5x en norme supremum orbitale max_{1 <= n <= 64} |H(z_n) - H(z_0)| à h = 0.10 sur Hénon-Heiles :
            def _bch_hall_c113(gam_seq: Tuple[float, ...]) -> float:
                acc_c113 = 0.0
                pref_c113 = 0.0
                for gw_c in gam_seq:
                    mid_c = pref_c113 + (0.5 * gw_c)
                    acc_c113 += (gw_c ** 3) * (mid_c * mid_c)
                    pref_c113 += gw_c
                return acc_c113

            def _orbital_linf_hh_comp(z0_orb: np.ndarray, h_orb: float, n_st_orb: int, gam_orb: Tuple[float, ...]) -> Tuple[np.ndarray, float]:
                q1_o, q2_o, p1_o, p2_o = float(z0_orb[0]), float(z0_orb[1]), float(z0_orb[2]), float(z0_orb[3])
                e0_o = _henon_heiles_energy(z0_orb)
                sup_ed_o = 0.0
                for _ in range(n_st_orb):
                    for gw_o in gam_orb:
                        dtq_o = 0.5 * gw_o * h_orb
                        q1_o += dtq_o * p1_o
                        q2_o += dtq_o * p2_o
                        dtp_o = gw_o * h_orb
                        p1_o += dtp_o * ((-q1_o) - (2.0 * q1_o * q2_o))
                        p2_o += dtp_o * ((-q2_o) - (q1_o * q1_o) + (q2_o * q2_o))
                        q1_o += dtq_o * p1_o
                        q2_o += dtq_o * p2_o
                    cur_ed_o = abs(_henon_heiles_energy(np.array([q1_o, q2_o, p1_o, p2_o], dtype=np.float64)) - e0_o)
                    if cur_ed_o > sup_ed_o:
                        sup_ed_o = cur_ed_o
                return np.array([q1_o, q2_o, p1_o, p2_o], dtype=np.float64), sup_ed_o

            w_kl_perm9 = (
                w_kl_half[3],
                w_kl_half[2],
                w_kl_half[1],
                w_kl_half[0],
                w0_kl,
                w_kl_half[0],
                w_kl_half[1],
                w_kl_half[2],
                w_kl_half[3],
            )
            c113_kl9 = _bch_hall_c113(w_kl9)
            c113_y6a = _bch_hall_c113(gam7_y6s)
