            zperm_4, _ = _orbital_linf_hh_comp(z0_hh, 0.40, 4, w_kl_perm9)
            zperm_8, _ = _orbital_linf_hh_comp(z0_hh, 0.20, 8, w_kl_perm9)
            zperm_16, _ = _orbital_linf_hh_comp(z0_hh, 0.10, 16, w_kl_perm9)
            rich_perm_ord4 = float(np.linalg.norm(zperm_4 - zperm_8)) / max(float(np.linalg.norm(zperm_8 - zperm_16)), 1e-30)
