                + abs(float(e7_64_bl[32]) - (17.0 / 315.0))
                + qmf_sym_bl_err
                + (float(np.linalg.norm((w32_bl3 @ w32_bl3.T) - eye32_d4, ord="fro")) / nrm32_d6)
                + (float(np.linalg.norm((w32_bl3.T @ w32_bl3) - eye32_d4, ord="fro")) / nrm32_d6)
