                + (float(np.linalg.norm((w32_cm.T @ w32_cm) - eye32_d4, ord="fro")) / nrm32_d6)
                + (float(np.linalg.norm((p0_cm + p1_cm) - eye32_d4, ord="fro")) / nrm32_d6)
