            s_op_wr = g_mat_wr.conj().T @ g_mat_wr
            gam_dual_wr = np.linalg.solve(s_op_wr, g_win_wr)
            gam_mat_wr = g_mat_wr @ np.linalg.inv(s_op_wr)
            evs_wr, uvs_wr = np.linalg.eigh(0.5 * (s_op_wr + s_op_wr.conj().T))
            sinv_half_wr = uvs_wr @ np.diag(1.0 / np.sqrt(np.maximum(evs_wr, 1e-15))) @ uvs_wr.conj().T
