                d1_pb = np.cross(verts6_pb[1], verts6_pb[4])
                d2_pb = np.cross(verts6_pb[2], verts6_pb[5])
                d0_pb = d0_pb / np.linalg.norm(d0_pb)
                d1_pb = d1_pb / np.linalg.norm(d1_pb)
                d2_pb = d2_pb / np.linalg.norm(d2_pb)
                b_pt_pb = np.cross(d0_pb, d1_pb)
                b_pt_pb = b_pt_pb / np.linalg.norm(b_pt_pb)
