                p_ab_des = np.cross(np.cross(tri1_des[0], tri1_des[1]), np.cross(tri2_des[0], tri2_des[1]))
                p_bc_des = np.cross(np.cross(tri1_des[1], tri1_des[2]), np.cross(tri2_des[1], tri2_des[2]))
                p_ca_des = np.cross(np.cross(tri1_des[2], tri1_des[0]), np.cross(tri2_des[2], tri2_des[0]))
