                l_axis_des = l_axis_des / np.linalg.norm(l_axis_des)
                r0_des = np.cross(tri1_des[0], tri2_des[0])
                r1_des = np.cross(tri1_des[1], tri2_des[1])
                r2_des = np.cross(tri1_des[2], tri2_des[2])
