                # Théorème de l'hexagone projectif de Pappus d'Alexandrie (~340 ap. J.-C., Collection Mathématique VII) et théorème dual des faisceaux dans RP^2 :
                # 1) sur deux droites distinctes L_1, L_2 portant (A_1, B_1, C_1) et (A_2, B_2, C_2), les 3 intersections de côtés opposés
                #    X_{AB} = (A_1 x B_2) x (A_2 x B_1), X_{BC} = (B_1 x C_2) x (B_2 x C_1), X_{CA} = (C_1 x A_2) x (C_2 x A_1) sont alignées (det == 0)
                # 2) par dualité projective sur deux sommets de faisceaux O_1, O_2 portant chacun 3 droites concourantes, les 3 droites de Pappus duales concourent (det == 0) :
                l1_pap = np.array([0.31 * max(h1_np, 0.25), -1.0, 0.15 * max(w1_np, 0.25)], dtype=np.float64)
                l2_pap = np.array([-0.47 * max(h2_np, 0.25), -1.0, 0.85 * max(w2_np, 0.25)], dtype=np.float64)
                pts_l1_pap = [np.array([xc_p, (l1_pap[0] * xc_p) + l1_pap[2], 1.0], dtype=np.float64) for xc_p in (0.11, 0.63, 1.37)]
                pts_l2_pap = [np.array([xc_p, (l2_pap[0] * xc_p) + l2_pap[2], 1.0], dtype=np.float64) for xc_p in (0.19, 0.83, 1.53)]
                x_ab_pap = np.cross(np.cross(pts_l1_pap[0], pts_l2_pap[1]), np.cross(pts_l2_pap[0], pts_l1_pap[1]))
                x_bc_pap = np.cross(np.cross(pts_l1_pap[1], pts_l2_pap[2]), np.cross(pts_l2_pap[1], pts_l1_pap[2]))
                x_ca_pap = np.cross(np.cross(pts_l1_pap[2], pts_l2_pap[0]), np.cross(pts_l2_pap[2], pts_l1_pap[0]))
                x_ab_pap = x_ab_pap / np.linalg.norm(x_ab_pap)
                x_bc_pap = x_bc_pap / np.linalg.norm(x_bc_pap)
                x_ca_pap = x_ca_pap / np.linalg.norm(x_ca_pap)
                o1_dp = np.array([0.17 * max(w1_np, 0.25), 0.29 * max(h1_np, 0.25), 1.0], dtype=np.float64)
                o2_dp = np.array([0.89 * max(w2_np, 0.25), -0.23 * max(h2_np, 0.25), 1.0], dtype=np.float64)
                pen1_dp = [np.cross(o1_dp, np.array([1.0, sl_p, 0.0], dtype=np.float64)) for sl_p in (-0.4, 0.35, 1.25)]
                pen2_dp = [np.cross(o2_dp, np.array([1.0, sl_p, 0.0], dtype=np.float64)) for sl_p in (-0.65, 0.15, 0.95)]
                m_ab_dp = np.cross(np.cross(pen1_dp[0], pen2_dp[1]), np.cross(pen2_dp[0], pen1_dp[1]))
                m_bc_dp = np.cross(np.cross(pen1_dp[1], pen2_dp[2]), np.cross(pen2_dp[1], pen1_dp[2]))
                m_ca_dp = np.cross(np.cross(pen1_dp[2], pen2_dp[0]), np.cross(pen2_dp[2], pen1_dp[0]))
                m_ab_dp = m_ab_dp / np.linalg.norm(m_ab_dp)
                m_bc_dp = m_bc_dp / np.linalg.norm(m_bc_dp)
                m_ca_dp = m_ca_dp / np.linalg.norm(m_ca_dp)
                pappus_hexagon_errs.append(
                    max(
                        max(abs(float(l1_pap @ pt_p)) for pt_p in pts_l1_pap),
                        max(abs(float(l2_pap @ pt_p)) for pt_p in pts_l2_pap),
                        abs(float(np.linalg.det(np.column_stack([x_ab_pap, x_bc_pap, x_ca_pap])))),
                        abs(float(np.linalg.det(np.column_stack([m_ab_dp, m_bc_dp, m_ca_dp])))),
                    )
                )
                # Théorèmes duaux des rapports signés de Ménélaüs d'Alexandrie (~100 apr. J.-C., Sphaerica III.1)
                # et de Giovanni Ceva (1678, De lineis rectis) + polaire trilinéaire projective sur les boîtes englobantes f3d :
                # 1) céviennes AP, BP, CP concourantes en P => (BD/DC)*(CE/EA)*(AF/FB) == +1
                # 2) transversale projective L coupant BC, CA, AB en D_m, E_m, F_m => (BD_m/D_mC)*(CE_m/E_mA)*(AF_m/F_mB) == -1
                # 3) polaire trilinéaire projective D_p = BC inter EF, E_p = CA inter FD, F_p = AB inter DE alignée (det == 0) et produit de Ménélaüs == -1 :
                a_mc = np.array([0.0, 0.0, 1.0], dtype=np.float64)
                b_mc = np.array([max(w1_np, 0.25), 0.19 * max(h1_np, 0.25), 1.0], dtype=np.float64)
                c_mc = np.array([0.27 * max(w2_np, 0.25), max(h2_np, 0.25), 1.0], dtype=np.float64)
                p_mc = (0.31 * a_mc) + (0.37 * b_mc) + (0.32 * c_mc)

                def _inter_mc(p1_m: np.ndarray, p2_m: np.ndarray, q1_m: np.ndarray, q2_m: np.ndarray) -> np.ndarray:
                    pt_m = np.cross(np.cross(p1_m, p2_m), np.cross(q1_m, q2_m))
                    return pt_m / pt_m[2]

                def _srat_mc(u1_m: np.ndarray, u2_m: np.ndarray, q_m: np.ndarray) -> float:
                    dir_m = u2_m[:2] - u1_m[:2]
                    return float(np.dot(q_m[:2] - u1_m[:2], dir_m)) / float(np.dot(u2_m[:2] - q_m[:2], dir_m))

                d_cev_mc = _inter_mc(a_mc, p_mc, b_mc, c_mc)
                e_cev_mc = _inter_mc(b_mc, p_mc, c_mc, a_mc)
                f_cev_mc = _inter_mc(c_mc, p_mc, a_mc, b_mc)
                ceva_prod_mc = _srat_mc(b_mc, c_mc, d_cev_mc) * _srat_mc(c_mc, a_mc, e_cev_mc) * _srat_mc(a_mc, b_mc, f_cev_mc)
                l_trn_mc = np.array([0.41, 0.53, -0.29 * max(w1_np, 0.25)], dtype=np.float64)
                dm_mc = np.cross(np.cross(b_mc, c_mc), l_trn_mc)
                dm_mc = dm_mc / dm_mc[2]
                em_mc = np.cross(np.cross(c_mc, a_mc), l_trn_mc)
                em_mc = em_mc / em_mc[2]
                fm_mc = np.cross(np.cross(a_mc, b_mc), l_trn_mc)
                fm_mc = fm_mc / fm_mc[2]
                men_prod_mc = _srat_mc(b_mc, c_mc, dm_mc) * _srat_mc(c_mc, a_mc, em_mc) * _srat_mc(a_mc, b_mc, fm_mc)
                dp_pol_mc = _inter_mc(b_mc, c_mc, e_cev_mc, f_cev_mc)
                ep_pol_mc = _inter_mc(c_mc, a_mc, f_cev_mc, d_cev_mc)
                fp_pol_mc = _inter_mc(a_mc, b_mc, d_cev_mc, e_cev_mc)
                pol_men_mc = _srat_mc(b_mc, c_mc, dp_pol_mc) * _srat_mc(c_mc, a_mc, ep_pol_mc) * _srat_mc(a_mc, b_mc, fp_pol_mc)
                dp_pol_u = dp_pol_mc / np.linalg.norm(dp_pol_mc)
                ep_pol_u = ep_pol_mc / np.linalg.norm(ep_pol_mc)
                fp_pol_u = fp_pol_mc / np.linalg.norm(fp_pol_mc)
                menelaus_ceva_errs.append(
                    max(
                        abs(ceva_prod_mc - 1.0),
                        abs(men_prod_mc + 1.0),
                        abs(float(np.linalg.det(np.column_stack([dp_pol_u, ep_pol_u, fp_pol_u])))),
                        abs(pol_men_mc + 1.0),
                    )
                )
                # Conjugué harmonique projectif du quadrilatère complet à la règle seule de Jean-Victor Poncelet
                # (1822, Traité des propriétés projectives des figures) & Karl von Staudt (1847) :
                # 1) indépendance du choix du quadrilatère complet Q_1 == Q_2 et birapport harmonique exact (A, B; P, Q) == -1
                # 2) relation métrique de Newton au milieu M = (A + B)/2 : <P - M, Q - M> == ||A - M||^2
                # 3) invariance exacte du birapport harmonique (A', B'; P', Q') == -1 par perspectivité centrale sur une droite inclinée :
                pa_ph = np.array([za_np.real, za_np.imag, 1.0], dtype=np.float64)
                pb_ph = np.array([zb_np.real, zb_np.imag, 1.0], dtype=np.float64)
                t_in_ph = 0.34
                pp_ph = ((1.0 - t_in_ph) * pa_ph) + (t_in_ph * pb_ph)

                def _dehom2_ph(v_ph: np.ndarray) -> np.ndarray:
                    return v_ph[:2] / float(v_ph[2])

                def _quad_fourth_harmonic_ph(r_ext_ph: np.ndarray, lam_s_ph: float, lam_u_ph: float) -> np.ndarray:
                    g1_ph = r_ext_ph
                    g2_ph = ((1.0 - lam_u_ph) * pa_ph) + (lam_u_ph * r_ext_ph)
                    g3_ex_ph = np.cross(np.cross(pb_ph, g2_ph), np.cross(pp_ph, g1_ph))
                    g4_ex_ph = np.cross(np.cross(pa_ph, g3_ex_ph), np.cross(pb_ph, g1_ph))
                    q_ex_ph = np.cross(np.cross(g2_ph, g4_ex_ph), np.cross(pa_ph, pb_ph))
                    return _dehom2_ph(q_ex_ph)

                r1_ph = np.array([zc_np.real + (0.15 * w1_np), zc_np.imag + (0.22 * h2_np), 1.0], dtype=np.float64)
                r2_ph = np.array([(-0.37 * w1_np), (0.83 * h2_np) + (0.19 * h1_np), 1.0], dtype=np.float64)
                q1_2d_ph = _quad_fourth_harmonic_ph(r1_ph, 0.41, 0.58)
                q2_2d_ph = _quad_fourth_harmonic_ph(r2_ph, 0.29, 0.67)
                a2_ph = _dehom2_ph(pa_ph)
                b2_ph = _dehom2_ph(pb_ph)
                p2_ph = _dehom2_ph(pp_ph)
                ab_vec_ph = b2_ph - a2_ph
                ab_n2_ph = max(float(np.dot(ab_vec_ph, ab_vec_ph)), 1e-12)
                s_p_ph = float(np.dot(p2_ph - a2_ph, ab_vec_ph)) / ab_n2_ph
                s_q_ph = float(np.dot(q1_2d_ph - a2_ph, ab_vec_ph)) / ab_n2_ph
                cr_abpq_ph = (s_p_ph / (s_p_ph - 1.0)) / (s_q_ph / (s_q_ph - 1.0))
                mid_ab_ph = 0.5 * (a2_ph + b2_ph)
                newton_lhs_ph = float(np.dot(p2_ph - mid_ab_ph, q1_2d_ph - mid_ab_ph))
                newton_rhs_ph = float(np.dot(a2_ph - mid_ab_ph, a2_ph - mid_ab_ph))
                o_persp_ph = np.array([0.23 * w1_np, -0.71 * max(h1_np, h2_np, 1.0), 1.0], dtype=np.float64)
                l_img_ph = np.array([0.31, 1.0, -0.27 * max(h1_np, h2_np, 1.0)], dtype=np.float64)
                qh1_ph = np.array([q1_2d_ph[0], q1_2d_ph[1], 1.0], dtype=np.float64)
                ap_2d_ph = _dehom2_ph(np.cross(np.cross(o_persp_ph, pa_ph), l_img_ph))
                bp_2d_ph = _dehom2_ph(np.cross(np.cross(o_persp_ph, pb_ph), l_img_ph))
                pp_2d_ph = _dehom2_ph(np.cross(np.cross(o_persp_ph, pp_ph), l_img_ph))
                qp_2d_ph = _dehom2_ph(np.cross(np.cross(o_persp_ph, qh1_ph), l_img_ph))
                abp_vec_ph = bp_2d_ph - ap_2d_ph
                abp_n2_ph = max(float(np.dot(abp_vec_ph, abp_vec_ph)), 1e-12)
                sp_p_ph = float(np.dot(pp_2d_ph - ap_2d_ph, abp_vec_ph)) / abp_n2_ph
                sp_q_ph = float(np.dot(qp_2d_ph - ap_2d_ph, abp_vec_ph)) / abp_n2_ph
                cr_persp_ph = (sp_p_ph / (sp_p_ph - 1.0)) / (sp_q_ph / (sp_q_ph - 1.0))
                poncelet_harmonic_quadrangle_errs.append(
                    max(
                        float(np.linalg.norm(q1_2d_ph - q2_2d_ph)) / math.sqrt(ab_n2_ph),
                        abs(cr_abpq_ph + 1.0),
                        abs(newton_lhs_ph - newton_rhs_ph) / ab_n2_ph,
                        abs(cr_persp_ph + 1.0),
                    )
                )
                # Birapport homographique PGL(2, C) d'August Ferdinand Möbius (1827, Der barycentrische Calcul)
                # et théorème d'involution harmonique de Michel Chasles (1852, Traité de géométrie supérieure) sur CP^1 :
                # 1) invariance exacte du birapport complexe (z_A, z_B; z_C, z_D) sous homographie inversible M in GL(2, C) et loi de groupe (M_2 * M_1)(z)
                # 2) groupe anharmonique S_3 à 6 valeurs : 1/lambda, 1 - lambda et lambda/(lambda - 1)
                # 3) involution de Chasles J(z) = (a*z + b)/(c*z - a) (tr(J) == 0, J(J(z)) == z) : division harmonique exacte (u_+, u_-; z, J(z)) == -1 :
                zd_hm = complex(-0.43 * w1_np, 0.67 * max(h1_np, h2_np, 0.25))

                def _cr_cp1_hm(z1_h: complex, z2_h: complex, z3_h: complex, z4_h: complex) -> complex:
                    return ((z1_h - z3_h) * (z2_h - z4_h)) / ((z1_h - z4_h) * (z2_h - z3_h))

                def _mob_cp1_hm(mat_h: np.ndarray, z_h: complex) -> complex:
                    return complex(((mat_h[0, 0] * z_h) + mat_h[0, 1]) / ((mat_h[1, 0] * z_h) + mat_h[1, 1]))

                m1_hm = np.array([[1.3 + 0.4j, -0.7 + 0.9j], [0.25 - 0.3j, 1.1 + 0.5j]], dtype=np.complex128)
                m2_hm = np.array([[0.8 - 0.5j, 0.6 + 0.2j], [-0.35 + 0.15j, 1.25 + 0.3j]], dtype=np.complex128)
                m21_hm = m2_hm @ m1_hm
                cr0_hm = _cr_cp1_hm(za_np, zb_np, zc_np, zd_hm)
                cr1_hm = _cr_cp1_hm(
                    _mob_cp1_hm(m1_hm, za_np),
                    _mob_cp1_hm(m1_hm, zb_np),
                    _mob_cp1_hm(m1_hm, zc_np),
                    _mob_cp1_hm(m1_hm, zd_hm),
                )
                a_inv_hm = 0.7 + 0.3j
                b_inv_hm = 1.1 - 0.4j
                c_inv_hm = 0.5 - 0.2j
                m_inv_hm = np.array([[a_inv_hm, b_inv_hm], [c_inv_hm, -a_inv_hm]], dtype=np.complex128)
                disc_inv_hm = complex(np.sqrt((a_inv_hm * a_inv_hm) + (b_inv_hm * c_inv_hm)))
                u_pos_hm = (a_inv_hm + disc_inv_hm) / c_inv_hm
                u_neg_hm = (a_inv_hm - disc_inv_hm) / c_inv_hm
                jzc_hm = _mob_cp1_hm(m_inv_hm, zc_np)
                mobius_chasles_homography_errs.append(
                    max(
                        abs(cr1_hm - cr0_hm),
                        abs(_mob_cp1_hm(m2_hm, _mob_cp1_hm(m1_hm, zc_np)) - _mob_cp1_hm(m21_hm, zc_np)),
                        abs(_cr_cp1_hm(za_np, zb_np, zd_hm, zc_np) - (1.0 / cr0_hm)),
                        abs(_cr_cp1_hm(za_np, zc_np, zb_np, zd_hm) - (1.0 - cr0_hm)),
                        abs(_cr_cp1_hm(za_np, zd_hm, zc_np, zb_np) - (cr0_hm / (cr0_hm - 1.0))),
                        abs(_mob_cp1_hm(m_inv_hm, jzc_hm) - zc_np),
                        abs(_cr_cp1_hm(u_pos_hm, u_neg_hm, zc_np, jzc_hm) + 1.0),
                    )
                )
                # Génération projective des coniques par faisceaux homographiques de droites de Steiner (1832) & Chasles (1852) dans RP^2 :
                # 1) l'intersection Q(t) = l_1(t) x l_2(H(t)) de deux faisceaux de sommets P_1, P_2 liés par H in PGL(2,R) engendre une conique non dégénérée C (rang de Veronese 8x6 == 5, |det(C)| > 1e-4) passant par P_1 et P_2
                # 2) invariance de Chasles du birapport des 4 rayons [V Q_1, V Q_2 ; V Q_3, V Q_4] pour tout sommet V in {P_1, P_2, Q_5, Q_6, Q_7} sur C et égalité exacte avec le birapport projectif [t_1, t_2 ; t_3, t_4] :
                p1_st = np.array([0.0, 0.0, 1.0], dtype=np.float64)
                p2_st = np.array([w1_np, 0.35 * h1_np, 1.0], dtype=np.float64)
                l1_a_st = np.cross(p1_st, np.array([w1_np, 0.20 * h1_np, 1.0], dtype=np.float64))
                l1_b_st = np.cross(p1_st, np.array([0.25 * w2_np, h2_np, 1.0], dtype=np.float64))
                l2_a_st = np.cross(p2_st, np.array([0.10 * w2_np, 0.95 * h2_np, 1.0], dtype=np.float64))
                l2_b_st = np.cross(p2_st, np.array([0.55 * w1_np, -0.40 * h1_np, 1.0], dtype=np.float64))
                mh_st = np.array([[1.3, -0.4], [0.5, 0.9]], dtype=np.float64)
                ts_st = (-1.7, -0.6, -0.15, 0.35, 0.85, 1.45, 2.1, 3.2)
                pts_st = []
                for t_st in ts_st:
                    u_st = mh_st @ np.array([t_st, 1.0], dtype=np.float64)
                    l1_t_st = (t_st * l1_a_st) + l1_b_st
                    l2_t_st = (u_st[0] * l2_a_st) + (u_st[1] * l2_b_st)
                    q_st = np.cross(l1_t_st, l2_t_st)
                    pts_st.append(q_st / q_st[2])
                ver_st = np.array(
                    [[q[0] * q[0], q[0] * q[1], q[1] * q[1], q[0] * q[2], q[1] * q[2], q[2] * q[2]] for q in pts_st],
                    dtype=np.float64,
                )
                _, sv_st, vt_st = np.linalg.svd(ver_st)
                cv_st = vt_st[-1]
                c_mat_st = np.array(
                    [
                        [cv_st[0], 0.5 * cv_st[1], 0.5 * cv_st[3]],
                        [0.5 * cv_st[1], cv_st[2], 0.5 * cv_st[4]],
                        [0.5 * cv_st[3], 0.5 * cv_st[4], cv_st[5]],
                    ],
                    dtype=np.float64,
                )
                c_mat_st /= np.linalg.norm(c_mat_st, ord="fro")

                def _cr_4rays_st(vtx_st: np.ndarray, four_pts_st: list[np.ndarray]) -> float:
                    def _br_st(pa_st: np.ndarray, pb_st: np.ndarray) -> float:
                        return float(np.linalg.det(np.vstack([vtx_st, pa_st, pb_st])))

                    q1_r, q2_r, q3_r, q4_r = four_pts_st
                    return (_br_st(q1_r, q3_r) * _br_st(q2_r, q4_r)) / (_br_st(q1_r, q4_r) * _br_st(q2_r, q3_r))

                four_conic_st = [pts_st[0], pts_st[1], pts_st[2], pts_st[3]]
                cr_ref_st = _cr_4rays_st(p1_st, four_conic_st)
                cr_max_st = max(
                    abs(_cr_4rays_st(v_st, four_conic_st) - cr_ref_st)
                    for v_st in (p2_st, pts_st[4], pts_st[5], pts_st[6])
                )
                cr_mob_st = ((ts_st[0] - ts_st[2]) * (ts_st[1] - ts_st[3])) / (
                    (ts_st[0] - ts_st[3]) * (ts_st[1] - ts_st[2])
                )
                steiner_chasles_pencil_conic_errs.append(
                    (sv_st[5] / sv_st[0])
                    + abs(float(p1_st @ c_mat_st @ p1_st))
                    + abs(float(p2_st @ c_mat_st @ p2_st))
                    + cr_max_st
                    + abs(cr_ref_st - cr_mob_st)
                    + (0.0 if ((sv_st[4] / sv_st[0]) > 1e-3 and abs(float(np.linalg.det(c_mat_st))) > 1e-4) else 1.0)
                )
                # Porisme de clôture triangulaire (n = 3) de Jean-Victor Poncelet (1822) & invariant déterminantiel cubique
                # d'Arthur Cayley (1853, Phil. Mag. 5:281) sur paire d'ellipses projectivement inclinées (C, D) issues des silhouettes f3d :
                # det(t*C + D) = det(C)*t^3 + Theta_1*t^2 + Theta_2*t + det(D), condition exacte Theta_2^2 - 4*Theta_1*det(D) == 0
                # et clôture tangentielle en 3 pas P_3 == P_0 dans RP^2 indépendamment de l'angle initial phi_0 :
                ax_pc = 0.5 + (0.65 * w1_np)
                by_pc = 0.5 + (0.65 * h1_np)
                sh_pc = 0.14 * (w2_np - h2_np)
                h_proj_pc = np.array(
                    [
                        [ax_pc, sh_pc, 0.09 * w2_np],
                        [0.05 * h2_np, by_pc, -0.07 * h1_np],
                        [0.06 * w1_np, -0.05 * h2_np, 1.0],
                    ],
                    dtype=np.float64,
                )
                hinv_pc = np.linalg.inv(h_proj_pc)
                c_std_pc = np.diag([1.0, 1.0, -1.0])
                d_std_pc = np.diag([4.0, 4.0, -1.0])
                c_con_pc = hinv_pc.T @ c_std_pc @ hinv_pc
                d_con_pc = hinv_pc.T @ d_std_pc @ hinv_pc
                d_dual_pc = np.linalg.inv(d_con_pc)
                dc_prod_pc = np.linalg.solve(c_con_pc, d_con_pc)
                det_c_pc = float(np.linalg.det(c_con_pc))
                det_d_pc = float(np.linalg.det(d_con_pc))
                tr1_pc = float(np.trace(dc_prod_pc))
                tr2_pc = 0.5 * ((tr1_pc * tr1_pc) - float(np.trace(dc_prod_pc @ dc_prod_pc)))
                th1_pc = det_c_pc * tr1_pc
                th2_pc = det_c_pc * tr2_pc
                cayley_res_pc = abs((th2_pc * th2_pc) - (4.0 * th1_pc * det_d_pc)) / max(
                    abs(4.0 * th1_pc * det_d_pc), 1e-12
                )
                max_clos_pc = 0.0
                for phi0_pc in (0.19, 0.83, 1.71, 2.57):
                    p0_pc = h_proj_pc @ np.array([math.cos(phi0_pc), math.sin(phi0_pc), 1.0], dtype=np.float64)
                    p0_pc = p0_pc / p0_pc[2]
                    p_cur_pc = p0_pc.copy()
                    l_prev_pc = None
                    for _ in range(3):
                        u1_pc = np.array([1.0, 0.0, -p_cur_pc[0]], dtype=np.float64)
                        u2_pc = np.array([0.0, 1.0, -p_cur_pc[1]], dtype=np.float64)
                        qa_pc = float(u1_pc @ d_dual_pc @ u1_pc)
                        qb_pc = 2.0 * float(u1_pc @ d_dual_pc @ u2_pc)
                        qc_pc = float(u2_pc @ d_dual_pc @ u2_pc)
                        disc_pc = math.sqrt(max((qb_pc * qb_pc) - (4.0 * qa_pc * qc_pc), 0.0))
                        if abs(qa_pc) >= abs(qc_pc):
                            t_a_pc = (-qb_pc + disc_pc) / (2.0 * qa_pc)
                            t_b_pc = (-qb_pc - disc_pc) / (2.0 * qa_pc)
                            la_pc = (t_a_pc * u1_pc) + u2_pc
                            lb_pc = (t_b_pc * u1_pc) + u2_pc
                        else:
                            s_a_pc = (-qb_pc + disc_pc) / (2.0 * qc_pc)
                            s_b_pc = (-qb_pc - disc_pc) / (2.0 * qc_pc)
                            la_pc = u1_pc + (s_a_pc * u2_pc)
                            lb_pc = u1_pc + (s_b_pc * u2_pc)
                        la_pc = la_pc / np.linalg.norm(la_pc)
                        lb_pc = lb_pc / np.linalg.norm(lb_pc)
                        if l_prev_pc is None:
                            l_next_pc = la_pc
                        else:
                            ca_pc = abs(float(np.dot(la_pc, l_prev_pc)))
                            cb_pc = abs(float(np.dot(lb_pc, l_prev_pc)))
                            l_next_pc = la_pc if ca_pc < cb_pc else lb_pc
                        if abs(l_next_pc[0]) >= abs(l_next_pc[1]):
                            q_base_pc = np.array([-l_next_pc[2] / l_next_pc[0], 0.0, 1.0], dtype=np.float64)
                            v_dir_pc = np.array([-l_next_pc[1], l_next_pc[0], 0.0], dtype=np.float64)
                        else:
                            q_base_pc = np.array([0.0, -l_next_pc[2] / l_next_pc[1], 1.0], dtype=np.float64)
                            v_dir_pc = np.array([l_next_pc[1], -l_next_pc[0], 0.0], dtype=np.float64)
                        dq_pc = p_cur_pc - q_base_pc
                        s0_pc = float(np.dot(dq_pc[:2], v_dir_pc[:2])) / float(np.dot(v_dir_pc[:2], v_dir_pc[:2]))
                        ca2_pc = float(v_dir_pc @ c_con_pc @ v_dir_pc)
                        cb2_pc = 2.0 * float(q_base_pc @ c_con_pc @ v_dir_pc)
                        s_next_pc = (-cb2_pc / ca2_pc) - s0_pc
                        p_next_pc = q_base_pc + (s_next_pc * v_dir_pc)
                        p_cur_pc = p_next_pc / p_next_pc[2]
                        l_prev_pc = l_next_pc
                    max_clos_pc = max(max_clos_pc, float(np.linalg.norm(p_cur_pc - p0_pc)))
                poncelet_cayley_triangle_porism_errs.append(cayley_res_pc + max_clos_pc)
                # Formule projective des angles euclidiens par birapport aux points cycliques à l'infini I_inf = [1 : i : 0], J_inf = [1 : -i : 0]
                # d'Edmond Laguerre (1853, Nouv. Ann. Math. 12:225, Note sur la théorie des foyers) dans CP^2 :
                # 1) CR(P_0 Q_1, P_0 Q_2 ; P_0 I_inf, P_0 J_inf) == exp(-2*i*(theta_2 - theta_1)) et angle exact (i/2)*log(CR) == theta_2 - theta_1
                # 2) orthogonalité euclidienne <=> division harmonique CR(P_0 Q_1, P_0 Q_perp ; P_0 I_inf, P_0 J_inf) == -1 et invariance Sim^+(2) :
                i_inf_lg = np.array([1.0 + 0.0j, 1.0j, 0.0 + 0.0j], dtype=np.complex128)
                j_inf_lg = np.array([1.0 + 0.0j, -1.0j, 0.0 + 0.0j], dtype=np.complex128)
                x0_lg, y0_lg = 0.23 * w1_np, -0.17 * h1_np
                p0_lg = np.array([x0_lg, y0_lg, 1.0], dtype=np.complex128)
                th1_lg = 0.5 * math.atan2(max(h1_np, 0.25), max(w1_np, 0.25))
                th2_lg = 0.5 * math.atan2(max(h2_np, 0.25), -0.65 * max(w2_np, 0.25))
                q1_lg = np.array([x0_lg + math.cos(th1_lg), y0_lg + math.sin(th1_lg), 1.0], dtype=np.complex128)
                q2_lg = np.array([x0_lg + math.cos(th2_lg), y0_lg + math.sin(th2_lg), 1.0], dtype=np.complex128)
                qp_lg = np.array([x0_lg - math.sin(th1_lg), y0_lg + math.cos(th1_lg), 1.0], dtype=np.complex128)

                def _cr_lag_lg(v0_l: np.ndarray, a_l: np.ndarray, b_l: np.ndarray) -> complex:
                    d_ai_l = complex(np.linalg.det(np.vstack([v0_l, a_l, i_inf_lg])))
                    d_bj_l = complex(np.linalg.det(np.vstack([v0_l, b_l, j_inf_lg])))
                    d_aj_l = complex(np.linalg.det(np.vstack([v0_l, a_l, j_inf_lg])))
                    d_bi_l = complex(np.linalg.det(np.vstack([v0_l, b_l, i_inf_lg])))
                    return (d_ai_l * d_bj_l) / (d_aj_l * d_bi_l)

                cr_12_lg = _cr_lag_lg(p0_lg, q1_lg, q2_lg)
                cr_perp_lg = _cr_lag_lg(p0_lg, q1_lg, qp_lg)
                ang_rec_lg = complex(np.log(cr_12_lg) / (-2.0j))
                ca_sim_lg, sa_sim_lg = 1.37 * math.cos(0.61), 1.37 * math.sin(0.61)
                sim_mat_lg = np.array(
                    [
                        [ca_sim_lg, -sa_sim_lg, 0.41 * w1_np],
                        [sa_sim_lg, ca_sim_lg, -0.29 * h2_np],
                        [0.0, 0.0, 1.0],
                    ],
                    dtype=np.complex128,
                )
                cr_sim_lg = _cr_lag_lg(sim_mat_lg @ p0_lg, sim_mat_lg @ q1_lg, sim_mat_lg @ q2_lg)
                laguerre_circular_points_angle_errs.append(
                    abs(cr_12_lg - np.exp(-2.0j * (th2_lg - th1_lg)))
                    + abs(ang_rec_lg - (th2_lg - th1_lg))
                    + abs(cr_perp_lg + 1.0)
                    + abs(cr_sim_lg - cr_12_lg)
                )
                # Théorème Généralisé de Ptolémée pour Quatre Cercles Tangents à un Cercle Directeur de John Casey
                # (1866, Proc. R. Ir. Acad. 9:396, On the Equations and Properties of the System of Circles Touching Three Circles in a Plane)
                # et nullité exacte du déterminant symétrique 4x4 de Cayley des carrés des bitangentes extérieures :
                # t_12*t_34 + t_14*t_23 == t_13*t_24 et det([t_{ij}^2]) == 0 :
                r_master_cs = 90.0 + float(w1_np) + float(h1_np)
                radii_cs = (
                    0.07 * r_master_cs,
                    0.11 * r_master_cs,
                    0.09 * r_master_cs,
                    0.13 * r_master_cs,
                )
                ths_cs = (
                    0.19,
                    0.95 + (0.25 * (float(w2_np) / max(float(w1_np) + float(w2_np), 1e-6))),
                    2.31,
                    4.17 + (0.20 * (float(h2_np) / max(float(h1_np) + float(h2_np), 1e-6))),
                )
                ctrs_cs = [
                    (r_master_cs - radii_cs[i_cs]) * complex(math.cos(ths_cs[i_cs]), math.sin(ths_cs[i_cs]))
                    for i_cs in range(4)
                ]
                tmat_cs = np.zeros((4, 4), dtype=np.float64)
                for i_cs in range(4):
                    for j_cs in range(4):
                        if i_cs != j_cs:
                            d2_cs = abs(ctrs_cs[i_cs] - ctrs_cs[j_cs]) ** 2
                            dr_cs = radii_cs[i_cs] - radii_cs[j_cs]
                            tmat_cs[i_cs, j_cs] = math.sqrt(max(0.0, d2_cs - (dr_cs * dr_cs)))
                casey_lhs_cs = (tmat_cs[0, 1] * tmat_cs[2, 3]) + (tmat_cs[0, 3] * tmat_cs[1, 2])
                casey_rhs_cs = tmat_cs[0, 2] * tmat_cs[1, 3]
                t2mat_cs = tmat_cs * tmat_cs
                casey_ptolemy_four_tangent_circles_errs.append(
                    (abs(casey_lhs_cs - casey_rhs_cs) / (r_master_cs * r_master_cs))
                    + (abs(float(np.linalg.det(t2mat_cs))) / (r_master_cs ** 8))
                )
                # Roger A. Johnson (1916, Amer. Math. Monthly 23:161) Three Equal Circles Theorem & Orthocenter-Circumcenter Anticomplementary Duality:
                # Let three equal circles Gamma_1, Gamma_2, Gamma_3 of radius R_J > 0 with centers O_1, O_2, O_3 pass through a common point H_J,
                # so O_k = H_J + R_J * exp(i * phi_k) (k = 1, 2, 3). Their other three pairwise intersection points are
                # P_1 = Gamma_2 cap Gamma_3 = H_J + R_J * (exp(i*phi_2) + exp(i*phi_3)),
                # P_2 = Gamma_3 cap Gamma_1 = H_J + R_J * (exp(i*phi_3) + exp(i*phi_1)),
                # P_3 = Gamma_1 cap Gamma_2 = H_J + R_J * (exp(i*phi_1) + exp(i*phi_2)).
                # Then: (1) P_1, P_2, P_3 lie on a fourth circle (Johnson's circle) of the exact same radius R_J centered at
                # O_J = H_J + R_J * (exp(i*phi_1) + exp(i*phi_2) + exp(i*phi_3)), so |P_k - O_J| == R_J for k = 1, 2, 3;
                # (2) H_J is the orthocenter of the Johnson triangle P_1 P_2 P_3 (Re((P_1 - H_J)*conj(P_2 - P_3)) == 0, etc.)
                # and O_J is the orthocenter of the center triangle O_1 O_2 O_3 (which has circumcenter H_J and circumradius R_J);
                # (3) Triangle P_1 P_2 P_3 and triangle O_1 O_2 O_3 are centrally symmetric (congruent by half-turn) around their common nine-point center
                # N_J = (H_J + O_J)/2, with P_k + O_k == H_J + O_J == 2 * N_J for k = 1, 2, 3.
                wf, hf, ws, hs = float(w1_np), float(h1_np), float(w2_np), float(h2_np)
                r_j16 = 0.55 * math.hypot(wf, hf) + 0.35 * math.hypot(ws, hs) + 1.0
                h_j16 = complex(0.25 * wf, -0.15 * hf)
                u1_j16 = cmath.rect(1.0, 0.17 + 0.19 * (wf / (wf + hf + 1.0)))
                u2_j16 = cmath.rect(1.0, 1.83 + 0.23 * (ws / (ws + hs + 1.0)))
                u3_j16 = cmath.rect(1.0, 3.91 + 0.13 * (hf / (wf + hf + 1.0)))
                o1_j16 = h_j16 + r_j16 * u1_j16
                o2_j16 = h_j16 + r_j16 * u2_j16
                o3_j16 = h_j16 + r_j16 * u3_j16
                p1_j16 = h_j16 + r_j16 * (u2_j16 + u3_j16)
                p2_j16 = h_j16 + r_j16 * (u3_j16 + u1_j16)
                p3_j16 = h_j16 + r_j16 * (u1_j16 + u2_j16)
                oj_j16 = h_j16 + r_j16 * (u1_j16 + u2_j16 + u3_j16)
                rad_p_j16_err = (
                    abs(abs(p1_j16 - oj_j16) - r_j16)
                    + abs(abs(p2_j16 - oj_j16) - r_j16)
                    + abs(abs(p3_j16 - oj_j16) - r_j16)
                    + abs(abs(p1_j16 - o2_j16) - r_j16)
                    + abs(abs(p1_j16 - o3_j16) - r_j16)
                    + abs(abs(p2_j16 - o3_j16) - r_j16)
                    + abs(abs(p2_j16 - o1_j16) - r_j16)
                    + abs(abs(p3_j16 - o1_j16) - r_j16)
                    + abs(abs(p3_j16 - o2_j16) - r_j16)
                ) / r_j16
                ortho_j16_err = (
                    abs(((p1_j16 - h_j16) * (p2_j16 - p3_j16).conjugate()).real)
                    + abs(((p2_j16 - h_j16) * (p3_j16 - p1_j16).conjugate()).real)
                    + abs(((p3_j16 - h_j16) * (p1_j16 - p2_j16).conjugate()).real)
                    + abs(((o1_j16 - oj_j16) * (o2_j16 - o3_j16).conjugate()).real)
                    + abs(((o2_j16 - oj_j16) * (o3_j16 - o1_j16).conjugate()).real)
                    + abs(((o3_j16 - oj_j16) * (o1_j16 - o2_j16).conjugate()).real)
                ) / (r_j16 * r_j16)
                sym_j16_err = (
                    abs((p1_j16 + o1_j16) - (h_j16 + oj_j16))
                    + abs((p2_j16 + o2_j16) - (h_j16 + oj_j16))
                    + abs((p3_j16 + o3_j16) - (h_j16 + oj_j16))
                ) / r_j16
                johnson_three_equal_circles_errs.append(float(rad_p_j16_err + ortho_j16_err + sym_j16_err))
                # Porisme de Steiner (Jakob Steiner 1826, J. Reine Angew. Math. 1:161) — Collier fermé de n = 6 cercles tangents :
                # dans le repère concentrique où sin(pi/6) = 1/2 = (R_out - R_in)/(R_out + R_in) => R_out = 3*R_in,
                # les 6 cercles de rayon r_c = R_in et centres c_k = 2*R_in*exp(i*(theta_0 + k*pi/3)) sont tangents à C_in, C_out et à leurs voisins ;
                # toute inversion de Möbius z -> z_p + K_inv / conj(z - z_p) préserve exactement les 6 tangences intérieures, les 6 tangences extérieures,
                # les 6 tangences cycliques et l'invariant anallagmatique de Coxeter cosh(delta/2) == (R_out' + R_in')/(R_out' - R_in') == 2 :
                rin_st26 = 0.25 * (w1_cm + h1_cm)
                rout_st26 = 3.0 * rin_st26
                th0_st26 = 0.15 + 0.05 * (w2_cm / max(h2_cm, 1e-12))
                zp_st26 = complex(-5.5 * rin_st26, 4.2 * rin_st26)
                kinv_st26 = 16.0 * (rin_st26 * rin_st26)

                def _invert_circle_st26(c_orig: complex, r_orig: float) -> tuple[complex, float]:
                    d2_p = abs(c_orig - zp_st26) ** 2 - (r_orig * r_orig)
                    scale_p = kinv_st26 / d2_p
                    c_img = zp_st26 + (scale_p * (c_orig - zp_st26))
                    r_img = abs(scale_p) * r_orig
                    return c_img, r_img

                cin_p_st26, rin_p_st26 = _invert_circle_st26(0.0j, rin_st26)
                cout_p_st26, rout_p_st26 = _invert_circle_st26(0.0j, rout_st26)
                necklace_p_st26 = [
                    _invert_circle_st26((2.0 * rin_st26) * cmath.exp(1.0j * (th0_st26 + (k_s * math.pi / 3.0))), rin_st26)
                    for k_s in range(6)
                ]
                tang_st26_err = 0.0
                for k_s in range(6):
                    ck_p, rk_p = necklace_p_st26[k_s]
                    cn_p, rn_p = necklace_p_st26[(k_s + 1) % 6]
                    tang_st26_err += (
                        abs(abs(ck_p - cin_p_st26) - (rk_p + rin_p_st26))
                        + abs(abs(ck_p - cout_p_st26) - (rout_p_st26 - rk_p))
                        + abs(abs(ck_p - cn_p) - (rk_p + rn_p))
                    ) / rin_st26
                d_inout_p_st26 = abs(cout_p_st26 - cin_p_st26)
                cos_inv_st26 = ((rout_p_st26 * rout_p_st26) + (rin_p_st26 * rin_p_st26) - (d_inout_p_st26 * d_inout_p_st26)) / (
                    2.0 * rout_p_st26 * rin_p_st26
                )
                coxeter_st26_err = abs(cos_inv_st26 - ((rout_st26 * rout_st26 + rin_st26 * rin_st26) / (2.0 * rout_st26 * rin_st26)))
                steiner_inversive_porism_errs.append(float(tang_st26_err + coxeter_st26_err))
                # Faisceau de Cercles Coaxiaux à Points Limites de Poncelet (1822, Traité des propriétés projectives des figures)
                # & Dualité d'Orthogonalité de l'Axe Radical de Gaspard Monge / Jakob Steiner (1826) :
                # pour deux cercles extérieurs C_1(O_1, r_1) et C_2(O_2, r_2) sur l'axe réel (O_1 = 0, O_2 = d_cx > r_1 + r_2),
                # l'abscisse du pied de l'axe radical est x_rad = (d_cx^2 + r_1^2 - r_2^2)/(2*d_cx), la distance aux deux points limites
                # de Poncelet L_+, L_- est a_lim = sqrt(x_rad^2 - r_1^2) (avec Pow(L_+/-, C_1) == Pow(L_+/-, C_2) == 0 pour les cercles de rayon nul x_rad +/- a_lim),
                # et tout cercle orthogonal centré en P = x_rad + i*y_p sur l'axe radical de rayon R_p = sqrt(a_lim^2 + y_p^2) passe exactement par L_+ et L_-
                # et coupe orthogonalement C_1 et C_2 (|P - O_k|^2 == R_p^2 + r_k^2, k = 1, 2) tout en divisant harmoniquement (O_1, O_2; L_-, L_+) si r_2 = 0 :
                r1_cx = 0.35 * (wf + hf) + 0.5
                r2_cx = 0.28 * (ws + hs) + 0.4
                d_cx = r1_cx + r2_cx + 0.65 * (wf + ws) + 1.2
                x_rad_cx = ((d_cx * d_cx) + (r1_cx * r1_cx) - (r2_cx * r2_cx)) / (2.0 * d_cx)
                a_lim_sq_cx = (x_rad_cx * x_rad_cx) - (r1_cx * r1_cx)
                a_lim_cx = math.sqrt(max(0.0, a_lim_sq_cx))
                lp_cx = x_rad_cx + a_lim_cx
                lm_cx = x_rad_cx - a_lim_cx
                yp_cx = 0.45 * (hf + hs) + 0.7
                rp_sq_cx = a_lim_sq_cx + (yp_cx * yp_cx)
                d1_sq_cx = (x_rad_cx * x_rad_cx) + (yp_cx * yp_cx)
                d2_sq_cx = ((d_cx - x_rad_cx) ** 2) + (yp_cx * yp_cx)
                coaxial_circle_pencil_radical_axis_errs.append(
                    float(
                        (
                            abs(d1_sq_cx - (rp_sq_cx + (r1_cx * r1_cx)))
                            + abs(d2_sq_cx - (rp_sq_cx + (r2_cx * r2_cx)))
                            + abs(((d_cx - x_rad_cx) ** 2 - (r2_cx * r2_cx)) - a_lim_sq_cx)
                            + abs(((lp_cx - x_rad_cx) ** 2 + (yp_cx * yp_cx)) - rp_sq_cx)
                            + abs(((lm_cx - x_rad_cx) ** 2 + (yp_cx * yp_cx)) - rp_sq_cx)
                        )
                        / (d_cx * d_cx)
                    )
                )
                # Cercle de Lieu d'Apollonius de Perga (~200 av. J.-C., Des Lieux Plans Livre II) & Dualité d'Inversion Harmonique de Poncelet (1822) :
                # pour deux foyers z_A et z_B dans C et un rapport k_ap > 1, le lieu |z - z_A| == k_ap * |z - z_B| est le cercle de centre
                # O_ap = (k_ap^2 * z_B - z_A)/(k_ap^2 - 1) et rayon R_ap = (k_ap / (k_ap^2 - 1))*|z_A - z_B|, qui coupe la droite (AB) aux conjugués
                # harmoniques D_in = (z_A + k_ap*z_B)/(1 + k_ap) et D_ex = (k_ap*z_B - z_A)/(k_ap - 1) (birapport (z_A, z_B; D_in, D_ex) == -1),
                # et z_A, z_B sont exactement inverses par rapport à ce cercle : (z_A - O_ap)*conj(z_B - O_ap) == R_ap^2 :
                za_ap = complex(0.15 * wf, -0.20 * hf)
