                cr_ap = ((za_ap - din_ap) * (zb_ap - dex_ap)) / ((za_ap - dex_ap) * (zb_ap - din_ap))
                inv_prod_ap = (za_ap - o_ap) * ((zb_ap - o_ap).conjugate())
                ratio_ap_err = 0.0
